window.TOPICS=[{"id": "t1", "slug": "deen-aur-firqe", "title": "The Deen of Islam and Sects", "num": "1"}, {"id": "t2", "slug": "imamon-ki-haisiyat", "title": "The Shari Status of the Imams", "num": "2"}, {"id": "t3", "slug": "ikhtilaf-ki-wajah", "title": "The Root Cause of Disagreements", "num": "3"}, {"id": "t4", "slug": "maslaki-hatdharmi", "title": "Stubbornness on a Sectarian Creed", "num": "4"}, {"id": "t5", "slug": "ulama-ka-kirdar", "title": "The Role of Scholars in the Rise of Sects", "num": "5"}, {"id": "t6", "slug": "qaumon-ki-barbadi", "title": "The Real Cause of the Decline and Ruin of Nations", "num": "6"}, {"id": "t7", "slug": "ahle-kitab-ka-naqsha", "title": "Today's Ummah on the Pattern of the People of the Book", "num": "7"}, {"id": "t8", "slug": "firqa-parasti-se-bachao", "title": "Means of Protection from Sectarianism", "num": "8"}, {"id": "t9", "slug": "tazkiya-e-nafs", "title": "Purification of the Soul (Tazkiyah)", "num": "9"}];
window.REF={"Q:3:103": {"l": "Surah Aal-i-Imraan, 3:103", "u": "https://quran.com/3/103", "ar": "وَٱعْتَصِمُوا۟ بِحَبْلِ ٱللَّهِ جَمِيعًۭا وَلَا تَفَرَّقُوا۟ ۚ وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ إِذْ كُنتُمْ أَعْدَآءًۭ فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُم بِنِعْمَتِهِۦٓ إِخْوَٰنًۭا وَكُنتُمْ عَلَىٰ شَفَا حُفْرَةٍۢ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنْهَا ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَهْتَدُونَ ﴿١٠٣﴾", "tr": "And hold firmly to the rope of Allah all together and do not become divided. And remember the favor of Allah upon you - when you were enemies and He brought your hearts together and you became, by His favor, brothers. And you were on the edge of a pit of the Fire, and He saved you from it. Thus does Allah make clear to you His verses that you may be guided. (103)", "a": "deen-aur-firqe.html#q-3-103"}, "H:bukhari:3461": {"l": "Sahih al-Bukhari, Hadith 3461", "u": "https://sunnah.com/bukhari:3461", "t": "Convey from me, even one verse", "k": "بَلِّغُوا عَنِّي وَلَوْ آيَةً", "a": "imamon-ki-haisiyat.html#h-bukhari-3461"}, "H:muslim:1840a": {"l": "Sahih Muslim, Hadith 1840", "u": "https://sunnah.com/muslim:1840a", "t": "No obedience in disobedience to Allah (Sahih Muslim)", "k": "لاَ طَاعَةَ فِي مَعْصِيَةِ اللَّهِ إِنَّمَا الطَّاعَةُ فِي الْمَعْرُوفِ", "a": "imamon-ki-haisiyat.html#h-muslim-1840a"}, "Q:2:166-167": {"l": "Surah Al-Baqara, 2:166-167", "u": "https://quran.com/2/166-167", "ar": "إِذْ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُوا۟ مِنَ ٱلَّذِينَ ٱتَّبَعُوا۟ وَرَأَوُا۟ ٱلْعَذَابَ وَتَقَطَّعَتْ بِهِمُ ٱلْأَسْبَابُ ﴿١٦٦﴾ وَقَالَ ٱلَّذِينَ ٱتَّبَعُوا۟ لَوْ أَنَّ لَنَا كَرَّةًۭ فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُوا۟ مِنَّا ۗ كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعْمَٰلَهُمْ حَسَرَٰتٍ عَلَيْهِمْ ۖ وَمَا هُم بِخَٰرِجِينَ مِنَ ٱلنَّارِ ﴿١٦٧﴾", "tr": "[And they should consider that] when those who have been followed disassociate themselves from those who followed [them], and they [all] see the punishment, and cut off from them are the ties [of relationship], (166) Those who followed will say, \"If only we had another turn [at worldly life] so we could disassociate ourselves from them as they have disassociated themselves from us.\" Thus will Allah show them their deeds as regrets upon them. And they are never to emerge from the Fire. (167)", "a": "imamon-ki-haisiyat.html#q-2-166-167"}, "H:muslim:1688a": {"l": "Sahih Muslim, Hadith 1688", "u": "https://sunnah.com/muslim:1688a", "t": "The case of the Makhzumi woman (Sahih Muslim)", "k": "إِنَّمَا أَهْلَكَ الَّذِينَ قَبْلَكُمْ أَنَّهُمْ كَانُوا إِذَا سَرَقَ فِيهِمُ الشَّرِيفُ تَرَكُوهُ", "a": "qaumon-ki-barbadi.html#h-muslim-1688a"}, "H:bukhari:6502": {"l": "Sahih al-Bukhari, Hadith 6502", "u": "https://sunnah.com/bukhari:6502", "t": "Hadith qudsi: nearness through obligatory and voluntary deeds", "k": "وَمَا يَزَالُ عَبْدِي يَتَقَرَّبُ إِلَىَّ بِالنَّوَافِلِ حَتَّى أُحِبَّهُ", "a": "tazkiya-e-nafs.html#h-bukhari-6502"}, "H:bukhari:100": {"l": "Sahih al-Bukhari, Hadith 100", "u": "https://sunnah.com/bukhari:100", "t": "Knowledge taken with the scholars, and ignorant leaders", "k": "وَلَكِنْ يَقْبِضُ الْعِلْمَ بِقَبْضِ الْعُلَمَاءِ … اتَّخَذَ النَّاسُ رُءُوسًا جُهَّالاً فَسُئِلُوا، فَأَفْتَوْا بِغَيْرِ عِلْمٍ، فَضَلُّوا وَأَضَلُّوا", "a": "ulama-ka-kirdar.html#h-bukhari-100"}, "H:bukhari:6103": {"l": "Sahih al-Bukhari, Hadith 6103", "u": "https://sunnah.com/bukhari:6103", "t": "Calling one's brother «O disbeliever»", "k": "إِذَا قَالَ الرَّجُلُ لأَخِيهِ يَا كَافِرُ فَقَدْ بَاءَ بِهِ أَحَدُهُمَا", "a": "firqa-parasti-se-bachao.html#h-bukhari-6103"}, "H:bukhari:2442": {"l": "Sahih al-Bukhari, Hadith 2442", "u": "https://sunnah.com/bukhari:2442", "t": "The Muslim is the brother of the Muslim", "k": "الْمُسْلِمُ أَخُو الْمُسْلِمِ، لاَ يَظْلِمُهُ وَلاَ يُسْلِمُهُ", "a": "firqa-parasti-se-bachao.html#h-bukhari-2442"}, "Q:3:7": {"l": "Surah Aal-i-Imraan, 3:7", "u": "https://quran.com/3/7", "ar": "هُوَ ٱلَّذِىٓ أَنزَلَ عَلَيْكَ ٱلْكِتَٰبَ مِنْهُ ءَايَٰتٌۭ مُّحْكَمَٰتٌ هُنَّ أُمُّ ٱلْكِتَٰبِ وَأُخَرُ مُتَشَٰبِهَٰتٌۭ ۖ فَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِمْ زَيْغٌۭ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنْهُ ٱبْتِغَآءَ ٱلْفِتْنَةِ وَٱبْتِغَآءَ تَأْوِيلِهِۦ ۗ وَمَا يَعْلَمُ تَأْوِيلَهُۥٓ إِلَّا ٱللَّهُ ۗ وَٱلرَّٰسِخُونَ فِى ٱلْعِلْمِ يَقُولُونَ ءَامَنَّا بِهِۦ كُلٌّۭ مِّنْ عِندِ رَبِّنَا ۗ وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَٰبِ ﴿٧﴾", "tr": "It is He who has sent down to you, [O Muhammad], the Book; in it are verses [that are] precise - they are the foundation of the Book - and others unspecific. As for those in whose hearts is deviation [from truth], they will follow that of it which is unspecific, seeking discord and seeking an interpretation [suitable to them]. And no one knows its [true] interpretation except Allah. But those firm in knowledge say, \"We believe in it. All [of it] is from our Lord.\" And no one will be reminded except those of understanding. (7)", "a": "ikhtilaf-ki-wajah.html#q-3-7"}, "Q:3:105": {"l": "Surah Aal-i-Imraan, 3:105", "u": "https://quran.com/3/105", "ar": "وَلَا تَكُونُوا۟ كَٱلَّذِينَ تَفَرَّقُوا۟ وَٱخْتَلَفُوا۟ مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْبَيِّنَٰتُ ۚ وَأُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ عَظِيمٌۭ ﴿١٠٥﴾", "tr": "And do not be like the ones who became divided and differed after the clear proofs had come to them. And those will have a great punishment. (105)", "a": "deen-aur-firqe.html#q-3-105"}, "H:muslim:1905a": {"l": "Sahih Muslim, Hadith 1905", "u": "https://sunnah.com/muslim:1905a", "t": "The one who learned knowledge for show", "k": "وَلَكِنَّكَ تَعَلَّمْتَ الْعِلْمَ لِيُقَالَ عَالِمٌ", "a": "ulama-ka-kirdar.html#h-muslim-1905a"}, "H:muslim:1716a": {"l": "Sahih Muslim, Hadith 1716", "u": "https://sunnah.com/muslim:1716a", "t": "Reward even for error in ijtihad (Sahih Muslim)", "k": "وَإِذَا حَكَمَ فَاجْتَهَدَ ثُمَّ أَخْطَأَ فَلَهُ أَجْرٌ", "a": "imamon-ki-haisiyat.html#h-muslim-1716a"}, "H:bukhari:4485": {"l": "Sahih al-Bukhari, Hadith 4485", "u": "https://sunnah.com/bukhari:4485", "t": "Neither believe nor deny the People of the Book", "k": "لاَ تُصَدِّقُوا أَهْلَ الْكِتَابِ وَلاَ تُكَذِّبُوهُمْ", "a": "ahle-kitab-ka-naqsha.html#h-bukhari-4485"}, "Q:30:41": {"l": "Surah Ar-Room, 30:41", "u": "https://quran.com/30/41", "ar": "ظَهَرَ ٱلْفَسَادُ فِى ٱلْبَرِّ وَٱلْبَحْرِ بِمَا كَسَبَتْ أَيْدِى ٱلنَّاسِ لِيُذِيقَهُم بَعْضَ ٱلَّذِى عَمِلُوا۟ لَعَلَّهُمْ يَرْجِعُونَ ﴿٤١﴾", "tr": "Corruption has appeared throughout the land and sea by [reason of] what the hands of people have earned so He may let them taste part of [the consequence of] what they have done that perhaps they will return [to righteousness]. (41)", "a": "qaumon-ki-barbadi.html#q-30-41"}, "Q:3:104": {"l": "Surah Aal-i-Imraan, 3:104", "u": "https://quran.com/3/104", "ar": "وَلْتَكُن مِّنكُمْ أُمَّةٌۭ يَدْعُونَ إِلَى ٱلْخَيْرِ وَيَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ ۚ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ ﴿١٠٤﴾", "tr": "And let there be [arising] from you a nation inviting to [all that is] good, enjoining what is right and forbidding what is wrong, and those will be the successful. (104)", "a": "firqa-parasti-se-bachao.html#q-3-104"}, "Q:5:3": {"l": "Surah Al-Maaida, 5:3", "u": "https://quran.com/5/3", "ar": "حُرِّمَتْ عَلَيْكُمُ ٱلْمَيْتَةُ وَٱلدَّمُ وَلَحْمُ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ وَٱلْمُنْخَنِقَةُ وَٱلْمَوْقُوذَةُ وَٱلْمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسْتَقْسِمُوا۟ بِٱلْأَزْلَٰمِ ۚ ذَٰلِكُمْ فِسْقٌ ۗ ٱلْيَوْمَ يَئِسَ ٱلَّذِينَ كَفَرُوا۟ مِن دِينِكُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِ ۚ ٱلْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِى وَرَضِيتُ لَكُمُ ٱلْإِسْلَٰمَ دِينًۭا ۚ فَمَنِ ٱضْطُرَّ فِى مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍۢ لِّإِثْمٍۢ ۙ فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ ﴿٣﴾", "tr": "Prohibited to you are dead animals, blood, the flesh of swine, and that which has been dedicated to other than Allah, and [those animals] killed by strangling or by a violent blow or by a head-long fall or by the goring of horns, and those from which a wild animal has eaten, except what you [are able to] slaughter [before its death], and those which are sacrificed on stone altars, and [prohibited is] that you seek decision through divining arrows. That is grave disobedience. This day those who disbelieve have despaired of [defeating] your religion; so fear them not, but fear Me. This day I have perfected for you your religion and completed My favor upon you and have approved for you Islam as religion. But whoever is forced by severe hunger with no inclination to sin - then indeed, Allah is Forgiving and Merciful. (3)", "a": "deen-aur-firqe.html#q-5-3"}, "Q:3:19": {"l": "Surah Aal-i-Imraan, 3:19", "u": "https://quran.com/3/19", "ar": "إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلْإِسْلَٰمُ ۗ وَمَا ٱخْتَلَفَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۗ وَمَن يَكْفُرْ بِـَٔايَٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ ﴿١٩﴾", "tr": "Indeed, the religion in the sight of Allah is Islam. And those who were given the Scripture did not differ except after knowledge had come to them - out of jealous animosity between themselves. And whoever disbelieves in the verses of Allah, then indeed, Allah is swift in [taking] account. (19)", "a": "deen-aur-firqe.html#q-3-19"}, "H:muslim:2586a": {"l": "Sahih Muslim, Hadith 2586", "u": "https://sunnah.com/muslim:2586a", "t": "Believers are like one body (Sahih Muslim)", "k": "مَثَلُ الْمُؤْمِنِينَ فِي تَوَادِّهِمْ وَتَرَاحُمِهِمْ وَتَعَاطُفِهِمْ مَثَلُ الْجَسَدِ", "a": "deen-aur-firqe.html#h-muslim-2586a"}, "Q:49:9": {"l": "Surah Al-Hujuraat, 49:9", "u": "https://quran.com/49/9", "ar": "وَإِن طَآئِفَتَانِ مِنَ ٱلْمُؤْمِنِينَ ٱقْتَتَلُوا۟ فَأَصْلِحُوا۟ بَيْنَهُمَا ۖ فَإِنۢ بَغَتْ إِحْدَىٰهُمَا عَلَى ٱلْأُخْرَىٰ فَقَٰتِلُوا۟ ٱلَّتِى تَبْغِى حَتَّىٰ تَفِىٓءَ إِلَىٰٓ أَمْرِ ٱللَّهِ ۚ فَإِن فَآءَتْ فَأَصْلِحُوا۟ بَيْنَهُمَا بِٱلْعَدْلِ وَأَقْسِطُوٓا۟ ۖ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ ﴿٩﴾", "tr": "And if two factions among the believers should fight, then make settlement between the two. But if one of them oppresses the other, then fight against the one that oppresses until it returns to the ordinance of Allah. And if it returns, then make settlement between them in justice and act justly. Indeed, Allah loves those who act justly. (9)", "a": "firqa-parasti-se-bachao.html#q-49-9"}, "Q:26:89": {"l": "Surah Ash-Shu'araa, 26:89", "u": "https://quran.com/26/89", "ar": "إِلَّا مَنْ أَتَى ٱللَّهَ بِقَلْبٍۢ سَلِيمٍۢ ﴿٨٩﴾", "tr": "But only one who comes to Allah with a sound heart.\" (89)", "a": "tazkiya-e-nafs.html#q-26-88-89"}, "Q:11:117": {"l": "Surah Hud, 11:117", "u": "https://quran.com/11/117", "ar": "وَمَا كَانَ رَبُّكَ لِيُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍۢ وَأَهْلُهَا مُصْلِحُونَ ﴿١١٧﴾", "tr": "And your Lord would not have destroyed the cities unjustly while their people were reformers. (117)", "a": "qaumon-ki-barbadi.html#q-11-117"}, "Q:4:65": {"l": "Surah An-Nisaa, 4:65", "u": "https://quran.com/4/65", "ar": "فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا۟ فِىٓ أَنفُسِهِمْ حَرَجًۭا مِّمَّا قَضَيْتَ وَيُسَلِّمُوا۟ تَسْلِيمًۭا ﴿٦٥﴾", "tr": "But no, by your Lord, they will not [truly] believe until they make you, [O Muhammad], judge concerning that over which they dispute among themselves and then find within themselves no discomfort from what you have judged and submit in [full, willing] submission. (65)", "a": "imamon-ki-haisiyat.html#q-4-65"}, "H:bukhari:50": {"l": "Sahih al-Bukhari, Hadith 50", "u": "https://sunnah.com/bukhari:50", "t": "Ihsan: as though you see Allah", "k": "أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ", "a": "tazkiya-e-nafs.html#h-bukhari-50"}, "Q:57:16": {"l": "Surah Al-Hadid, 57:16", "u": "https://quran.com/57/16", "ar": "۞ أَلَمْ يَأْنِ لِلَّذِينَ ءَامَنُوٓا۟ أَن تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلْحَقِّ وَلَا يَكُونُوا۟ كَٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ مِن قَبْلُ فَطَالَ عَلَيْهِمُ ٱلْأَمَدُ فَقَسَتْ قُلُوبُهُمْ ۖ وَكَثِيرٌۭ مِّنْهُمْ فَٰسِقُونَ ﴿١٦﴾", "tr": "Has the time not come for those who have believed that their hearts should become humbly submissive at the remembrance of Allah and what has come down of the truth? And let them not be like those who were given the Scripture before, and a long period passed over them, so their hearts hardened; and many of them are defiantly disobedient. (16)", "a": "ahle-kitab-ka-naqsha.html#q-57-16"}, "Q:24:51": {"l": "Surah An-Noor, 24:51", "u": "https://quran.com/24/51", "ar": "إِنَّمَا كَانَ قَوْلَ ٱلْمُؤْمِنِينَ إِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ أَن يَقُولُوا۟ سَمِعْنَا وَأَطَعْنَا ۚ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ ﴿٥١﴾", "tr": "The only statement of the [true] believers when they are called to Allah and His Messenger to judge between them is that they say, \"We hear and we obey.\" And those are the successful. (51)", "a": "imamon-ki-haisiyat.html#q-24-51-52"}, "Q:33:36": {"l": "Surah Al-Ahzaab, 33:36", "u": "https://quran.com/33/36", "ar": "وَمَا كَانَ لِمُؤْمِنٍۢ وَلَا مُؤْمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمْرًا أَن يَكُونَ لَهُمُ ٱلْخِيَرَةُ مِنْ أَمْرِهِمْ ۗ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدْ ضَلَّ ضَلَٰلًۭا مُّبِينًۭا ﴿٣٦﴾", "tr": "It is not for a believing man or a believing woman, when Allah and His Messenger have decided a matter, that they should [thereafter] have any choice about their affair. And whoever disobeys Allah and His Messenger has certainly strayed into clear error. (36)", "a": "imamon-ki-haisiyat.html#q-33-36"}, "Q:24:49": {"l": "Surah An-Noor, 24:49", "u": "https://quran.com/24/49", "ar": "وَإِن يَكُن لَّهُمُ ٱلْحَقُّ يَأْتُوٓا۟ إِلَيْهِ مُذْعِنِينَ ﴿٤٩﴾", "tr": "But if the right is theirs, they come to him in prompt obedience. (49)", "a": "maslaki-hatdharmi.html#q-24-48-51"}, "Q:49:12": {"l": "Surah Al-Hujuraat, 49:12", "u": "https://quran.com/49/12", "ar": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱجْتَنِبُوا۟ كَثِيرًۭا مِّنَ ٱلظَّنِّ إِنَّ بَعْضَ ٱلظَّنِّ إِثْمٌۭ ۖ وَلَا تَجَسَّسُوا۟ وَلَا يَغْتَب بَّعْضُكُم بَعْضًا ۚ أَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًۭا فَكَرِهْتُمُوهُ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ تَوَّابٌۭ رَّحِيمٌۭ ﴿١٢﴾", "tr": "O you who have believed, avoid much [negative] assumption. Indeed, some assumption is sin. And do not spy or backbite each other. Would one of you like to eat the flesh of his brother when dead? You would detest it. And fear Allah; indeed, Allah is Accepting of repentance and Merciful. (12)", "a": "tazkiya-e-nafs.html#q-49-12"}, "Q:91:7-10": {"l": "Surah Ash-Shams, 91:7-10", "u": "https://quran.com/91/7-10", "ar": "وَنَفْسٍۢ وَمَا سَوَّىٰهَا ﴿٧﴾ فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا ﴿٨﴾ قَدْ أَفْلَحَ مَن زَكَّىٰهَا ﴿٩﴾ وَقَدْ خَابَ مَن دَسَّىٰهَا ﴿١٠﴾", "tr": "And [by] the soul and He who proportioned it (7) And inspired it [with discernment of] its wickedness and its righteousness, (8) He has succeeded who purifies it, (9) And he has failed who instills it [with corruption]. (10)", "a": "tazkiya-e-nafs.html#q-91-7-10"}, "Q:13:11": {"l": "Surah Ar-Ra'd, 13:11", "u": "https://quran.com/13/11", "ar": "لَهُۥ مُعَقِّبَٰتٌۭ مِّنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ يَحْفَظُونَهُۥ مِنْ أَمْرِ ٱللَّهِ ۗ إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ ۗ وَإِذَآ أَرَادَ ٱللَّهُ بِقَوْمٍۢ سُوٓءًۭا فَلَا مَرَدَّ لَهُۥ ۚ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ ﴿١١﴾", "tr": "For each one are successive [angels] before and behind him who protect him by the decree of Allah. Indeed, Allah will not change the condition of a people until they change what is in themselves. And when Allah intends for a people ill, there is no repelling it. And there is not for them besides Him any patron. (11)", "a": "qaumon-ki-barbadi.html#q-13-11"}, "Q:17:16": {"l": "Surah Al-Israa, 17:16", "u": "https://quran.com/17/16", "ar": "وَإِذَآ أَرَدْنَآ أَن نُّهْلِكَ قَرْيَةً أَمَرْنَا مُتْرَفِيهَا فَفَسَقُوا۟ فِيهَا فَحَقَّ عَلَيْهَا ٱلْقَوْلُ فَدَمَّرْنَٰهَا تَدْمِيرًۭا ﴿١٦﴾", "tr": "And when We intend to destroy a city, We command its affluent but they defiantly disobey therein; so the word comes into effect upon it, and We destroy it with [complete] destruction. (16)", "a": "qaumon-ki-barbadi.html#q-17-16"}, "Q:53:32": {"l": "Surah An-Najm, 53:32", "u": "https://quran.com/53/32", "ar": "ٱلَّذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ إِلَّا ٱللَّمَمَ ۚ إِنَّ رَبَّكَ وَٰسِعُ ٱلْمَغْفِرَةِ ۚ هُوَ أَعْلَمُ بِكُمْ إِذْ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَإِذْ أَنتُمْ أَجِنَّةٌۭ فِى بُطُونِ أُمَّهَٰتِكُمْ ۖ فَلَا تُزَكُّوٓا۟ أَنفُسَكُمْ ۖ هُوَ أَعْلَمُ بِمَنِ ٱتَّقَىٰٓ ﴿٣٢﴾", "tr": "Those who avoid the major sins and immoralities, only [committing] slight ones. Indeed, your Lord is vast in forgiveness. He was most knowing of you when He produced you from the earth and when you were fetuses in the wombs of your mothers. So do not claim yourselves to be pure; He is most knowing of who fears Him. (32)", "a": "tazkiya-e-nafs.html#q-53-32"}, "Q:62:5": {"l": "Surah Al-Jumu'a, 62:5", "u": "https://quran.com/62/5", "ar": "مَثَلُ ٱلَّذِينَ حُمِّلُوا۟ ٱلتَّوْرَىٰةَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ ٱلْحِمَارِ يَحْمِلُ أَسْفَارًۢا ۚ بِئْسَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِ ٱللَّهِ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ ﴿٥﴾", "tr": "The example of those who were entrusted with the Torah and then did not take it on is like that of a donkey who carries volumes [of books]. Wretched is the example of the people who deny the signs of Allah. And Allah does not guide the wrongdoing people. (5)", "a": "ulama-ka-kirdar.html#q-62-5"}, "Q:45:23": {"l": "Surah Al-Jaathiya, 45:23", "u": "https://quran.com/45/23", "ar": "أَفَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلْمٍۢ وَخَتَمَ عَلَىٰ سَمْعِهِۦ وَقَلْبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةًۭ فَمَن يَهْدِيهِ مِنۢ بَعْدِ ٱللَّهِ ۚ أَفَلَا تَذَكَّرُونَ ﴿٢٣﴾", "tr": "Have you seen he who has taken as his god his [own] desire, and Allah has sent him astray due to knowledge and has set a seal upon his hearing and his heart and put over his vision a veil? So who will guide him after Allah? Then will you not be reminded? (23)", "a": "ikhtilaf-ki-wajah.html#q-45-23"}, "H:bukhari:7144": {"l": "Sahih al-Bukhari, Hadith 7144", "u": "https://sunnah.com/bukhari:7144", "t": "Listening and obeying, unless commanded to sin", "k": "السَّمْعُ وَالطَّاعَةُ عَلَى الْمَرْءِ الْمُسْلِمِ، فِيمَا أَحَبَّ وَكَرِهَ، مَا لَمْ يُؤْمَرْ بِمَعْصِيَةٍ، فَإِذَا أُمِرَ بِمَعْصِيَةٍ فَلاَ سَمْعَ وَلاَ طَاعَةَ", "a": "imamon-ki-haisiyat.html#h-bukhari-7144"}, "H:muslim:60b": {"l": "Sahih Muslim, Hadith 60", "u": "https://sunnah.com/muslim:60b", "t": "Otherwise it returns to the one who said it", "k": "فَقَدْ بَاءَ بِهَا أَحَدُهُمَا إِنْ كَانَ كَمَا قَالَ وَإِلاَّ رَجَعَتْ عَلَيْهِ", "a": "firqa-parasti-se-bachao.html#h-muslim-60b"}, "Q:26:88-89": {"l": "Surah Ash-Shu'araa, 26:88-89", "u": "https://quran.com/26/88-89", "ar": "يَوْمَ لَا يَنفَعُ مَالٌۭ وَلَا بَنُونَ ﴿٨٨﴾ إِلَّا مَنْ أَتَى ٱللَّهَ بِقَلْبٍۢ سَلِيمٍۢ ﴿٨٩﴾", "tr": "The Day when there will not benefit [anyone] wealth or children (88) But only one who comes to Allah with a sound heart.\" (89)", "a": "tazkiya-e-nafs.html#q-26-88-89"}, "H:muslim:2668": {"l": "Sahih Muslim, Hadith 2668", "u": "https://sunnah.com/muslim:2668", "t": "The fiercely quarrelsome is hateful to Allah (Sahih Muslim)", "k": "إِنَّ أَبْغَضَ الرِّجَالِ إِلَى اللَّهِ الأَلَدُّ الْخَصِمُ", "a": "maslaki-hatdharmi.html#h-muslim-2668"}, "Q:9:34": {"l": "Surah At-Tawba, 9:34", "u": "https://quran.com/9/34", "ar": "۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ كَثِيرًۭا مِّنَ ٱلْأَحْبَارِ وَٱلرُّهْبَانِ لَيَأْكُلُونَ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ ۗ وَٱلَّذِينَ يَكْنِزُونَ ٱلذَّهَبَ وَٱلْفِضَّةَ وَلَا يُنفِقُونَهَا فِى سَبِيلِ ٱللَّهِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍۢ ﴿٣٤﴾", "tr": "O you who have believed, indeed many of the scholars and the monks devour the wealth of people unjustly and avert [them] from the way of Allah. And those who hoard gold and silver and spend it not in the way of Allah - give them tidings of a painful punishment. (34)", "a": "ulama-ka-kirdar.html#q-9-34"}, "H:muslim:2961a": {"l": "Sahih Muslim, Hadith 2961", "u": "https://sunnah.com/muslim:2961a", "t": "The race for the world that destroyed those before (Sahih Muslim)", "k": "فَتَنَافَسُوهَا كَمَا تَنَافَسُوهَا وَتُهْلِكَكُمْ كَمَا أَهْلَكَتْهُمْ", "a": "qaumon-ki-barbadi.html#h-muslim-2961a"}, "Q:2:174": {"l": "Surah Al-Baqara, 2:174", "u": "https://quran.com/2/174", "ar": "إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلْكِتَٰبِ وَيَشْتَرُونَ بِهِۦ ثَمَنًۭا قَلِيلًا ۙ أُو۟لَٰٓئِكَ مَا يَأْكُلُونَ فِى بُطُونِهِمْ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوْمَ ٱلْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ ﴿١٧٤﴾", "tr": "Indeed, they who conceal what Allah has sent down of the Book and exchange it for a small price - those consume not into their bellies except the Fire. And Allah will not speak to them on the Day of Resurrection, nor will He purify them. And they will have a painful punishment. (174)", "a": "ulama-ka-kirdar.html#q-2-174-175"}, "Q:10:78": {"l": "Surah Yunus, 10:78", "u": "https://quran.com/10/78", "ar": "قَالُوٓا۟ أَجِئْتَنَا لِتَلْفِتَنَا عَمَّا وَجَدْنَا عَلَيْهِ ءَابَآءَنَا وَتَكُونَ لَكُمَا ٱلْكِبْرِيَآءُ فِى ٱلْأَرْضِ وَمَا نَحْنُ لَكُمَا بِمُؤْمِنِينَ ﴿٧٨﴾", "tr": "They said, \"Have you come to us to turn us away from that upon which we found our fathers and so that you two may have grandeur in the land? And we are not believers in you.\" (78)", "a": "maslaki-hatdharmi.html#q-10-78"}, "H:bukhari:391": {"l": "Sahih al-Bukhari, Hadith 391", "u": "https://sunnah.com/bukhari:391", "t": "Whoever prays our prayer and faces our qiblah is a Muslim", "k": "مَنْ صَلَّى صَلاَتَنَا، وَاسْتَقْبَلَ قِبْلَتَنَا، وَأَكَلَ ذَبِيحَتَنَا، فَذَلِكَ الْمُسْلِمُ", "a": "firqa-parasti-se-bachao.html#h-bukhari-391"}, "Q:4:171": {"l": "Surah An-Nisaa, 4:171", "u": "https://quran.com/4/171", "ar": "يَٰٓأَهْلَ ٱلْكِتَٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ وَلَا تَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ ۚ إِنَّمَا ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلْقَىٰهَآ إِلَىٰ مَرْيَمَ وَرُوحٌۭ مِّنْهُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۖ وَلَا تَقُولُوا۟ ثَلَٰثَةٌ ۚ ٱنتَهُوا۟ خَيْرًۭا لَّكُمْ ۚ إِنَّمَا ٱللَّهُ إِلَٰهٌۭ وَٰحِدٌۭ ۖ سُبْحَٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٌۭ ۘ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَكَفَىٰ بِٱللَّهِ وَكِيلًۭا ﴿١٧١﴾", "tr": "O People of the Scripture, do not commit excess in your religion or say about Allah except the truth. The Messiah, Jesus, the son of Mary, was but a messenger of Allah and His word which He directed to Mary and a soul [created at a command] from Him. So believe in Allah and His messengers. And do not say, \"Three\"; desist - it is better for you. Indeed, Allah is but one God. Exalted is He above having a son. To Him belongs whatever is in the heavens and whatever is on the earth. And sufficient is Allah as Disposer of affairs. (171)", "a": "ahle-kitab-ka-naqsha.html#q-4-171"}, "H:bukhari:7137": {"l": "Sahih al-Bukhari, Hadith 7137", "u": "https://sunnah.com/bukhari:7137", "t": "Whoever obeys me obeys Allah", "k": "مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ، وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ، وَمَنْ أَطَاعَ أَمِيرِي فَقَدْ أَطَاعَنِي", "a": "imamon-ki-haisiyat.html#h-bukhari-7137"}, "Q:4:94": {"l": "Surah An-Nisaa, 4:94", "u": "https://quran.com/4/94", "ar": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا ضَرَبْتُمْ فِى سَبِيلِ ٱللَّهِ فَتَبَيَّنُوا۟ وَلَا تَقُولُوا۟ لِمَنْ أَلْقَىٰٓ إِلَيْكُمُ ٱلسَّلَٰمَ لَسْتَ مُؤْمِنًۭا تَبْتَغُونَ عَرَضَ ٱلْحَيَوٰةِ ٱلدُّنْيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةٌۭ ۚ كَذَٰلِكَ كُنتُم مِّن قَبْلُ فَمَنَّ ٱللَّهُ عَلَيْكُمْ فَتَبَيَّنُوٓا۟ ۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًۭا ﴿٩٤﴾", "tr": "O you who have believed, when you go forth [to fight] in the cause of Allah, investigate; and do not say to one who gives you [a greeting of] peace \"You are not a believer,\" aspiring for the goods of worldly life; for with Allah are many acquisitions. You [yourselves] were like that before; then Allah conferred His favor upon you, so investigate. Indeed Allah is ever, with what you do, Acquainted. (94)", "a": "firqa-parasti-se-bachao.html#q-4-94"}, "Q:87:14-15": {"l": "Surah Al-A'laa, 87:14-15", "u": "https://quran.com/87/14-15", "ar": "قَدْ أَفْلَحَ مَن تَزَكَّىٰ ﴿١٤﴾ وَذَكَرَ ٱسْمَ رَبِّهِۦ فَصَلَّىٰ ﴿١٥﴾", "tr": "He has certainly succeeded who purifies himself (14) And mentions the name of his Lord and prays. (15)", "a": "tazkiya-e-nafs.html#q-87-14-15"}, "Q:5:92": {"l": "Surah Al-Maaida, 5:92", "u": "https://quran.com/5/92", "ar": "وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَٱحْذَرُوا۟ ۚ فَإِن تَوَلَّيْتُمْ فَٱعْلَمُوٓا۟ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَٰغُ ٱلْمُبِينُ ﴿٩٢﴾", "tr": "And obey Allah and obey the Messenger and beware. And if you turn away - then know that upon Our Messenger is only [the responsibility for] clear notification. (92)", "a": "imamon-ki-haisiyat.html#q-5-92"}, "Q:7:94-96": {"l": "Surah Al-A'raaf, 7:94-96", "u": "https://quran.com/7/94-96", "ar": "وَمَآ أَرْسَلْنَا فِى قَرْيَةٍۢ مِّن نَّبِىٍّ إِلَّآ أَخَذْنَآ أَهْلَهَا بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَضَّرَّعُونَ ﴿٩٤﴾ ثُمَّ بَدَّلْنَا مَكَانَ ٱلسَّيِّئَةِ ٱلْحَسَنَةَ حَتَّىٰ عَفَوا۟ وَّقَالُوا۟ قَدْ مَسَّ ءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ فَأَخَذْنَٰهُم بَغْتَةًۭ وَهُمْ لَا يَشْعُرُونَ ﴿٩٥﴾ وَلَوْ أَنَّ أَهْلَ ٱلْقُرَىٰٓ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَفَتَحْنَا عَلَيْهِم بَرَكَٰتٍۢ مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ وَلَٰكِن كَذَّبُوا۟ فَأَخَذْنَٰهُم بِمَا كَانُوا۟ يَكْسِبُونَ ﴿٩٦﴾", "tr": "And We sent to no city a prophet [who was denied] except that We seized its people with poverty and hardship that they might humble themselves [to Allah]. (94) Then We exchanged in place of the bad [condition], good, until they increased [and prospered] and said, \"Our fathers [also] were touched with hardship and ease.\" So We seized them suddenly while they did not perceive. (95) And if only the people of the cities had believed and feared Allah, We would have opened upon them blessings from the heaven and the earth; but they denied [the messengers], so We seized them for what they were earning.\" (96)", "a": "qaumon-ki-barbadi.html#q-7-94-96"}, "Q:49:11": {"l": "Surah Al-Hujuraat, 49:11", "u": "https://quran.com/49/11", "ar": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا يَسْخَرْ قَوْمٌۭ مِّن قَوْمٍ عَسَىٰٓ أَن يَكُونُوا۟ خَيْرًۭا مِّنْهُمْ وَلَا نِسَآءٌۭ مِّن نِّسَآءٍ عَسَىٰٓ أَن يَكُنَّ خَيْرًۭا مِّنْهُنَّ ۖ وَلَا تَلْمِزُوٓا۟ أَنفُسَكُمْ وَلَا تَنَابَزُوا۟ بِٱلْأَلْقَٰبِ ۖ بِئْسَ ٱلِٱسْمُ ٱلْفُسُوقُ بَعْدَ ٱلْإِيمَٰنِ ۚ وَمَن لَّمْ يَتُبْ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ ﴿١١﴾", "tr": "O you who have believed, let not a people ridicule [another] people; perhaps they may be better than them; nor let women ridicule [other] women; perhaps they may be better than them. And do not insult one another and do not call each other by [offensive] nicknames. Wretched is the name of disobedience after [one's] faith. And whoever does not repent - then it is those who are the wrongdoers. (11)", "a": "firqa-parasti-se-bachao.html#q-49-11"}, "Q:42:13": {"l": "Surah Ash-Shura, 42:13", "u": "https://quran.com/42/13", "ar": "۞ شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحًۭا وَٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ وَمَا وَصَّيْنَا بِهِۦٓ إِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓ ۖ أَنْ أَقِيمُوا۟ ٱلدِّينَ وَلَا تَتَفَرَّقُوا۟ فِيهِ ۚ كَبُرَ عَلَى ٱلْمُشْرِكِينَ مَا تَدْعُوهُمْ إِلَيْهِ ۚ ٱللَّهُ يَجْتَبِىٓ إِلَيْهِ مَن يَشَآءُ وَيَهْدِىٓ إِلَيْهِ مَن يُنِيبُ ﴿١٣﴾", "tr": "He has ordained for you of religion what He enjoined upon Noah and that which We have revealed to you, [O Muhammad], and what We enjoined upon Abraham and Moses and Jesus - to establish the religion and not be divided therein. Difficult for those who associate others with Allah is that to which you invite them. Allah chooses for Himself whom He wills and guides to Himself whoever turns back [to Him]. (13)", "a": "deen-aur-firqe.html#q-42-13"}, "Q:3:31-32": {"l": "Surah Aal-i-Imraan, 3:31-32", "u": "https://quran.com/3/31-32", "ar": "قُلْ إِن كُنتُمْ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِى يُحْبِبْكُمُ ٱللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ ۗ وَٱللَّهُ غَفُورٌۭ رَّحِيمٌۭ ﴿٣١﴾ قُلْ أَطِيعُوا۟ ٱللَّهَ وَٱلرَّسُولَ ۖ فَإِن تَوَلَّوْا۟ فَإِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْكَٰفِرِينَ ﴿٣٢﴾", "tr": "Say, [O Muhammad], \"If you should love Allah, then follow me, [so] Allah will love you and forgive you your sins. And Allah is Forgiving and Merciful.\" (31) Say, \"Obey Allah and the Messenger.\" But if they turn away - then indeed, Allah does not like the disbelievers. (32)", "a": "imamon-ki-haisiyat.html#q-3-31-32"}, "Q:2:41-42": {"l": "Surah Al-Baqara, 2:41-42", "u": "https://quran.com/2/41-42", "ar": "وَءَامِنُوا۟ بِمَآ أَنزَلْتُ مُصَدِّقًۭا لِّمَا مَعَكُمْ وَلَا تَكُونُوٓا۟ أَوَّلَ كَافِرٍۭ بِهِۦ ۖ وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًۭا قَلِيلًۭا وَإِيَّٰىَ فَٱتَّقُونِ ﴿٤١﴾ وَلَا تَلْبِسُوا۟ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُوا۟ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ ﴿٤٢﴾", "tr": "And believe in what I have sent down confirming that which is [already] with you, and be not the first to disbelieve in it. And do not exchange My signs for a small price, and fear [only] Me. (41) And do not mix the truth with falsehood or conceal the truth while you know [it]. (42)", "a": "ulama-ka-kirdar.html#q-2-41-42"}, "H:bukhari:6425": {"l": "Sahih al-Bukhari, Hadith 6425", "u": "https://sunnah.com/bukhari:6425", "t": "I do not fear poverty for you, but the world spread out", "k": "مَا الْفَقْرَ أَخْشَى عَلَيْكُمْ … فَتَنَافَسُوهَا كَمَا تَنَافَسُوهَا", "a": "qaumon-ki-barbadi.html#h-bukhari-6425"}, "H:muslim:96a": {"l": "Sahih Muslim, Hadith 96", "u": "https://sunnah.com/muslim:96a", "t": "Did you split open his heart?", "k": "أَفَلاَ شَقَقْتَ عَنْ قَلْبِهِ حَتَّى تَعْلَمَ أَقَالَهَا أَمْ لاَ", "a": "firqa-parasti-se-bachao.html#h-muslim-96a"}, "Q:23:71": {"l": "Surah Al-Muminoon, 23:71", "u": "https://quran.com/23/71", "ar": "وَلَوِ ٱتَّبَعَ ٱلْحَقُّ أَهْوَآءَهُمْ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ وَمَن فِيهِنَّ ۚ بَلْ أَتَيْنَٰهُم بِذِكْرِهِمْ فَهُمْ عَن ذِكْرِهِم مُّعْرِضُونَ ﴿٧١﴾", "tr": "But if the Truth had followed their inclinations, the heavens and the earth and whoever is in them would have been ruined. Rather, We have brought them their message, but they, from their message, are turning away. (71)", "a": "ikhtilaf-ki-wajah.html#q-23-71"}, "H:bukhari:6307": {"l": "Sahih al-Bukhari, Hadith 6307", "u": "https://sunnah.com/bukhari:6307", "t": "Seeking forgiveness more than seventy times a day", "k": "إِنِّي لأَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ فِي الْيَوْمِ أَكْثَرَ مِنْ سَبْعِينَ مَرَّةً", "a": "tazkiya-e-nafs.html#h-bukhari-6307"}, "H:muslim:54a": {"l": "Sahih Muslim, Hadith 54", "u": "https://sunnah.com/muslim:54a", "t": "Love one another and spread the greeting", "k": "وَلاَ تُؤْمِنُوا حَتَّى تَحَابُّوا … أَفْشُوا السَّلاَمَ بَيْنَكُمْ", "a": "firqa-parasti-se-bachao.html#h-muslim-54a"}, "H:bukhari:7288": {"l": "Sahih al-Bukhari, Hadith 7288", "u": "https://sunnah.com/bukhari:7288", "t": "Ruin through questions and differing with the prophets", "k": "إِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِسُؤَالِهِمْ وَاخْتِلاَفِهِمْ عَلَى أَنْبِيَائِهِمْ", "a": "ikhtilaf-ki-wajah.html#h-bukhari-7288"}, "Q:59:9": {"l": "Surah Al-Hashr, 59:9", "u": "https://quran.com/59/9", "ar": "وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلْإِيمَٰنَ مِن قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِى صُدُورِهِمْ حَاجَةًۭ مِّمَّآ أُوتُوا۟ وَيُؤْثِرُونَ عَلَىٰٓ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌۭ ۚ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ ﴿٩﴾", "tr": "And [also for] those who were settled in al-Madinah and [adopted] the faith before them. They love those who emigrated to them and find not any want in their breasts of what the emigrants were given but give [them] preference over themselves, even though they are in privation. And whoever is protected from the stinginess of his soul - it is those who will be the successful. (9)", "a": "tazkiya-e-nafs.html#q-59-9"}, "H:bukhari:110": {"l": "Sahih al-Bukhari, Hadith 110", "u": "https://sunnah.com/bukhari:110", "t": "Whoever lies about me deliberately", "k": "وَمَنْ كَذَبَ عَلَىَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ", "a": "ulama-ka-kirdar.html#h-bukhari-110"}, "H:bukhari:48": {"l": "Sahih al-Bukhari, Hadith 48", "u": "https://sunnah.com/bukhari:48", "t": "Abusing a Muslim is wickedness, fighting him disbelief", "k": "سِبَابُ الْمُسْلِمِ فُسُوقٌ، وَقِتَالُهُ كُفْرٌ", "a": "firqa-parasti-se-bachao.html#h-bukhari-48"}, "Q:59:7": {"l": "Surah Al-Hashr, 59:7", "u": "https://quran.com/59/7", "ar": "مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْ أَهْلِ ٱلْقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ كَىْ لَا يَكُونَ دُولَةًۢ بَيْنَ ٱلْأَغْنِيَآءِ مِنكُمْ ۚ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمْ عَنْهُ فَٱنتَهُوا۟ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ ﴿٧﴾", "tr": "And what Allah restored to His Messenger from the people of the towns - it is for Allah and for the Messenger and for [his] near relatives and orphans and the [stranded] traveler - so that it will not be a perpetual distribution among the rich from among you. And whatever the Messenger has given you - take; and what he has forbidden you - refrain from. And fear Allah; indeed, Allah is severe in penalty. (7)", "a": "imamon-ki-haisiyat.html#q-59-7"}, "Q:4:80": {"l": "Surah An-Nisaa, 4:80", "u": "https://quran.com/4/80", "ar": "مَّن يُطِعِ ٱلرَّسُولَ فَقَدْ أَطَاعَ ٱللَّهَ ۖ وَمَن تَوَلَّىٰ فَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ حَفِيظًۭا ﴿٨٠﴾", "tr": "He who obeys the Messenger has obeyed Allah; but those who turn away - We have not sent you over them as a guardian. (80)", "a": "imamon-ki-haisiyat.html#q-4-80"}, "H:bukhari:3476": {"l": "Sahih al-Bukhari, Hadith 3476", "u": "https://sunnah.com/bukhari:3476", "t": "Both of you are right; do not differ", "k": "كِلاَكُمَا مُحْسِنٌ، وَلاَ تَخْتَلِفُوا، فَإِنَّ مَنْ كَانَ قَبْلَكُمُ اخْتَلَفُوا فَهَلَكُوا", "a": "ikhtilaf-ki-wajah.html#h-bukhari-3476"}, "H:bukhari:6066": {"l": "Sahih al-Bukhari, Hadith 6066", "u": "https://sunnah.com/bukhari:6066", "t": "Avoid suspicion, envy and hatred; be brothers", "k": "إِيَّاكُمْ وَالظَّنَّ، فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ … وَلاَ تَحَاسَدُوا، وَلاَ تَبَاغَضُوا، وَلاَ تَدَابَرُوا، وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا", "a": "ikhtilaf-ki-wajah.html#h-bukhari-6066"}, "H:bukhari:481": {"l": "Sahih al-Bukhari, Hadith 481", "u": "https://sunnah.com/bukhari:481", "t": "A believer to a believer is like a building", "k": "إِنَّ الْمُؤْمِنَ لِلْمُؤْمِنِ كَالْبُنْيَانِ، يَشُدُّ بَعْضُهُ بَعْضًا", "a": "deen-aur-firqe.html#h-bukhari-481"}, "Q:7:28": {"l": "Surah Al-A'raaf, 7:28", "u": "https://quran.com/7/28", "ar": "وَإِذَا فَعَلُوا۟ فَٰحِشَةًۭ قَالُوا۟ وَجَدْنَا عَلَيْهَآ ءَابَآءَنَا وَٱللَّهُ أَمَرَنَا بِهَا ۗ قُلْ إِنَّ ٱللَّهَ لَا يَأْمُرُ بِٱلْفَحْشَآءِ ۖ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ ﴿٢٨﴾", "tr": "And when they commit an immorality, they say, \"We found our fathers doing it, and Allah has ordered us to do it.\" Say, \"Indeed, Allah does not order immorality. Do you say about Allah that which you do not know?\" (28)", "a": "maslaki-hatdharmi.html#q-7-28"}, "Q:7:175-176": {"l": "Surah Al-A'raaf, 7:175-176", "u": "https://quran.com/7/175-176", "ar": "وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱلَّذِىٓ ءَاتَيْنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنْهَا فَأَتْبَعَهُ ٱلشَّيْطَٰنُ فَكَانَ مِنَ ٱلْغَاوِينَ ﴿١٧٥﴾ وَلَوْ شِئْنَا لَرَفَعْنَٰهُ بِهَا وَلَٰكِنَّهُۥٓ أَخْلَدَ إِلَى ٱلْأَرْضِ وَٱتَّبَعَ هَوَىٰهُ ۚ فَمَثَلُهُۥ كَمَثَلِ ٱلْكَلْبِ إِن تَحْمِلْ عَلَيْهِ يَلْهَثْ أَوْ تَتْرُكْهُ يَلْهَث ۚ ذَّٰلِكَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا ۚ فَٱقْصُصِ ٱلْقَصَصَ لَعَلَّهُمْ يَتَفَكَّرُونَ ﴿١٧٦﴾", "tr": "And recite to them, [O Muhammad], the news of him to whom we gave [knowledge of] Our signs, but he detached himself from them; so Satan pursued him, and he became of the deviators. (175) And if We had willed, we could have elevated him thereby, but he adhered [instead] to the earth and followed his own desire. So his example is like that of the dog: if you chase him, he pants, or if you leave him, he [still] pants. That is the example of the people who denied Our signs. So relate the stories that perhaps they will give thought. (176)", "a": "ulama-ka-kirdar.html#q-7-175-176"}, "Q:2:176": {"l": "Surah Al-Baqara, 2:176", "u": "https://quran.com/2/176", "ar": "ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلْكِتَٰبَ بِٱلْحَقِّ ۗ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِى ٱلْكِتَٰبِ لَفِى شِقَاقٍۭ بَعِيدٍۢ ﴿١٧٦﴾", "tr": "That is [deserved by them] because Allah has sent down the Book in truth. And indeed, those who differ over the Book are in extreme dissension. (176)", "a": "ikhtilaf-ki-wajah.html#q-2-176"}, "H:muslim:2989a": {"l": "Sahih Muslim, Hadith 2989", "u": "https://sunnah.com/muslim:2989a", "t": "Commanding good without doing it (Sahih Muslim)", "k": "قَدْ كُنْتُ آمُرُ بِالْمَعْرُوفِ وَلاَ آتِيهِ وَأَنْهَى عَنِ الْمُنْكَرِ وَآتِيهِ", "a": "ulama-ka-kirdar.html#h-muslim-2989a"}, "H:bukhari:7352": {"l": "Sahih al-Bukhari, Hadith 7352", "u": "https://sunnah.com/bukhari:7352", "t": "Ijtihad: two rewards if right, one if mistaken", "k": "إِذَا حَكَمَ الْحَاكِمُ فَاجْتَهَدَ ثُمَّ أَصَابَ فَلَهُ أَجْرَانِ، وَإِذَا حَكَمَ فَاجْتَهَدَ ثُمَّ أَخْطَأَ فَلَهُ أَجْرٌ", "a": "imamon-ki-haisiyat.html#h-bukhari-7352"}, "Q:8:53": {"l": "Surah Al-Anfaal, 8:53", "u": "https://quran.com/8/53", "ar": "ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمْ يَكُ مُغَيِّرًۭا نِّعْمَةً أَنْعَمَهَا عَلَىٰ قَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ ۙ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌۭ ﴿٥٣﴾", "tr": "That is because Allah would not change a favor which He had bestowed upon a people until they change what is within themselves. And indeed, Allah is Hearing and Knowing. (53)", "a": "qaumon-ki-barbadi.html#q-8-53"}, "Q:34:43": {"l": "Surah Saba, 34:43", "u": "https://quran.com/34/43", "ar": "وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍۢ قَالُوا۟ مَا هَٰذَآ إِلَّا رَجُلٌۭ يُرِيدُ أَن يَصُدَّكُمْ عَمَّا كَانَ يَعْبُدُ ءَابَآؤُكُمْ وَقَالُوا۟ مَا هَٰذَآ إِلَّآ إِفْكٌۭ مُّفْتَرًۭى ۚ وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلْحَقِّ لَمَّا جَآءَهُمْ إِنْ هَٰذَآ إِلَّا سِحْرٌۭ مُّبِينٌۭ ﴿٤٣﴾", "tr": "And when our verses are recited to them as clear evidences, they say, \"This is not but a man who wishes to avert you from that which your fathers were worshipping.\" And they say, \"This is not except a lie invented.\" And those who disbelieve say of the truth when it has come to them, \"This is not but obvious magic.\" (43)", "a": "maslaki-hatdharmi.html#q-34-43"}, "Q:4:59": {"l": "Surah An-Nisaa, 4:59", "u": "https://quran.com/4/59", "ar": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَأُو۟لِى ٱلْأَمْرِ مِنكُمْ ۖ فَإِن تَنَٰزَعْتُمْ فِى شَىْءٍۢ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمْ تُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۚ ذَٰلِكَ خَيْرٌۭ وَأَحْسَنُ تَأْوِيلًا ﴿٥٩﴾", "tr": "O you who have believed, obey Allah and obey the Messenger and those in authority among you. And if you disagree over anything, refer it to Allah and the Messenger, if you should believe in Allah and the Last Day. That is the best [way] and best in result. (59)", "a": "imamon-ki-haisiyat.html#q-4-59"}, "Q:2:42": {"l": "Surah Al-Baqara, 2:42", "u": "https://quran.com/2/42", "ar": "وَلَا تَلْبِسُوا۟ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُوا۟ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ ﴿٤٢﴾", "tr": "And do not mix the truth with falsehood or conceal the truth while you know [it]. (42)", "a": "ulama-ka-kirdar.html#q-2-41-42"}, "H:muslim:532": {"l": "Sahih Muslim, Hadith 532", "u": "https://sunnah.com/muslim:532", "t": "Beware, do not take graves as places of prostration", "k": "أَلاَ فَلاَ تَتَّخِذُوا الْقُبُورَ مَسَاجِدَ إِنِّي أَنْهَاكُمْ عَنْ ذَلِكَ", "a": "ahle-kitab-ka-naqsha.html#h-muslim-532"}, "H:bukhari:6487": {"l": "Sahih al-Bukhari, Hadith 6487", "u": "https://sunnah.com/bukhari:6487", "t": "The Fire is veiled with desires, Paradise with hardships", "k": "حُجِبَتِ النَّارُ بِالشَّهَوَاتِ، وَحُجِبَتِ الْجَنَّةُ بِالْمَكَارِهِ", "a": "tazkiya-e-nafs.html#h-bukhari-6487"}, "H:muslim:867a": {"l": "Sahih Muslim, Hadith 867", "u": "https://sunnah.com/muslim:867a", "t": "The sermon: the best speech is the Book of Allah, every innovation is misguidance", "k": "فَإِنَّ خَيْرَ الْحَدِيثِ كِتَابُ اللَّهِ وَخَيْرُ الْهُدَى هُدَى مُحَمَّدٍ وَشَرُّ الأُمُورِ مُحْدَثَاتُهَا وَكُلُّ بِدْعَةٍ ضَلاَلَةٌ", "a": "deen-aur-firqe.html#h-muslim-867a"}, "Q:17:36": {"l": "Surah Al-Israa, 17:36", "u": "https://quran.com/17/36", "ar": "وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ ۚ إِنَّ ٱلسَّمْعَ وَٱلْبَصَرَ وَٱلْفُؤَادَ كُلُّ أُو۟لَٰٓئِكَ كَانَ عَنْهُ مَسْـُٔولًۭا ﴿٣٦﴾", "tr": "And do not pursue that of which you have no knowledge. Indeed, the hearing, the sight and the heart - about all those [one] will be questioned. (36)", "a": "ikhtilaf-ki-wajah.html#q-17-36"}, "H:bukhari:1": {"l": "Sahih al-Bukhari, Hadith 1", "u": "https://sunnah.com/bukhari:1", "t": "Deeds are only by intentions", "k": "إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ", "a": "tazkiya-e-nafs.html#h-bukhari-1"}, "H:bukhari:7257": {"l": "Sahih al-Bukhari, Hadith 7257", "u": "https://sunnah.com/bukhari:7257", "t": "The commander and the fire: no obedience in sin", "k": "لاَ طَاعَةَ فِي مَعْصِيَةٍ، إِنَّمَا الطَّاعَةُ فِي الْمَعْرُوفِ", "a": "imamon-ki-haisiyat.html#h-bukhari-7257"}, "Q:59:10": {"l": "Surah Al-Hashr, 59:10", "u": "https://quran.com/59/10", "ar": "وَٱلَّذِينَ جَآءُو مِنۢ بَعْدِهِمْ يَقُولُونَ رَبَّنَا ٱغْفِرْ لَنَا وَلِإِخْوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلْإِيمَٰنِ وَلَا تَجْعَلْ فِى قُلُوبِنَا غِلًّۭا لِّلَّذِينَ ءَامَنُوا۟ رَبَّنَآ إِنَّكَ رَءُوفٌۭ رَّحِيمٌ ﴿١٠﴾", "tr": "And [there is a share for] those who came after them, saying, \"Our Lord, forgive us and our brothers who preceded us in faith and put not in our hearts [any] resentment toward those who have believed. Our Lord, indeed You are Kind and Merciful.\" (10)", "a": "firqa-parasti-se-bachao.html#q-59-10"}, "Q:3:110": {"l": "Surah Aal-i-Imraan, 3:110", "u": "https://quran.com/3/110", "ar": "كُنتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِٱلْمَعْرُوفِ وَتَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَتُؤْمِنُونَ بِٱللَّهِ ۗ وَلَوْ ءَامَنَ أَهْلُ ٱلْكِتَٰبِ لَكَانَ خَيْرًۭا لَّهُم ۚ مِّنْهُمُ ٱلْمُؤْمِنُونَ وَأَكْثَرُهُمُ ٱلْفَٰسِقُونَ ﴿١١٠﴾", "tr": "You are the best nation produced [as an example] for mankind. You enjoin what is right and forbid what is wrong and believe in Allah. If only the People of the Scripture had believed, it would have been better for them. Among them are believers, but most of them are defiantly disobedient. (110)", "a": "firqa-parasti-se-bachao.html#q-3-110"}, "Q:8:46": {"l": "Surah Al-Anfaal, 8:46", "u": "https://quran.com/8/46", "ar": "وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَٰزَعُوا۟ فَتَفْشَلُوا۟ وَتَذْهَبَ رِيحُكُمْ ۖ وَٱصْبِرُوٓا۟ ۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ ﴿٤٦﴾", "tr": "And obey Allah and His Messenger, and do not dispute and [thus] lose courage and [then] your strength would depart; and be patient. Indeed, Allah is with the patient. (46)", "a": "deen-aur-firqe.html#q-8-46"}, "Q:7:96": {"l": "Surah Al-A'raaf, 7:96", "u": "https://quran.com/7/96", "ar": "وَلَوْ أَنَّ أَهْلَ ٱلْقُرَىٰٓ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَفَتَحْنَا عَلَيْهِم بَرَكَٰتٍۢ مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ وَلَٰكِن كَذَّبُوا۟ فَأَخَذْنَٰهُم بِمَا كَانُوا۟ يَكْسِبُونَ ﴿٩٦﴾", "tr": "And if only the people of the cities had believed and feared Allah, We would have opened upon them blessings from the heaven and the earth; but they denied [the messengers], so We seized them for what they were earning.\" (96)", "a": "qaumon-ki-barbadi.html#q-7-94-96"}, "Q:2:206": {"l": "Surah Al-Baqara, 2:206", "u": "https://quran.com/2/206", "ar": "وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتْهُ ٱلْعِزَّةُ بِٱلْإِثْمِ ۚ فَحَسْبُهُۥ جَهَنَّمُ ۚ وَلَبِئْسَ ٱلْمِهَادُ ﴿٢٠٦﴾", "tr": "And when it is said to him, \"Fear Allah,\" pride in the sin takes hold of him. Sufficient for him is Hellfire, and how wretched is the resting place. (206)", "a": "maslaki-hatdharmi.html#q-2-206"}, "Q:4:83": {"l": "Surah An-Nisaa, 4:83", "u": "https://quran.com/4/83", "ar": "وَإِذَا جَآءَهُمْ أَمْرٌۭ مِّنَ ٱلْأَمْنِ أَوِ ٱلْخَوْفِ أَذَاعُوا۟ بِهِۦ ۖ وَلَوْ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُو۟لِى ٱلْأَمْرِ مِنْهُمْ لَعَلِمَهُ ٱلَّذِينَ يَسْتَنۢبِطُونَهُۥ مِنْهُمْ ۗ وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَٱتَّبَعْتُمُ ٱلشَّيْطَٰنَ إِلَّا قَلِيلًۭا ﴿٨٣﴾", "tr": "And when there comes to them information about [public] security or fear, they spread it around. But if they had referred it back to the Messenger or to those of authority among them, then the ones who [can] draw correct conclusions from it would have known about it. And if not for the favor of Allah upon you and His mercy, you would have followed Satan, except for a few. (83)", "a": "firqa-parasti-se-bachao.html#q-4-83"}, "H:muslim:2563a": {"l": "Sahih Muslim, Hadith 2563", "u": "https://sunnah.com/muslim:2563a", "t": "Avoid suspicion; be brothers (Sahih Muslim)", "k": "إِيَّاكُمْ وَالظَّنَّ فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ … وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا", "a": "ikhtilaf-ki-wajah.html#h-muslim-2563a"}, "H:bukhari:13": {"l": "Sahih al-Bukhari, Hadith 13", "u": "https://sunnah.com/bukhari:13", "t": "Love for your brother what you love for yourself", "k": "لا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ", "a": "firqa-parasti-se-bachao.html#h-bukhari-13"}, "Q:24:54": {"l": "Surah An-Noor, 24:54", "u": "https://quran.com/24/54", "ar": "قُلْ أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ ۖ فَإِن تَوَلَّوْا۟ فَإِنَّمَا عَلَيْهِ مَا حُمِّلَ وَعَلَيْكُم مَّا حُمِّلْتُمْ ۖ وَإِن تُطِيعُوهُ تَهْتَدُوا۟ ۚ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ ﴿٥٤﴾", "tr": "Say, \"Obey Allah and obey the Messenger; but if you turn away - then upon him is only that [duty] with which he has been charged, and upon you is that with which you have been charged. And if you obey him, you will be [rightly] guided. And there is not upon the Messenger except the [responsibility for] clear notification.\" (54)", "a": "imamon-ki-haisiyat.html#q-24-54"}, "Q:2:79": {"l": "Surah Al-Baqara, 2:79", "u": "https://quran.com/2/79", "ar": "فَوَيْلٌۭ لِّلَّذِينَ يَكْتُبُونَ ٱلْكِتَٰبَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَٰذَا مِنْ عِندِ ٱللَّهِ لِيَشْتَرُوا۟ بِهِۦ ثَمَنًۭا قَلِيلًۭا ۖ فَوَيْلٌۭ لَّهُم مِّمَّا كَتَبَتْ أَيْدِيهِمْ وَوَيْلٌۭ لَّهُم مِّمَّا يَكْسِبُونَ ﴿٧٩﴾", "tr": "So woe to those who write the \"scripture\" with their own hands, then say, \"This is from Allah,\" in order to exchange it for a small price. Woe to them for what their hands have written and woe to them for what they earn. (79)", "a": "ulama-ka-kirdar.html#q-2-79"}, "Q:43:22-24": {"l": "Surah Az-Zukhruf, 43:22-24", "u": "https://quran.com/43/22-24", "ar": "بَلْ قَالُوٓا۟ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍۢ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّهْتَدُونَ ﴿٢٢﴾ وَكَذَٰلِكَ مَآ أَرْسَلْنَا مِن قَبْلِكَ فِى قَرْيَةٍۢ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَآ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍۢ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّقْتَدُونَ ﴿٢٣﴾ ۞ قَٰلَ أَوَلَوْ جِئْتُكُم بِأَهْدَىٰ مِمَّا وَجَدتُّمْ عَلَيْهِ ءَابَآءَكُمْ ۖ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ ﴿٢٤﴾", "tr": "Rather, they say, \"Indeed, we found our fathers upon a religion, and we are in their footsteps [rightly] guided.\" (22) And similarly, We did not send before you any warner into a city except that its affluent said, \"Indeed, we found our fathers upon a religion, and we are, in their footsteps, following.\" (23) [Each warner] said, \"Even if I brought you better guidance than that [religion] upon which you found your fathers?\" They said, \"Indeed we, in that with which you were sent, are disbelievers.\" (24)", "a": "maslaki-hatdharmi.html#q-43-22-24"}, "Q:11:118-119": {"l": "Surah Hud, 11:118-119", "u": "https://quran.com/11/118-119", "ar": "وَلَوْ شَآءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةًۭ وَٰحِدَةًۭ ۖ وَلَا يَزَالُونَ مُخْتَلِفِينَ ﴿١١٨﴾ إِلَّا مَن رَّحِمَ رَبُّكَ ۚ وَلِذَٰلِكَ خَلَقَهُمْ ۗ وَتَمَّتْ كَلِمَةُ رَبِّكَ لَأَمْلَأَنَّ جَهَنَّمَ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ أَجْمَعِينَ ﴿١١٩﴾", "tr": "And if your Lord had willed, He could have made mankind one community; but they will not cease to differ. (118) Except whom your Lord has given mercy, and for that He created them. But the word of your Lord is to be fulfilled that, \"I will surely fill Hell with jinn and men all together.\" (119)", "a": "ikhtilaf-ki-wajah.html#q-11-118-119"}, "Q:4:61": {"l": "Surah An-Nisaa, 4:61", "u": "https://quran.com/4/61", "ar": "وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَيْتَ ٱلْمُنَٰفِقِينَ يَصُدُّونَ عَنكَ صُدُودًۭا ﴿٦١﴾", "tr": "And when it is said to them, \"Come to what Allah has revealed and to the Messenger,\" you see the hypocrites turning away from you in aversion. (61)", "a": "maslaki-hatdharmi.html#q-4-61"}, "Q:79:40": {"l": "Surah An-Naazi'aat, 79:40", "u": "https://quran.com/79/40", "ar": "وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفْسَ عَنِ ٱلْهَوَىٰ ﴿٤٠﴾", "tr": "But as for he who feared the position of his Lord and prevented the soul from [unlawful] inclination, (40)", "a": "tazkiya-e-nafs.html#q-79-40-41"}, "H:muslim:531": {"l": "Sahih Muslim, Hadith 531", "u": "https://sunnah.com/muslim:531", "t": "The curse on taking the prophets' graves as places of prostration", "k": "لَعْنَةُ اللَّهِ عَلَى الْيَهُودِ وَالنَّصَارَى اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ", "a": "ahle-kitab-ka-naqsha.html#h-muslim-531"}, "H:bukhari:7363": {"l": "Sahih al-Bukhari, Hadith 7363", "u": "https://sunnah.com/bukhari:7363", "t": "A Companion's words: Ibn 'Abbas on asking the People of the Book", "k": "كَيْفَ تَسْأَلُونَ أَهْلَ الْكِتَابِ عَنْ شَىْءٍ … تَقْرَءُونَهُ مَحْضًا لَمْ يُشَبْ", "a": "ahle-kitab-ka-naqsha.html#h-bukhari-7363"}, "Q:33:66-68": {"l": "Surah Al-Ahzaab, 33:66-68", "u": "https://quran.com/33/66-68", "ar": "يَوْمَ تُقَلَّبُ وُجُوهُهُمْ فِى ٱلنَّارِ يَقُولُونَ يَٰلَيْتَنَآ أَطَعْنَا ٱللَّهَ وَأَطَعْنَا ٱلرَّسُولَا۠ ﴿٦٦﴾ وَقَالُوا۟ رَبَّنَآ إِنَّآ أَطَعْنَا سَادَتَنَا وَكُبَرَآءَنَا فَأَضَلُّونَا ٱلسَّبِيلَا۠ ﴿٦٧﴾ رَبَّنَآ ءَاتِهِمْ ضِعْفَيْنِ مِنَ ٱلْعَذَابِ وَٱلْعَنْهُمْ لَعْنًۭا كَبِيرًۭا ﴿٦٨﴾", "tr": "The Day their faces will be turned about in the Fire, they will say, \"How we wish we had obeyed Allah and obeyed the Messenger.\" (66) And they will say, \"Our Lord, indeed we obeyed our masters and our dignitaries, and they led us astray from the [right] way. (67) Our Lord, give them double the punishment and curse them with a great curse.\" (68)", "a": "imamon-ki-haisiyat.html#q-33-66-68"}, "Q:2:160": {"l": "Surah Al-Baqara, 2:160", "u": "https://quran.com/2/160", "ar": "إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَبَيَّنُوا۟ فَأُو۟لَٰٓئِكَ أَتُوبُ عَلَيْهِمْ ۚ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ ﴿١٦٠﴾", "tr": "Except for those who repent and correct themselves and make evident [what they concealed]. Those - I will accept their repentance, and I am the Accepting of repentance, the Merciful. (160)", "a": "ulama-ka-kirdar.html#q-2-159-160"}, "Q:7:146": {"l": "Surah Al-A'raaf, 7:146", "u": "https://quran.com/7/146", "ar": "سَأَصْرِفُ عَنْ ءَايَٰتِىَ ٱلَّذِينَ يَتَكَبَّرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَإِن يَرَوْا۟ كُلَّ ءَايَةٍۢ لَّا يُؤْمِنُوا۟ بِهَا وَإِن يَرَوْا۟ سَبِيلَ ٱلرُّشْدِ لَا يَتَّخِذُوهُ سَبِيلًۭا وَإِن يَرَوْا۟ سَبِيلَ ٱلْغَىِّ يَتَّخِذُوهُ سَبِيلًۭا ۚ ذَٰلِكَ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ عَنْهَا غَٰفِلِينَ ﴿١٤٦﴾", "tr": "I will turn away from My signs those who are arrogant upon the earth without right; and if they should see every sign, they will not believe in it. And if they see the way of consciousness, they will not adopt it as a way; but if they see the way of error, they will adopt it as a way. That is because they have denied Our signs and they were heedless of them. (146)", "a": "maslaki-hatdharmi.html#q-7-146"}, "H:bukhari:7280": {"l": "Sahih al-Bukhari, Hadith 7280", "u": "https://sunnah.com/bukhari:7280", "t": "All my ummah will enter Paradise except the one who refuses", "k": "كُلُّ أُمَّتِي يَدْخُلُونَ الْجَنَّةَ، إِلاَّ مَنْ أَبَى … مَنْ أَطَاعَنِي دَخَلَ الْجَنَّةَ، وَمَنْ عَصَانِي فَقَدْ أَبَى", "a": "deen-aur-firqe.html#h-bukhari-7280"}, "Q:16:125": {"l": "Surah An-Nahl, 16:125", "u": "https://quran.com/16/125", "ar": "ٱدْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلْحِكْمَةِ وَٱلْمَوْعِظَةِ ٱلْحَسَنَةِ ۖ وَجَٰدِلْهُم بِٱلَّتِى هِىَ أَحْسَنُ ۚ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ ۖ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ ﴿١٢٥﴾", "tr": "Invite to the way of your Lord with wisdom and good instruction, and argue with them in a way that is best. Indeed, your Lord is most knowing of who has strayed from His way, and He is most knowing of who is [rightly] guided. (125)", "a": "firqa-parasti-se-bachao.html#q-16-125"}, "H:muslim:2666": {"l": "Sahih Muslim, Hadith 2666", "u": "https://sunnah.com/muslim:2666", "t": "Earlier nations perished by differing over the Book", "k": "إِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِاخْتِلاَفِهِمْ فِي الْكِتَابِ", "a": "ikhtilaf-ki-wajah.html#h-muslim-2666"}, "H:bukhari:3475": {"l": "Sahih al-Bukhari, Hadith 3475", "u": "https://sunnah.com/bukhari:3475", "t": "What destroyed earlier nations: one law for the noble, another for the weak", "k": "إِنَّمَا أَهْلَكَ الَّذِينَ قَبْلَكُمْ … لَوْ أَنَّ فَاطِمَةَ ابْنَةَ مُحَمَّدٍ سَرَقَتْ لَقَطَعْتُ يَدَهَا", "a": "qaumon-ki-barbadi.html#h-bukhari-3475"}, "Q:3:85": {"l": "Surah Aal-i-Imraan, 3:85", "u": "https://quran.com/3/85", "ar": "وَمَن يَبْتَغِ غَيْرَ ٱلْإِسْلَٰمِ دِينًۭا فَلَن يُقْبَلَ مِنْهُ وَهُوَ فِى ٱلْءَاخِرَةِ مِنَ ٱلْخَٰسِرِينَ ﴿٨٥﴾", "tr": "And whoever desires other than Islam as religion - never will it be accepted from him, and he, in the Hereafter, will be among the losers. (85)", "a": "deen-aur-firqe.html#q-3-85"}, "H:muslim:2665": {"l": "Sahih Muslim, Hadith 2665", "u": "https://sunnah.com/muslim:2665", "t": "Beware of those who follow the ambiguous (Sahih Muslim)", "k": "إِذَا رَأَيْتُمُ الَّذِينَ يَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ فَأُولَئِكَ الَّذِينَ سَمَّى اللَّهُ فَاحْذَرُوهُمْ", "a": "ikhtilaf-ki-wajah.html#h-muslim-2665"}, "H:bukhari:79": {"l": "Sahih al-Bukhari, Hadith 79", "u": "https://sunnah.com/bukhari:79", "t": "The parable of guidance and knowledge: rain and land", "k": "مَثَلُ مَا بَعَثَنِي اللَّهُ بِهِ مِنَ الْهُدَى وَالْعِلْمِ كَمَثَلِ الْغَيْثِ الْكَثِيرِ … فَذَلِكَ مَثَلُ مَنْ فَقِهَ فِي دِينِ اللَّهِ وَنَفَعَهُ مَا بَعَثَنِي اللَّهُ بِهِ، فَعَلِمَ وَعَلَّمَ", "a": "imamon-ki-haisiyat.html#h-bukhari-79"}, "Q:5:77": {"l": "Surah Al-Maaida, 5:77", "u": "https://quran.com/5/77", "ar": "قُلْ يَٰٓأَهْلَ ٱلْكِتَٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ غَيْرَ ٱلْحَقِّ وَلَا تَتَّبِعُوٓا۟ أَهْوَآءَ قَوْمٍۢ قَدْ ضَلُّوا۟ مِن قَبْلُ وَأَضَلُّوا۟ كَثِيرًۭا وَضَلُّوا۟ عَن سَوَآءِ ٱلسَّبِيلِ ﴿٧٧﴾", "tr": "Say, \"O People of the Scripture, do not exceed limits in your religion beyond the truth and do not follow the inclinations of a people who had gone astray before and misled many and have strayed from the soundness of the way.\" (77)", "a": "ahle-kitab-ka-naqsha.html#q-5-77"}, "H:muslim:2021": {"l": "Sahih Muslim, Hadith 2021", "u": "https://sunnah.com/muslim:2021", "t": "Refusing to eat with the right hand: pride stopped him", "k": "كُلْ بِيَمِينِكَ ‏\"‏ ‏.‏ قَالَ لاَ أَسْتَطِيعُ قَالَ ‏\"‏ لاَ اسْتَطَعْتَ ‏\"‏ ‏.‏ مَا مَنَعَهُ إِلاَّ الْكِبْرُ", "a": "maslaki-hatdharmi.html#h-muslim-2021"}, "Q:22:78": {"l": "Surah Al-Hajj, 22:78", "u": "https://quran.com/22/78", "ar": "وَجَٰهِدُوا۟ فِى ٱللَّهِ حَقَّ جِهَادِهِۦ ۚ هُوَ ٱجْتَبَىٰكُمْ وَمَا جَعَلَ عَلَيْكُمْ فِى ٱلدِّينِ مِنْ حَرَجٍۢ ۚ مِّلَّةَ أَبِيكُمْ إِبْرَٰهِيمَ ۚ هُوَ سَمَّىٰكُمُ ٱلْمُسْلِمِينَ مِن قَبْلُ وَفِى هَٰذَا لِيَكُونَ ٱلرَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ ۚ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱعْتَصِمُوا۟ بِٱللَّهِ هُوَ مَوْلَىٰكُمْ ۖ فَنِعْمَ ٱلْمَوْلَىٰ وَنِعْمَ ٱلنَّصِيرُ ﴿٧٨﴾", "tr": "And strive for Allah with the striving due to Him. He has chosen you and has not placed upon you in the religion any difficulty. [It is] the religion of your father, Abraham. Allah named you \"Muslims\" before [in former scriptures] and in this [revelation] that the Messenger may be a witness over you and you may be witnesses over the people. So establish prayer and give zakah and hold fast to Allah. He is your protector; and excellent is the protector, and excellent is the helper. (78)", "a": "deen-aur-firqe.html#q-22-78"}, "Q:28:50": {"l": "Surah Al-Qasas, 28:50", "u": "https://quran.com/28/50", "ar": "فَإِن لَّمْ يَسْتَجِيبُوا۟ لَكَ فَٱعْلَمْ أَنَّمَا يَتَّبِعُونَ أَهْوَآءَهُمْ ۚ وَمَنْ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيْرِ هُدًۭى مِّنَ ٱللَّهِ ۚ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ ﴿٥٠﴾", "tr": "But if they do not respond to you - then know that they only follow their [own] desires. And who is more astray than one who follows his desire without guidance from Allah? Indeed, Allah does not guide the wrongdoing people. (50)", "a": "ikhtilaf-ki-wajah.html#q-28-50"}, "Q:2:159-160": {"l": "Surah Al-Baqara, 2:159-160", "u": "https://quran.com/2/159-160", "ar": "إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلْنَا مِنَ ٱلْبَيِّنَٰتِ وَٱلْهُدَىٰ مِنۢ بَعْدِ مَا بَيَّنَّٰهُ لِلنَّاسِ فِى ٱلْكِتَٰبِ ۙ أُو۟لَٰٓئِكَ يَلْعَنُهُمُ ٱللَّهُ وَيَلْعَنُهُمُ ٱللَّٰعِنُونَ ﴿١٥٩﴾ إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَبَيَّنُوا۟ فَأُو۟لَٰٓئِكَ أَتُوبُ عَلَيْهِمْ ۚ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ ﴿١٦٠﴾", "tr": "Indeed, those who conceal what We sent down of clear proofs and guidance after We made it clear for the people in the Scripture - those are cursed by Allah and cursed by those who curse, (159) Except for those who repent and correct themselves and make evident [what they concealed]. Those - I will accept their repentance, and I am the Accepting of repentance, the Merciful. (160)", "a": "ulama-ka-kirdar.html#q-2-159-160"}, "H:bukhari:6114": {"l": "Sahih al-Bukhari, Hadith 6114", "u": "https://sunnah.com/bukhari:6114", "t": "The strong one controls himself in anger", "k": "إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ", "a": "tazkiya-e-nafs.html#h-bukhari-6114"}, "Q:61:2-3": {"l": "Surah As-Saff, 61:2-3", "u": "https://quran.com/61/2-3", "ar": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ ﴿٢﴾ كَبُرَ مَقْتًا عِندَ ٱللَّهِ أَن تَقُولُوا۟ مَا لَا تَفْعَلُونَ ﴿٣﴾", "tr": "O you who have believed, why do you say what you do not do? (2) Great is hatred in the sight of Allah that you say what you do not do. (3)", "a": "ulama-ka-kirdar.html#q-61-2-3"}, "H:muslim:2722": {"l": "Sahih Muslim, Hadith 2722", "u": "https://sunnah.com/muslim:2722", "t": "Prayer: O Allah, give my soul its mindfulness and purify it", "k": "اللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا", "a": "tazkiya-e-nafs.html#h-muslim-2722"}, "H:muslim:2588": {"l": "Sahih Muslim, Hadith 2588", "u": "https://sunnah.com/muslim:2588", "t": "Honour through forgiveness, elevation through humility", "k": "وَمَا تَوَاضَعَ أَحَدٌ لِلَّهِ إِلاَّ رَفَعَهُ اللَّهُ", "a": "tazkiya-e-nafs.html#h-muslim-2588"}, "H:bukhari:2410": {"l": "Sahih al-Bukhari, Hadith 2410", "u": "https://sunnah.com/bukhari:2410", "t": "Both of you are right; do not dispute", "k": "كِلاَكُمَا مُحْسِنٌ … لاَ تَخْتَلِفُوا فَإِنَّ مَنْ كَانَ قَبْلَكُمُ اخْتَلَفُوا فَهَلَكُوا", "a": "firqa-parasti-se-bachao.html#h-bukhari-2410"}, "Q:7:33": {"l": "Surah Al-A'raaf, 7:33", "u": "https://quran.com/7/33", "ar": "قُلْ إِنَّمَا حَرَّمَ رَبِّىَ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَٱلْإِثْمَ وَٱلْبَغْىَ بِغَيْرِ ٱلْحَقِّ وَأَن تُشْرِكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًۭا وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ ﴿٣٣﴾", "tr": "Say, \"My Lord has only forbidden immoralities - what is apparent of them and what is concealed - and sin, and oppression without right, and that you associate with Allah that for which He has not sent down authority, and that you say about Allah that which you do not know.\" (33)", "a": "ikhtilaf-ki-wajah.html#q-7-33"}, "Q:3:78": {"l": "Surah Aal-i-Imraan, 3:78", "u": "https://quran.com/3/78", "ar": "وَإِنَّ مِنْهُمْ لَفَرِيقًۭا يَلْوُۥنَ أَلْسِنَتَهُم بِٱلْكِتَٰبِ لِتَحْسَبُوهُ مِنَ ٱلْكِتَٰبِ وَمَا هُوَ مِنَ ٱلْكِتَٰبِ وَيَقُولُونَ هُوَ مِنْ عِندِ ٱللَّهِ وَمَا هُوَ مِنْ عِندِ ٱللَّهِ وَيَقُولُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُمْ يَعْلَمُونَ ﴿٧٨﴾", "tr": "And indeed, there is among them a party who alter the Scripture with their tongues so you may think it is from the Scripture, but it is not from the Scripture. And they say, \"This is from Allah,\" but it is not from Allah. And they speak untruth about Allah while they know. (78)", "a": "ulama-ka-kirdar.html#q-3-78"}, "H:bukhari:3456": {"l": "Sahih al-Bukhari, Hadith 3456", "u": "https://sunnah.com/bukhari:3456", "t": "You will surely follow the ways of those before you (with the Companions' question)", "k": "لَتَتَّبِعُنَّ سَنَنَ مَنْ قَبْلَكُمْ شِبْرًا بِشِبْرٍ، وَذِرَاعًا بِذِرَاعٍ … الْيَهُودَ وَالنَّصَارَى قَالَ ‏\"‏ فَمَنْ", "a": "ahle-kitab-ka-naqsha.html#h-bukhari-3456"}, "Q:33:21": {"l": "Surah Al-Ahzaab, 33:21", "u": "https://quran.com/33/21", "ar": "لَّقَدْ كَانَ لَكُمْ فِى رَسُولِ ٱللَّهِ أُسْوَةٌ حَسَنَةٌۭ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْءَاخِرَ وَذَكَرَ ٱللَّهَ كَثِيرًۭا ﴿٢١﴾", "tr": "There has certainly been for you in the Messenger of Allah an excellent pattern for anyone whose hope is in Allah and the Last Day and [who] remembers Allah often. (21)", "a": "firqa-parasti-se-bachao.html#q-33-21"}, "Q:24:48": {"l": "Surah An-Noor, 24:48", "u": "https://quran.com/24/48", "ar": "وَإِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ إِذَا فَرِيقٌۭ مِّنْهُم مُّعْرِضُونَ ﴿٤٨﴾", "tr": "And when they are called to [the words of] Allah and His Messenger to judge between them, at once a party of them turns aside [in refusal]. (48)", "a": "maslaki-hatdharmi.html#q-24-48-51"}, "Q:20:124": {"l": "Surah Taa-Haa, 20:124", "u": "https://quran.com/20/124", "ar": "وَمَنْ أَعْرَضَ عَن ذِكْرِى فَإِنَّ لَهُۥ مَعِيشَةًۭ ضَنكًۭا وَنَحْشُرُهُۥ يَوْمَ ٱلْقِيَٰمَةِ أَعْمَىٰ ﴿١٢٤﴾", "tr": "And whoever turns away from My remembrance - indeed, he will have a depressed life, and We will gather him on the Day of Resurrection blind.\" (124)", "a": "qaumon-ki-barbadi.html#q-20-124"}, "Q:2:170": {"l": "Surah Al-Baqara, 2:170", "u": "https://quran.com/2/170", "ar": "وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلْ نَتَّبِعُ مَآ أَلْفَيْنَا عَلَيْهِ ءَابَآءَنَآ ۗ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْقِلُونَ شَيْـًۭٔا وَلَا يَهْتَدُونَ ﴿١٧٠﴾", "tr": "And when it is said to them, \"Follow what Allah has revealed,\" they say, \"Rather, we will follow that which we found our fathers doing.\" Even though their fathers understood nothing, nor were they guided? (170)", "a": "maslaki-hatdharmi.html#q-2-170"}, "H:bukhari:3445": {"l": "Sahih al-Bukhari, Hadith 3445", "u": "https://sunnah.com/bukhari:3445", "t": "Do not exaggerate about me as the Christians did", "k": "لاَ تُطْرُونِي كَمَا أَطْرَتِ النَّصَارَى ابْنَ مَرْيَمَ … فَقُولُوا عَبْدُ اللَّهِ وَرَسُولُهُ", "a": "ahle-kitab-ka-naqsha.html#h-bukhari-3445"}, "Q:9:9": {"l": "Surah At-Tawba, 9:9", "u": "https://quran.com/9/9", "ar": "ٱشْتَرَوْا۟ بِـَٔايَٰتِ ٱللَّهِ ثَمَنًۭا قَلِيلًۭا فَصَدُّوا۟ عَن سَبِيلِهِۦٓ ۚ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ ﴿٩﴾", "tr": "They have exchanged the signs of Allah for a small price and averted [people] from His way. Indeed, it was evil that they were doing. (9)", "a": "ulama-ka-kirdar.html#q-9-9"}, "Q:9:103": {"l": "Surah At-Tawba, 9:103", "u": "https://quran.com/9/103", "ar": "خُذْ مِنْ أَمْوَٰلِهِمْ صَدَقَةًۭ تُطَهِّرُهُمْ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيْهِمْ ۖ إِنَّ صَلَوٰتَكَ سَكَنٌۭ لَّهُمْ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ ﴿١٠٣﴾", "tr": "Take, [O, Muhammad], from their wealth a charity by which you purify them and cause them increase, and invoke [Allah 's blessings] upon them. Indeed, your invocations are reassurance for them. And Allah is Hearing and Knowing. (103)", "a": "tazkiya-e-nafs.html#q-9-103"}, "Q:2:159": {"l": "Surah Al-Baqara, 2:159", "u": "https://quran.com/2/159", "ar": "إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلْنَا مِنَ ٱلْبَيِّنَٰتِ وَٱلْهُدَىٰ مِنۢ بَعْدِ مَا بَيَّنَّٰهُ لِلنَّاسِ فِى ٱلْكِتَٰبِ ۙ أُو۟لَٰٓئِكَ يَلْعَنُهُمُ ٱللَّهُ وَيَلْعَنُهُمُ ٱللَّٰعِنُونَ ﴿١٥٩﴾", "tr": "Indeed, those who conceal what We sent down of clear proofs and guidance after We made it clear for the people in the Scripture - those are cursed by Allah and cursed by those who curse, (159)", "a": "ulama-ka-kirdar.html#q-2-159-160"}, "Q:6:153": {"l": "Surah Al-An'aam, 6:153", "u": "https://quran.com/6/153", "ar": "وَأَنَّ هَٰذَا صِرَٰطِى مُسْتَقِيمًۭا فَٱتَّبِعُوهُ ۖ وَلَا تَتَّبِعُوا۟ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِۦ ۚ ذَٰلِكُمْ وَصَّىٰكُم بِهِۦ لَعَلَّكُمْ تَتَّقُونَ ﴿١٥٣﴾", "tr": "And, [moreover], this is My path, which is straight, so follow it; and do not follow [other] ways, for you will be separated from His way. This has He instructed you that you may become righteous. (153)", "a": "deen-aur-firqe.html#q-6-153"}, "Q:16:116": {"l": "Surah An-Nahl, 16:116", "u": "https://quran.com/16/116", "ar": "وَلَا تَقُولُوا۟ لِمَا تَصِفُ أَلْسِنَتُكُمُ ٱلْكَذِبَ هَٰذَا حَلَٰلٌۭ وَهَٰذَا حَرَامٌۭ لِّتَفْتَرُوا۟ عَلَى ٱللَّهِ ٱلْكَذِبَ ۚ إِنَّ ٱلَّذِينَ يَفْتَرُونَ عَلَى ٱللَّهِ ٱلْكَذِبَ لَا يُفْلِحُونَ ﴿١١٦﴾", "tr": "And do not say about what your tongues assert of untruth, \"This is lawful and this is unlawful,\" to invent falsehood about Allah. Indeed, those who invent falsehood about Allah will not succeed. (116)", "a": "ulama-ka-kirdar.html#q-16-116"}, "H:bukhari:71": {"l": "Sahih al-Bukhari, Hadith 71", "u": "https://sunnah.com/bukhari:71", "t": "Whom Allah wants good for, He gives understanding of the religion", "k": "مَنْ يُرِدِ اللَّهُ بِهِ خَيْرًا يُفَقِّهْهُ فِي الدِّينِ", "a": "imamon-ki-haisiyat.html#h-bukhari-71"}, "Q:3:23": {"l": "Surah Aal-i-Imraan, 3:23", "u": "https://quran.com/3/23", "ar": "أَلَمْ تَرَ إِلَى ٱلَّذِينَ أُوتُوا۟ نَصِيبًۭا مِّنَ ٱلْكِتَٰبِ يُدْعَوْنَ إِلَىٰ كِتَٰبِ ٱللَّهِ لِيَحْكُمَ بَيْنَهُمْ ثُمَّ يَتَوَلَّىٰ فَرِيقٌۭ مِّنْهُمْ وَهُم مُّعْرِضُونَ ﴿٢٣﴾", "tr": "Do you not consider, [O Muhammad], those who were given a portion of the Scripture? They are invited to the Scripture of Allah that it should arbitrate between them; then a party of them turns away, and they are refusing. (23)", "a": "ahle-kitab-ka-naqsha.html#q-3-23"}, "H:muslim:2669a": {"l": "Sahih Muslim, Hadith 2669", "u": "https://sunnah.com/muslim:2669a", "t": "Following the ways of those before (Sahih Muslim)", "k": "لَتَتَّبِعُنَّ سَنَنَ الَّذِينَ مِنْ قَبْلِكُمْ شِبْرًا بِشِبْرٍ وَذِرَاعًا بِذِرَاعٍ", "a": "ahle-kitab-ka-naqsha.html#h-muslim-2669a"}, "Q:49:6": {"l": "Surah Al-Hujuraat, 49:6", "u": "https://quran.com/49/6", "ar": "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن جَآءَكُمْ فَاسِقٌۢ بِنَبَإٍۢ فَتَبَيَّنُوٓا۟ أَن تُصِيبُوا۟ قَوْمًۢا بِجَهَٰلَةٍۢ فَتُصْبِحُوا۟ عَلَىٰ مَا فَعَلْتُمْ نَٰدِمِينَ ﴿٦﴾", "tr": "O you who have believed, if there comes to you a disobedient one with information, investigate, lest you harm a people out of ignorance and become, over what you have done, regretful. (6)", "a": "firqa-parasti-se-bachao.html#q-49-6"}, "H:muslim:2578": {"l": "Sahih Muslim, Hadith 2578", "u": "https://sunnah.com/muslim:2578", "t": "Oppression is darkness, and greed destroyed those before", "k": "اتَّقُوا الظُّلْمَ فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ … فَإِنَّ الشُّحَّ أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ", "a": "qaumon-ki-barbadi.html#h-muslim-2578"}, "H:bukhari:118": {"l": "Sahih al-Bukhari, Hadith 118", "u": "https://sunnah.com/bukhari:118", "t": "A Companion's words: Abu Hurayrah and the verse on concealment", "k": "وَلَوْلاَ آيَتَانِ فِي كِتَابِ اللَّهِ مَا حَدَّثْتُ حَدِيثًا", "a": "ulama-ka-kirdar.html#h-bukhari-118"}, "H:muslim:1920": {"l": "Sahih Muslim, Hadith 1920", "u": "https://sunnah.com/muslim:1920", "t": "A group will always remain upon the truth", "k": "لاَ تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي ظَاهِرِينَ عَلَى الْحَقِّ", "a": "deen-aur-firqe.html#h-muslim-1920"}, "H:muslim:1847a": {"l": "Sahih Muslim, Hadith 1847", "u": "https://sunnah.com/muslim:1847a", "t": "The hadith of Hudhayfah (Sahih Muslim)", "k": "قَوْمٌ يَسْتَنُّونَ بِغَيْرِ سُنَّتِي وَيَهْدُونَ بِغَيْرِ هَدْيِي … فَاعْتَزِلْ تِلْكَ الْفِرَقَ كُلَّهَا", "a": "deen-aur-firqe.html#h-muslim-1847a"}, "H:bukhari:5060": {"l": "Sahih al-Bukhari, Hadith 5060", "u": "https://sunnah.com/bukhari:5060", "t": "Recite the Quran while hearts agree; rise when you differ", "k": "اقْرَءُوا الْقُرْآنَ مَا ائْتَلَفَتْ قُلُوبُكُمْ، فَإِذَا اخْتَلَفْتُمْ فَقُومُوا عَنْهُ", "a": "ikhtilaf-ki-wajah.html#h-bukhari-5060"}, "Q:6:116": {"l": "Surah Al-An'aam, 6:116", "u": "https://quran.com/6/116", "ar": "وَإِن تُطِعْ أَكْثَرَ مَن فِى ٱلْأَرْضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِ ۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ ﴿١١٦﴾", "tr": "And if you obey most of those upon the earth, they will mislead you from the way of Allah. They follow not except assumption, and they are not but falsifying. (116)", "a": "maslaki-hatdharmi.html#q-6-116"}, "H:muslim:2673a": {"l": "Sahih Muslim, Hadith 2673", "u": "https://sunnah.com/muslim:2673a", "t": "The taking away of knowledge (Sahih Muslim)", "k": "اتَّخَذَ النَّاسُ رُءُوسًا جُهَّالاً فَسُئِلُوا فَأَفْتَوْا بِغَيْرِ عِلْمٍ فَضَلُّوا وَأَضَلُّوا", "a": "ulama-ka-kirdar.html#h-muslim-2673a"}, "H:muslim:2890a": {"l": "Sahih Muslim, Hadith 2890", "u": "https://sunnah.com/muslim:2890a", "t": "Three requests: the one about fighting among themselves was withheld", "k": "وَسَأَلْتُهُ أَنْ لاَ يَجْعَلَ بَأْسَهُمْ بَيْنَهُمْ فَمَنَعَنِيهَا", "a": "qaumon-ki-barbadi.html#h-muslim-2890a"}, "Q:3:164": {"l": "Surah Aal-i-Imraan, 3:164", "u": "https://quran.com/3/164", "ar": "لَقَدْ مَنَّ ٱللَّهُ عَلَى ٱلْمُؤْمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولًۭا مِّنْ أَنفُسِهِمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَٰلٍۢ مُّبِينٍ ﴿١٦٤﴾", "tr": "Certainly did Allah confer [great] favor upon the believers when He sent among them a Messenger from themselves, reciting to them His verses and purifying them and teaching them the Book and wisdom, although they had been before in manifest error. (164)", "a": "tazkiya-e-nafs.html#q-3-164"}, "H:bukhari:121": {"l": "Sahih al-Bukhari, Hadith 121", "u": "https://sunnah.com/bukhari:121", "t": "Do not strike one another's necks after me", "k": "لاَ تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ", "a": "firqa-parasti-se-bachao.html#h-bukhari-121"}, "Q:31:21": {"l": "Surah Luqman, 31:21", "u": "https://quran.com/31/21", "ar": "وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلْ نَتَّبِعُ مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ ۚ أَوَلَوْ كَانَ ٱلشَّيْطَٰنُ يَدْعُوهُمْ إِلَىٰ عَذَابِ ٱلسَّعِيرِ ﴿٢١﴾", "tr": "And when it is said to them, \"Follow what Allah has revealed,\" they say, \"Rather, we will follow that upon which we found our fathers.\" Even if Satan was inviting them to the punishment of the Blaze? (21)", "a": "maslaki-hatdharmi.html#q-31-21"}, "H:bukhari:2493": {"l": "Sahih al-Bukhari, Hadith 2493", "u": "https://sunnah.com/bukhari:2493", "t": "The parable of the ship: hold their hands and all are saved", "k": "فَإِنْ يَتْرُكُوهُمْ وَمَا أَرَادُوا هَلَكُوا جَمِيعًا", "a": "qaumon-ki-barbadi.html#h-bukhari-2493"}, "H:bukhari:6407": {"l": "Sahih al-Bukhari, Hadith 6407", "u": "https://sunnah.com/bukhari:6407", "t": "The one who remembers and the one who does not: living and dead", "k": "مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ وَالَّذِي لاَ يَذْكُرُ مَثَلُ الْحَىِّ وَالْمَيِّتِ", "a": "tazkiya-e-nafs.html#h-bukhari-6407"}, "Q:5:78-79": {"l": "Surah Al-Maaida, 5:78-79", "u": "https://quran.com/5/78-79", "ar": "لُعِنَ ٱلَّذِينَ كَفَرُوا۟ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبْنِ مَرْيَمَ ۚ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ ﴿٧٨﴾ كَانُوا۟ لَا يَتَنَاهَوْنَ عَن مُّنكَرٍۢ فَعَلُوهُ ۚ لَبِئْسَ مَا كَانُوا۟ يَفْعَلُونَ ﴿٧٩﴾", "tr": "Cursed were those who disbelieved among the Children of Israel by the tongue of David and of Jesus, the son of Mary. That was because they disobeyed and [habitually] transgressed. (78) They used not to prevent one another from wrongdoing that they did. How wretched was that which they were doing. (79)", "a": "qaumon-ki-barbadi.html#q-5-78-79"}, "Q:30:32": {"l": "Surah Ar-Room, 30:32", "u": "https://quran.com/30/32", "ar": "مِنَ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًۭا ۖ كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ ﴿٣٢﴾", "tr": "[Or] of those who have divided their religion and become sects, every faction rejoicing in what it has. (32)", "a": "deen-aur-firqe.html#q-30-31-32"}, "Q:5:14": {"l": "Surah Al-Maaida, 5:14", "u": "https://quran.com/5/14", "ar": "وَمِنَ ٱلَّذِينَ قَالُوٓا۟ إِنَّا نَصَٰرَىٰٓ أَخَذْنَا مِيثَٰقَهُمْ فَنَسُوا۟ حَظًّۭا مِّمَّا ذُكِّرُوا۟ بِهِۦ فَأَغْرَيْنَا بَيْنَهُمُ ٱلْعَدَاوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ ۚ وَسَوْفَ يُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُوا۟ يَصْنَعُونَ ﴿١٤﴾", "tr": "And from those who say, \"We are Christians\" We took their covenant; but they forgot a portion of that of which they were reminded. So We caused among them animosity and hatred until the Day of Resurrection. And Allah is going to inform them about what they used to do. (14)", "a": "ahle-kitab-ka-naqsha.html#q-5-14"}, "Q:10:19": {"l": "Surah Yunus, 10:19", "u": "https://quran.com/10/19", "ar": "وَمَا كَانَ ٱلنَّاسُ إِلَّآ أُمَّةًۭ وَٰحِدَةًۭ فَٱخْتَلَفُوا۟ ۚ وَلَوْلَا كَلِمَةٌۭ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ فِيمَا فِيهِ يَخْتَلِفُونَ ﴿١٩﴾", "tr": "And mankind was not but one community [united in religion], but [then] they differed. And if not for a word that preceded from your Lord, it would have been judged between them [immediately] concerning that over which they differ. (19)", "a": "ikhtilaf-ki-wajah.html#q-10-19"}, "Q:2:213": {"l": "Surah Al-Baqara, 2:213", "u": "https://quran.com/2/213", "ar": "كَانَ ٱلنَّاسُ أُمَّةًۭ وَٰحِدَةًۭ فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّۦنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلْكِتَٰبَ بِٱلْحَقِّ لِيَحْكُمَ بَيْنَ ٱلنَّاسِ فِيمَا ٱخْتَلَفُوا۟ فِيهِ ۚ وَمَا ٱخْتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ بَغْيًۢا بَيْنَهُمْ ۖ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ لِمَا ٱخْتَلَفُوا۟ فِيهِ مِنَ ٱلْحَقِّ بِإِذْنِهِۦ ۗ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍۢ مُّسْتَقِيمٍ ﴿٢١٣﴾", "tr": "Mankind was [of] one religion [before their deviation]; then Allah sent the prophets as bringers of good tidings and warners and sent down with them the Scripture in truth to judge between the people concerning that in which they differed. And none differed over the Scripture except those who were given it - after the clear proofs came to them - out of jealous animosity among themselves. And Allah guided those who believed to the truth concerning that over which they had differed, by His permission. And Allah guides whom He wills to a straight path. (213)", "a": "ikhtilaf-ki-wajah.html#q-2-213"}, "H:bukhari:1741": {"l": "Sahih al-Bukhari, Hadith 1741", "u": "https://sunnah.com/bukhari:1741", "t": "Let the one present convey to the one absent", "k": "فَلْيُبَلِّغِ الشَّاهِدُ الْغَائِبَ، فَرُبَّ مُبَلَّغٍ أَوْعَى مِنْ سَامِعٍ", "a": "imamon-ki-haisiyat.html#h-bukhari-1741"}, "Q:5:13": {"l": "Surah Al-Maaida, 5:13", "u": "https://quran.com/5/13", "ar": "فَبِمَا نَقْضِهِم مِّيثَٰقَهُمْ لَعَنَّٰهُمْ وَجَعَلْنَا قُلُوبَهُمْ قَٰسِيَةًۭ ۖ يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ ۙ وَنَسُوا۟ حَظًّۭا مِّمَّا ذُكِّرُوا۟ بِهِۦ ۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةٍۢ مِّنْهُمْ إِلَّا قَلِيلًۭا مِّنْهُمْ ۖ فَٱعْفُ عَنْهُمْ وَٱصْفَحْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ ﴿١٣﴾", "tr": "So for their breaking of the covenant We cursed them and made their hearts hard. They distort words from their [proper] usages and have forgotten a portion of that of which they were reminded. And you will still observe deceit among them, except a few of them. But pardon them and overlook [their misdeeds]. Indeed, Allah loves the doers of good. (13)", "a": "ahle-kitab-ka-naqsha.html#q-5-13"}, "Q:33:67": {"l": "Surah Al-Ahzaab, 33:67", "u": "https://quran.com/33/67", "ar": "وَقَالُوا۟ رَبَّنَآ إِنَّآ أَطَعْنَا سَادَتَنَا وَكُبَرَآءَنَا فَأَضَلُّونَا ٱلسَّبِيلَا۠ ﴿٦٧﴾", "tr": "And they will say, \"Our Lord, indeed we obeyed our masters and our dignitaries, and they led us astray from the [right] way. (67)", "a": "imamon-ki-haisiyat.html#q-33-66-68"}, "H:muslim:1337": {"l": "Sahih Muslim, Hadith 1337", "u": "https://sunnah.com/muslim:1337", "t": "The question about Hajj: ruin through many questions and differing (Sahih Muslim)", "k": "فَإِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِكَثْرَةِ سُؤَالِهِمْ وَاخْتِلاَفِهِمْ عَلَى أَنْبِيَائِهِمْ", "a": "ikhtilaf-ki-wajah.html#h-muslim-1337"}, "Q:64:16": {"l": "Surah At-Taghaabun, 64:16", "u": "https://quran.com/64/16", "ar": "فَٱتَّقُوا۟ ٱللَّهَ مَا ٱسْتَطَعْتُمْ وَٱسْمَعُوا۟ وَأَطِيعُوا۟ وَأَنفِقُوا۟ خَيْرًۭا لِّأَنفُسِكُمْ ۗ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ ﴿١٦﴾", "tr": "So fear Allah as much as you are able and listen and obey and spend [in the way of Allah]; it is better for your selves. And whoever is protected from the stinginess of his soul - it is those who will be the successful. (16)", "a": "tazkiya-e-nafs.html#q-64-16"}, "Q:24:48-51": {"l": "Surah An-Noor, 24:48-51", "u": "https://quran.com/24/48-51", "ar": "وَإِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ إِذَا فَرِيقٌۭ مِّنْهُم مُّعْرِضُونَ ﴿٤٨﴾ وَإِن يَكُن لَّهُمُ ٱلْحَقُّ يَأْتُوٓا۟ إِلَيْهِ مُذْعِنِينَ ﴿٤٩﴾ أَفِى قُلُوبِهِم مَّرَضٌ أَمِ ٱرْتَابُوٓا۟ أَمْ يَخَافُونَ أَن يَحِيفَ ٱللَّهُ عَلَيْهِمْ وَرَسُولُهُۥ ۚ بَلْ أُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ ﴿٥٠﴾ إِنَّمَا كَانَ قَوْلَ ٱلْمُؤْمِنِينَ إِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ أَن يَقُولُوا۟ سَمِعْنَا وَأَطَعْنَا ۚ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ ﴿٥١﴾", "tr": "And when they are called to [the words of] Allah and His Messenger to judge between them, at once a party of them turns aside [in refusal]. (48) But if the right is theirs, they come to him in prompt obedience. (49) Is there disease in their hearts? Or have they doubted? Or do they fear that Allah will be unjust to them, or His Messenger? Rather, it is they who are the wrongdoers. (50) The only statement of the [true] believers when they are called to Allah and His Messenger to judge between them is that they say, \"We hear and we obey.\" And those are the successful. (51)", "a": "maslaki-hatdharmi.html#q-24-48-51"}, "Q:38:26": {"l": "Surah Saad, 38:26", "u": "https://quran.com/38/26", "ar": "يَٰدَاوُۥدُ إِنَّا جَعَلْنَٰكَ خَلِيفَةًۭ فِى ٱلْأَرْضِ فَٱحْكُم بَيْنَ ٱلنَّاسِ بِٱلْحَقِّ وَلَا تَتَّبِعِ ٱلْهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِ ۚ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمْ عَذَابٌۭ شَدِيدٌۢ بِمَا نَسُوا۟ يَوْمَ ٱلْحِسَابِ ﴿٢٦﴾", "tr": "[We said], \"O David, indeed We have made you a successor upon the earth, so judge between the people in truth and do not follow [your own] desire, as it will lead you astray from the way of Allah.\" Indeed, those who go astray from the way of Allah will have a severe punishment for having forgotten the Day of Account. (26)", "a": "maslaki-hatdharmi.html#q-38-26"}, "Q:79:40-41": {"l": "Surah An-Naazi'aat, 79:40-41", "u": "https://quran.com/79/40-41", "ar": "وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفْسَ عَنِ ٱلْهَوَىٰ ﴿٤٠﴾ فَإِنَّ ٱلْجَنَّةَ هِىَ ٱلْمَأْوَىٰ ﴿٤١﴾", "tr": "But as for he who feared the position of his Lord and prevented the soul from [unlawful] inclination, (40) Then indeed, Paradise will be [his] refuge. (41)", "a": "tazkiya-e-nafs.html#q-79-40-41"}, "Q:6:44": {"l": "Surah Al-An'aam, 6:44", "u": "https://quran.com/6/44", "ar": "فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦ فَتَحْنَا عَلَيْهِمْ أَبْوَٰبَ كُلِّ شَىْءٍ حَتَّىٰٓ إِذَا فَرِحُوا۟ بِمَآ أُوتُوٓا۟ أَخَذْنَٰهُم بَغْتَةًۭ فَإِذَا هُم مُّبْلِسُونَ ﴿٤٤﴾", "tr": "So when they forgot that by which they had been reminded, We opened to them the doors of every [good] thing until, when they rejoiced in that which they were given, We seized them suddenly, and they were [then] in despair. (44)", "a": "qaumon-ki-barbadi.html#q-6-44"}, "H:muslim:2564c": {"l": "Sahih Muslim, Hadith 2564", "u": "https://sunnah.com/muslim:2564c", "t": "Allah looks at hearts and deeds", "k": "إِنَّ اللَّهَ لاَ يَنْظُرُ إِلَى صُوَرِكُمْ وَأَمْوَالِكُمْ وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ", "a": "tazkiya-e-nafs.html#h-muslim-2564c"}, "Q:91:9": {"l": "Surah Ash-Shams, 91:9", "u": "https://quran.com/91/9", "ar": "قَدْ أَفْلَحَ مَن زَكَّىٰهَا ﴿٩﴾", "tr": "He has succeeded who purifies it, (9)", "a": "tazkiya-e-nafs.html#q-91-7-10"}, "Q:42:10": {"l": "Surah Ash-Shura, 42:10", "u": "https://quran.com/42/10", "ar": "وَمَا ٱخْتَلَفْتُمْ فِيهِ مِن شَىْءٍۢ فَحُكْمُهُۥٓ إِلَى ٱللَّهِ ۚ ذَٰلِكُمُ ٱللَّهُ رَبِّى عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ ﴿١٠﴾", "tr": "And in anything over which you disagree - its ruling is [to be referred] to Allah. [Say], \"That is Allah, my Lord; upon Him I have relied, and to Him I turn back.\" (10)", "a": "firqa-parasti-se-bachao.html#q-42-10"}, "Q:35:18": {"l": "Surah Faatir, 35:18", "u": "https://quran.com/35/18", "ar": "وَلَا تَزِرُ وَازِرَةٌۭ وِزْرَ أُخْرَىٰ ۚ وَإِن تَدْعُ مُثْقَلَةٌ إِلَىٰ حِمْلِهَا لَا يُحْمَلْ مِنْهُ شَىْءٌۭ وَلَوْ كَانَ ذَا قُرْبَىٰٓ ۗ إِنَّمَا تُنذِرُ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ ۚ وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفْسِهِۦ ۚ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ ﴿١٨﴾", "tr": "And no bearer of burdens will bear the burden of another. And if a heavily laden soul calls [another] to [carry some of] its load, nothing of it will be carried, even if he should be a close relative. You can only warn those who fear their Lord unseen and have established prayer. And whoever purifies himself only purifies himself for [the benefit of] his soul. And to Allah is the [final] destination. (18)", "a": "tazkiya-e-nafs.html#q-35-18"}, "H:bukhari:5063": {"l": "Sahih al-Bukhari, Hadith 5063", "u": "https://sunnah.com/bukhari:5063", "t": "Whoever turns away from my Sunnah is not of me", "k": "فَمَنْ رَغِبَ عَنْ سُنَّتِي فَلَيْسَ مِنِّي", "a": "deen-aur-firqe.html#h-bukhari-5063"}, "Q:21:92-93": {"l": "Surah Al-Anbiyaa, 21:92-93", "u": "https://quran.com/21/92-93", "ar": "إِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةًۭ وَٰحِدَةًۭ وَأَنَا۠ رَبُّكُمْ فَٱعْبُدُونِ ﴿٩٢﴾ وَتَقَطَّعُوٓا۟ أَمْرَهُم بَيْنَهُمْ ۖ كُلٌّ إِلَيْنَا رَٰجِعُونَ ﴿٩٣﴾", "tr": "Indeed this, your religion, is one religion, and I am your Lord, so worship Me. (92) And [yet] they divided their affair among themselves, [but] all to Us will return. (93)", "a": "deen-aur-firqe.html#q-21-92-93"}, "Q:2:120": {"l": "Surah Al-Baqara, 2:120", "u": "https://quran.com/2/120", "ar": "وَلَن تَرْضَىٰ عَنكَ ٱلْيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمْ ۗ قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ ۗ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَ ٱلَّذِى جَآءَكَ مِنَ ٱلْعِلْمِ ۙ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّۢ وَلَا نَصِيرٍ ﴿١٢٠﴾", "tr": "And never will the Jews or the Christians approve of you until you follow their religion. Say, \"Indeed, the guidance of Allah is the [only] guidance.\" If you were to follow their desires after what has come to you of knowledge, you would have against Allah no protector or helper. (120)", "a": "ahle-kitab-ka-naqsha.html#q-2-120"}, "Q:6:159": {"l": "Surah Al-An'aam, 6:159", "u": "https://quran.com/6/159", "ar": "إِنَّ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًۭا لَّسْتَ مِنْهُمْ فِى شَىْءٍ ۚ إِنَّمَآ أَمْرُهُمْ إِلَى ٱللَّهِ ثُمَّ يُنَبِّئُهُم بِمَا كَانُوا۟ يَفْعَلُونَ ﴿١٥٩﴾", "tr": "Indeed, those who have divided their religion and become sects - you, [O Muhammad], are not [associated] with them in anything. Their affair is only [left] to Allah; then He will inform them about what they used to do. (159)", "a": "deen-aur-firqe.html#q-6-159"}, "H:muslim:1715a": {"l": "Sahih Muslim, Hadith 1715", "u": "https://sunnah.com/muslim:1715a", "t": "Allah is pleased with three things: tawhid and holding to the rope", "k": "فَيَرْضَى لَكُمْ أَنْ تَعْبُدُوهُ وَلاَ تُشْرِكُوا بِهِ شَيْئًا وَأَنْ تَعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلاَ تَفَرَّقُوا", "a": "deen-aur-firqe.html#h-muslim-1715a"}, "H:bukhari:3346": {"l": "Sahih al-Bukhari, Hadith 3346", "u": "https://sunnah.com/bukhari:3346", "t": "Will we perish with the righteous among us? Yes, when wickedness spreads", "k": "أَنَهْلِكُ وَفِينَا الصَّالِحُونَ", "a": "qaumon-ki-barbadi.html#h-bukhari-3346"}, "Q:13:28": {"l": "Surah Ar-Ra'd, 13:28", "u": "https://quran.com/13/28", "ar": "ٱلَّذِينَ ءَامَنُوا۟ وَتَطْمَئِنُّ قُلُوبُهُم بِذِكْرِ ٱللَّهِ ۗ أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ ﴿٢٨﴾", "tr": "Those who have believed and whose hearts are assured by the remembrance of Allah. Unquestionably, by the remembrance of Allah hearts are assured.\" (28)", "a": "tazkiya-e-nafs.html#q-13-28"}, "Q:39:18": {"l": "Surah Az-Zumar, 39:18", "u": "https://quran.com/39/18", "ar": "ٱلَّذِينَ يَسْتَمِعُونَ ٱلْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُۥٓ ۚ أُو۟لَٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُ ۖ وَأُو۟لَٰٓئِكَ هُمْ أُو۟لُوا۟ ٱلْأَلْبَٰبِ ﴿١٨﴾", "tr": "Who listen to speech and follow the best of it. Those are the ones Allah has guided, and those are people of understanding. (18)", "a": "maslaki-hatdharmi.html#q-39-17-18"}, "H:muslim:91a": {"l": "Sahih Muslim, Hadith 91", "u": "https://sunnah.com/muslim:91a", "t": "Pride: rejecting the truth and looking down on people", "k": "لاَ يَدْخُلُ الْجَنَّةَ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ كِبْرٍ … الْكِبْرُ بَطَرُ الْحَقِّ وَغَمْطُ النَّاسِ", "a": "maslaki-hatdharmi.html#h-muslim-91a"}, "Q:2:174-175": {"l": "Surah Al-Baqara, 2:174-175", "u": "https://quran.com/2/174-175", "ar": "إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلْكِتَٰبِ وَيَشْتَرُونَ بِهِۦ ثَمَنًۭا قَلِيلًا ۙ أُو۟لَٰٓئِكَ مَا يَأْكُلُونَ فِى بُطُونِهِمْ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوْمَ ٱلْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ ﴿١٧٤﴾ أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَٰلَةَ بِٱلْهُدَىٰ وَٱلْعَذَابَ بِٱلْمَغْفِرَةِ ۚ فَمَآ أَصْبَرَهُمْ عَلَى ٱلنَّارِ ﴿١٧٥﴾", "tr": "Indeed, they who conceal what Allah has sent down of the Book and exchange it for a small price - those consume not into their bellies except the Fire. And Allah will not speak to them on the Day of Resurrection, nor will He purify them. And they will have a painful punishment. (174) Those are the ones who have exchanged guidance for error and forgiveness for punishment. How patient they are in pursuit of the Fire! (175)", "a": "ulama-ka-kirdar.html#q-2-174-175"}, "Q:21:92": {"l": "Surah Al-Anbiyaa, 21:92", "u": "https://quran.com/21/92", "ar": "إِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةًۭ وَٰحِدَةًۭ وَأَنَا۠ رَبُّكُمْ فَٱعْبُدُونِ ﴿٩٢﴾", "tr": "Indeed this, your religion, is one religion, and I am your Lord, so worship Me. (92)", "a": "deen-aur-firqe.html#q-21-92-93"}, "Q:43:22": {"l": "Surah Az-Zukhruf, 43:22", "u": "https://quran.com/43/22", "ar": "بَلْ قَالُوٓا۟ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍۢ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّهْتَدُونَ ﴿٢٢﴾", "tr": "Rather, they say, \"Indeed, we found our fathers upon a religion, and we are in their footsteps [rightly] guided.\" (22)", "a": "maslaki-hatdharmi.html#q-43-22-24"}, "H:muslim:1718a": {"l": "Sahih Muslim, Hadith 1718", "u": "https://sunnah.com/muslim:1718a", "t": "A new matter in the religion is rejected (Sahih Muslim)", "k": "مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ مِنْهُ فَهُوَ رَدٌّ", "a": "deen-aur-firqe.html#h-muslim-1718a"}, "H:bukhari:1291": {"l": "Sahih al-Bukhari, Hadith 1291", "u": "https://sunnah.com/bukhari:1291", "t": "Lying about me is not like lying about anyone else", "k": "إِنَّ كَذِبًا عَلَىَّ لَيْسَ كَكَذِبٍ عَلَى أَحَدٍ", "a": "ulama-ka-kirdar.html#h-bukhari-1291"}, "H:bukhari:3267": {"l": "Sahih al-Bukhari, Hadith 3267", "u": "https://sunnah.com/bukhari:3267", "t": "The one who commanded good but did not do it", "k": "كُنْتُ آمُرُكُمْ بِالْمَعْرُوفِ وَلاَ آتِيهِ، وَأَنْهَاكُمْ عَنِ الْمُنْكَرِ وَآتِيهِ", "a": "ulama-ka-kirdar.html#h-bukhari-3267"}, "Q:24:21": {"l": "Surah An-Noor, 24:21", "u": "https://quran.com/24/21", "ar": "۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ ۚ وَمَن يَتَّبِعْ خُطُوَٰتِ ٱلشَّيْطَٰنِ فَإِنَّهُۥ يَأْمُرُ بِٱلْفَحْشَآءِ وَٱلْمُنكَرِ ۚ وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنْ أَحَدٍ أَبَدًۭا وَلَٰكِنَّ ٱللَّهَ يُزَكِّى مَن يَشَآءُ ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌۭ ﴿٢١﴾", "tr": "O you who have believed, do not follow the footsteps of Satan. And whoever follows the footsteps of Satan - indeed, he enjoins immorality and wrongdoing. And if not for the favor of Allah upon you and His mercy, not one of you would have been pure, ever, but Allah purifies whom He wills, and Allah is Hearing and Knowing. (21)", "a": "tazkiya-e-nafs.html#q-24-21"}, "H:muslim:1839a": {"l": "Sahih Muslim, Hadith 1839", "u": "https://sunnah.com/muslim:1839a", "t": "If commanded to sin, no listening and no obeying (Sahih Muslim)", "k": "إِلاَّ أَنْ يُؤْمَرَ بِمَعْصِيَةٍ فَإِنْ أُمِرَ بِمَعْصِيَةٍ فَلاَ سَمْعَ وَلاَ طَاعَةَ", "a": "imamon-ki-haisiyat.html#h-muslim-1839a"}, "Q:5:104": {"l": "Surah Al-Maaida, 5:104", "u": "https://quran.com/5/104", "ar": "وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُوا۟ حَسْبُنَا مَا وَجَدْنَا عَلَيْهِ ءَابَآءَنَآ ۚ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْلَمُونَ شَيْـًۭٔا وَلَا يَهْتَدُونَ ﴿١٠٤﴾", "tr": "And when it is said to them, \"Come to what Allah has revealed and to the Messenger,\" they say, \"Sufficient for us is that upon which we found our fathers.\" Even though their fathers knew nothing, nor were they guided? (104)", "a": "maslaki-hatdharmi.html#q-5-104"}, "Q:5:63": {"l": "Surah Al-Maaida, 5:63", "u": "https://quran.com/5/63", "ar": "لَوْلَا يَنْهَىٰهُمُ ٱلرَّبَّٰنِيُّونَ وَٱلْأَحْبَارُ عَن قَوْلِهِمُ ٱلْإِثْمَ وَأَكْلِهِمُ ٱلسُّحْتَ ۚ لَبِئْسَ مَا كَانُوا۟ يَصْنَعُونَ ﴿٦٣﴾", "tr": "Why do the rabbis and religious scholars not forbid them from saying what is sinful and devouring what is unlawful? How wretched is what they have been practicing. (63)", "a": "ulama-ka-kirdar.html#q-5-63"}, "Q:7:3": {"l": "Surah Al-A'raaf, 7:3", "u": "https://quran.com/7/3", "ar": "ٱتَّبِعُوا۟ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ وَلَا تَتَّبِعُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ۗ قَلِيلًۭا مَّا تَذَكَّرُونَ ﴿٣﴾", "tr": "Follow, [O mankind], what has been revealed to you from your Lord and do not follow other than Him any allies. Little do you remember. (3)", "a": "imamon-ki-haisiyat.html#q-7-3"}, "Q:3:187": {"l": "Surah Aal-i-Imraan, 3:187", "u": "https://quran.com/3/187", "ar": "وَإِذْ أَخَذَ ٱللَّهُ مِيثَٰقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكْتُمُونَهُۥ فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمْ وَٱشْتَرَوْا۟ بِهِۦ ثَمَنًۭا قَلِيلًۭا ۖ فَبِئْسَ مَا يَشْتَرُونَ ﴿١٨٧﴾", "tr": "And [mention, O Muhammad], when Allah took a covenant from those who were given the Scripture, [saying], \"You must make it clear to the people and not conceal it.\" But they threw it away behind their backs and exchanged it for a small price. And wretched is that which they purchased. (187)", "a": "ulama-ka-kirdar.html#q-3-187"}, "Q:39:17-18": {"l": "Surah Az-Zumar, 39:17-18", "u": "https://quran.com/39/17-18", "ar": "وَٱلَّذِينَ ٱجْتَنَبُوا۟ ٱلطَّٰغُوتَ أَن يَعْبُدُوهَا وَأَنَابُوٓا۟ إِلَى ٱللَّهِ لَهُمُ ٱلْبُشْرَىٰ ۚ فَبَشِّرْ عِبَادِ ﴿١٧﴾ ٱلَّذِينَ يَسْتَمِعُونَ ٱلْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُۥٓ ۚ أُو۟لَٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُ ۖ وَأُو۟لَٰٓئِكَ هُمْ أُو۟لُوا۟ ٱلْأَلْبَٰبِ ﴿١٨﴾", "tr": "But those who have avoided Taghut, lest they worship it, and turned back to Allah - for them are good tidings. So give good tidings to My servants (17) Who listen to speech and follow the best of it. Those are the ones Allah has guided, and those are people of understanding. (18)", "a": "maslaki-hatdharmi.html#q-39-17-18"}, "Q:22:45-46": {"l": "Surah Al-Hajj, 22:45-46", "u": "https://quran.com/22/45-46", "ar": "فَكَأَيِّن مِّن قَرْيَةٍ أَهْلَكْنَٰهَا وَهِىَ ظَالِمَةٌۭ فَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَبِئْرٍۢ مُّعَطَّلَةٍۢ وَقَصْرٍۢ مَّشِيدٍ ﴿٤٥﴾ أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَتَكُونَ لَهُمْ قُلُوبٌۭ يَعْقِلُونَ بِهَآ أَوْ ءَاذَانٌۭ يَسْمَعُونَ بِهَا ۖ فَإِنَّهَا لَا تَعْمَى ٱلْأَبْصَٰرُ وَلَٰكِن تَعْمَى ٱلْقُلُوبُ ٱلَّتِى فِى ٱلصُّدُورِ ﴿٤٦﴾", "tr": "And how many a city did We destroy while it was committing wrong - so it is [now] fallen into ruin - and [how many] an abandoned well and [how many] a lofty palace. (45) So have they not traveled through the earth and have hearts by which to reason and ears by which to hear? For indeed, it is not eyes that are blinded, but blinded are the hearts which are within the breasts. (46)", "a": "qaumon-ki-barbadi.html#q-22-45-46"}, "H:bukhari:7319": {"l": "Sahih al-Bukhari, Hadith 7319", "u": "https://sunnah.com/bukhari:7319", "t": "The ummah will take the way of earlier nations: Persia and Rome", "k": "لاَ تَقُومُ السَّاعَةُ حَتَّى تَأْخُذَ أُمَّتِي بِأَخْذِ الْقُرُونِ قَبْلَهَا", "a": "ahle-kitab-ka-naqsha.html#h-bukhari-7319"}, "Q:2:75": {"l": "Surah Al-Baqara, 2:75", "u": "https://quran.com/2/75", "ar": "۞ أَفَتَطْمَعُونَ أَن يُؤْمِنُوا۟ لَكُمْ وَقَدْ كَانَ فَرِيقٌۭ مِّنْهُمْ يَسْمَعُونَ كَلَٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَمُونَ ﴿٧٥﴾", "tr": "Do you covet [the hope, O believers], that they would believe for you while a party of them used to hear the words of Allah and then distort the Torah after they had understood it while they were knowing? (75)", "a": "ahle-kitab-ka-naqsha.html#q-2-75"}, "H:bukhari:7188": {"l": "Sahih al-Bukhari, Hadith 7188", "u": "https://sunnah.com/bukhari:7188", "t": "Most hateful to Allah: the fiercely quarrelsome", "k": "أَبْغَضُ الرِّجَالِ إِلَى اللَّهِ الأَلَدُّ الْخَصِمُ", "a": "maslaki-hatdharmi.html#h-bukhari-7188"}, "Q:6:65": {"l": "Surah Al-An'aam, 6:65", "u": "https://quran.com/6/65", "ar": "قُلْ هُوَ ٱلْقَادِرُ عَلَىٰٓ أَن يَبْعَثَ عَلَيْكُمْ عَذَابًۭا مِّن فَوْقِكُمْ أَوْ مِن تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعًۭا وَيُذِيقَ بَعْضَكُم بَأْسَ بَعْضٍ ۗ ٱنظُرْ كَيْفَ نُصَرِّفُ ٱلْءَايَٰتِ لَعَلَّهُمْ يَفْقَهُونَ ﴿٦٥﴾", "tr": "Say, \"He is the [one] Able to send upon you affliction from above you or from beneath your feet or to confuse you [so you become] sects and make you taste the violence of one another.\" Look how We diversify the signs that they might understand. (65)", "a": "qaumon-ki-barbadi.html#q-6-65"}, "Q:98:4": {"l": "Surah Al-Bayyina, 98:4", "u": "https://quran.com/98/4", "ar": "وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَةُ ﴿٤﴾", "tr": "Nor did those who were given the Scripture become divided until after there had come to them clear evidence. (4)", "a": "ikhtilaf-ki-wajah.html#q-98-4"}, "Q:49:10": {"l": "Surah Al-Hujuraat, 49:10", "u": "https://quran.com/49/10", "ar": "إِنَّمَا ٱلْمُؤْمِنُونَ إِخْوَةٌۭ فَأَصْلِحُوا۟ بَيْنَ أَخَوَيْكُمْ ۚ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُرْحَمُونَ ﴿١٠﴾", "tr": "The believers are but brothers, so make settlement between your brothers. And fear Allah that you may receive mercy. (10)", "a": "deen-aur-firqe.html#q-49-10"}, "H:muslim:2577a": {"l": "Sahih Muslim, Hadith 2577", "u": "https://sunnah.com/muslim:2577a", "t": "Hadith qudsi: it is only your deeds", "k": "يَا عِبَادِي إِنَّمَا هِيَ أَعْمَالُكُمْ أُحْصِيهَا لَكُمْ", "a": "tazkiya-e-nafs.html#h-muslim-2577a"}, "H:bukhari:52": {"l": "Sahih al-Bukhari, Hadith 52", "u": "https://sunnah.com/bukhari:52", "t": "A piece of flesh in the body: it is the heart", "k": "أَلاَ وَإِنَّ فِي الْجَسَدِ مُضْغَةً … أَلاَ وَهِيَ الْقَلْبُ", "a": "tazkiya-e-nafs.html#h-bukhari-52"}, "Q:2:85": {"l": "Surah Al-Baqara, 2:85", "u": "https://quran.com/2/85", "ar": "ثُمَّ أَنتُمْ هَٰٓؤُلَآءِ تَقْتُلُونَ أَنفُسَكُمْ وَتُخْرِجُونَ فَرِيقًۭا مِّنكُم مِّن دِيَٰرِهِمْ تَظَٰهَرُونَ عَلَيْهِم بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَإِن يَأْتُوكُمْ أُسَٰرَىٰ تُفَٰدُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْرَاجُهُمْ ۚ أَفَتُؤْمِنُونَ بِبَعْضِ ٱلْكِتَٰبِ وَتَكْفُرُونَ بِبَعْضٍۢ ۚ فَمَا جَزَآءُ مَن يَفْعَلُ ذَٰلِكَ مِنكُمْ إِلَّا خِزْىٌۭ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا ۖ وَيَوْمَ ٱلْقِيَٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلْعَذَابِ ۗ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ ﴿٨٥﴾", "tr": "Then, you are those [same ones who are] killing one another and evicting a party of your people from their homes, cooperating against them in sin and aggression. And if they come to you as captives, you ransom them, although their eviction was forbidden to you. So do you believe in part of the Scripture and disbelieve in part? Then what is the recompense for those who do that among you except disgrace in worldly life; and on the Day of Resurrection they will be sent back to the severest of punishment. And Allah is not unaware of what you do. (85)", "a": "ahle-kitab-ka-naqsha.html#q-2-85"}, "Q:23:52-53": {"l": "Surah Al-Muminoon, 23:52-53", "u": "https://quran.com/23/52-53", "ar": "وَإِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةًۭ وَٰحِدَةًۭ وَأَنَا۠ رَبُّكُمْ فَٱتَّقُونِ ﴿٥٢﴾ فَتَقَطَّعُوٓا۟ أَمْرَهُم بَيْنَهُمْ زُبُرًۭا ۖ كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ ﴿٥٣﴾", "tr": "And indeed this, your religion, is one religion, and I am your Lord, so fear Me.\" (52) But the people divided their religion among them into sects - each faction, in what it has, rejoicing. (53)", "a": "deen-aur-firqe.html#q-23-52-53"}, "H:bukhari:2697": {"l": "Sahih al-Bukhari, Hadith 2697", "u": "https://sunnah.com/bukhari:2697", "t": "A new matter in the religion is rejected", "k": "مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ فِيهِ فَهُوَ رَدٌّ", "a": "deen-aur-firqe.html#h-bukhari-2697"}, "H:muslim:1848a": {"l": "Sahih Muslim, Hadith 1848", "u": "https://sunnah.com/muslim:1848a", "t": "Leaving the community and blind partisanship", "k": "مَنْ خَرَجَ مِنَ الطَّاعَةِ وَفَارَقَ الْجَمَاعَةَ فَمَاتَ مَاتَ مِيتَةً جَاهِلِيَّةً", "a": "deen-aur-firqe.html#h-muslim-1848a"}, "H:muslim:2880a": {"l": "Sahih Muslim, Hadith 2880", "u": "https://sunnah.com/muslim:2880a", "t": "When wickedness spreads (Sahih Muslim)", "k": "أَنَهْلِكُ وَفِينَا الصَّالِحُونَ قَالَ ‏\"‏ نَعَمْ إِذَا كَثُرَ الْخَبَثُ", "a": "qaumon-ki-barbadi.html#h-muslim-2880a"}, "Q:91:10": {"l": "Surah Ash-Shams, 91:10", "u": "https://quran.com/91/10", "ar": "وَقَدْ خَابَ مَن دَسَّىٰهَا ﴿١٠﴾", "tr": "And he has failed who instills it [with corruption]. (10)", "a": "tazkiya-e-nafs.html#q-91-7-10"}, "Q:9:31": {"l": "Surah At-Tawba, 9:31", "u": "https://quran.com/9/31", "ar": "ٱتَّخَذُوٓا۟ أَحْبَارَهُمْ وَرُهْبَٰنَهُمْ أَرْبَابًۭا مِّن دُونِ ٱللَّهِ وَٱلْمَسِيحَ ٱبْنَ مَرْيَمَ وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوٓا۟ إِلَٰهًۭا وَٰحِدًۭا ۖ لَّآ إِلَٰهَ إِلَّا هُوَ ۚ سُبْحَٰنَهُۥ عَمَّا يُشْرِكُونَ ﴿٣١﴾", "tr": "They have taken their scholars and monks as lords besides Allah, and [also] the Messiah, the son of Mary. And they were not commanded except to worship one God; there is no deity except Him. Exalted is He above whatever they associate with Him. (31)", "a": "imamon-ki-haisiyat.html#q-9-31"}, "H:bukhari:7084": {"l": "Sahih al-Bukhari, Hadith 7084", "u": "https://sunnah.com/bukhari:7084", "t": "The hadith of Hudhayfah: stay with the community, or keep away from all sects", "k": "دُعَاةٌ عَلَى أَبْوَابِ جَهَنَّمَ، مَنْ أَجَابَهُمْ إِلَيْهَا قَذَفُوهُ فِيهَا … تَلْزَمُ جَمَاعَةَ الْمُسْلِمِينَ وَإِمَامَهُمْ … فَاعْتَزِلْ تِلْكَ الْفِرَقَ كُلَّهَا", "a": "deen-aur-firqe.html#h-bukhari-7084"}, "Q:16:44": {"l": "Surah An-Nahl, 16:44", "u": "https://quran.com/16/44", "ar": "بِٱلْبَيِّنَٰتِ وَٱلزُّبُرِ ۗ وَأَنزَلْنَآ إِلَيْكَ ٱلذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ وَلَعَلَّهُمْ يَتَفَكَّرُونَ ﴿٤٤﴾", "tr": "[We sent them] with clear proofs and written ordinances. And We revealed to you the message that you may make clear to the people what was sent down to them and that they might give thought. (44)", "a": "imamon-ki-haisiyat.html#q-16-43-44"}, "Q:24:51-52": {"l": "Surah An-Noor, 24:51-52", "u": "https://quran.com/24/51-52", "ar": "إِنَّمَا كَانَ قَوْلَ ٱلْمُؤْمِنِينَ إِذَا دُعُوٓا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِيَحْكُمَ بَيْنَهُمْ أَن يَقُولُوا۟ سَمِعْنَا وَأَطَعْنَا ۚ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ ﴿٥١﴾ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَيَخْشَ ٱللَّهَ وَيَتَّقْهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلْفَآئِزُونَ ﴿٥٢﴾", "tr": "The only statement of the [true] believers when they are called to Allah and His Messenger to judge between them is that they say, \"We hear and we obey.\" And those are the successful. (51) And whoever obeys Allah and His Messenger and fears Allah and is conscious of Him - it is those who are the attainers. (52)", "a": "imamon-ki-haisiyat.html#q-24-51-52"}, "Q:2:253": {"l": "Surah Al-Baqara, 2:253", "u": "https://quran.com/2/253", "ar": "۞ تِلْكَ ٱلرُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍۢ ۘ مِّنْهُم مَّن كَلَّمَ ٱللَّهُ ۖ وَرَفَعَ بَعْضَهُمْ دَرَجَٰتٍۢ ۚ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ ٱلْقُدُسِ ۗ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلَ ٱلَّذِينَ مِنۢ بَعْدِهِم مِّنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ وَلَٰكِنِ ٱخْتَلَفُوا۟ فَمِنْهُم مَّنْ ءَامَنَ وَمِنْهُم مَّن كَفَرَ ۚ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلُوا۟ وَلَٰكِنَّ ٱللَّهَ يَفْعَلُ مَا يُرِيدُ ﴿٢٥٣﴾", "tr": "Those messengers - some of them We caused to exceed others. Among them were those to whom Allah spoke, and He raised some of them in degree. And We gave Jesus, the Son of Mary, clear proofs, and We supported him with the Pure Spirit. If Allah had willed, those [generations] succeeding them would not have fought each other after the clear proofs had come to them. But they differed, and some of them believed and some of them disbelieved. And if Allah had willed, they would not have fought each other, but Allah does what He intends. (253)", "a": "ikhtilaf-ki-wajah.html#q-2-253"}, "H:muslim:1835c": {"l": "Sahih Muslim, Hadith 1835", "u": "https://sunnah.com/muslim:1835c", "t": "Whoever obeys me obeys Allah (Sahih Muslim)", "k": "مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ", "a": "imamon-ki-haisiyat.html#h-muslim-1835c"}, "Q:2:44": {"l": "Surah Al-Baqara, 2:44", "u": "https://quran.com/2/44", "ar": "۞ أَتَأْمُرُونَ ٱلنَّاسَ بِٱلْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ ٱلْكِتَٰبَ ۚ أَفَلَا تَعْقِلُونَ ﴿٤٤﴾", "tr": "Do you order righteousness of the people and forget yourselves while you recite the Scripture? Then will you not reason? (44)", "a": "ulama-ka-kirdar.html#q-2-44"}, "Q:30:31-32": {"l": "Surah Ar-Room, 30:31-32", "u": "https://quran.com/30/31-32", "ar": "۞ مُنِيبِينَ إِلَيْهِ وَٱتَّقُوهُ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَلَا تَكُونُوا۟ مِنَ ٱلْمُشْرِكِينَ ﴿٣١﴾ مِنَ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًۭا ۖ كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ ﴿٣٢﴾", "tr": "[Adhere to it], turning in repentance to Him, and fear Him and establish prayer and do not be of those who associate others with Allah (31) [Or] of those who have divided their religion and become sects, every faction rejoicing in what it has. (32)", "a": "deen-aur-firqe.html#q-30-31-32"}, "H:bukhari:4547": {"l": "Sahih al-Bukhari, Hadith 4547", "u": "https://sunnah.com/bukhari:4547", "t": "Beware of those who follow the ambiguous", "k": "فَإِذَا رَأَيْتَ الَّذِينَ يَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ، فَأُولَئِكَ الَّذِينَ سَمَّى اللَّهُ، فَاحْذَرُوهُمْ", "a": "ikhtilaf-ki-wajah.html#h-bukhari-4547"}, "Q:29:40": {"l": "Surah Al-Ankaboot, 29:40", "u": "https://quran.com/29/40", "ar": "فَكُلًّا أَخَذْنَا بِذَنۢبِهِۦ ۖ فَمِنْهُم مَّنْ أَرْسَلْنَا عَلَيْهِ حَاصِبًۭا وَمِنْهُم مَّنْ أَخَذَتْهُ ٱلصَّيْحَةُ وَمِنْهُم مَّنْ خَسَفْنَا بِهِ ٱلْأَرْضَ وَمِنْهُم مَّنْ أَغْرَقْنَا ۚ وَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ ﴿٤٠﴾", "tr": "So each We seized for his sin; and among them were those upon whom We sent a storm of stones, and among them were those who were seized by the blast [from the sky], and among them were those whom We caused the earth to swallow, and among them were those whom We drowned. And Allah would not have wronged them, but it was they who were wronging themselves. (40)", "a": "qaumon-ki-barbadi.html#q-29-40"}, "Q:5:66": {"l": "Surah Al-Maaida, 5:66", "u": "https://quran.com/5/66", "ar": "وَلَوْ أَنَّهُمْ أَقَامُوا۟ ٱلتَّوْرَىٰةَ وَٱلْإِنجِيلَ وَمَآ أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ لَأَكَلُوا۟ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِم ۚ مِّنْهُمْ أُمَّةٌۭ مُّقْتَصِدَةٌۭ ۖ وَكَثِيرٌۭ مِّنْهُمْ سَآءَ مَا يَعْمَلُونَ ﴿٦٦﴾", "tr": "And if only they upheld [the law of] the Torah, the Gospel, and what has been revealed to them from their Lord, they would have consumed [provision] from above them and from beneath their feet. Among them are a moderate community, but many of them - evil is that which they do. (66)", "a": "ahle-kitab-ka-naqsha.html#q-5-66"}, "Q:45:17": {"l": "Surah Al-Jaathiya, 45:17", "u": "https://quran.com/45/17", "ar": "وَءَاتَيْنَٰهُم بَيِّنَٰتٍۢ مِّنَ ٱلْأَمْرِ ۖ فَمَا ٱخْتَلَفُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۚ إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ ﴿١٧﴾", "tr": "And We gave them clear proofs of the matter [of religion]. And they did not differ except after knowledge had come to them - out of jealous animosity between themselves. Indeed, your Lord will judge between them on the Day of Resurrection concerning that over which they used to differ. (17)", "a": "ikhtilaf-ki-wajah.html#q-45-17"}, "H:bukhari:10": {"l": "Sahih al-Bukhari, Hadith 10", "u": "https://sunnah.com/bukhari:10", "t": "The Muslim is one from whose tongue and hand Muslims are safe", "k": "الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ", "a": "firqa-parasti-se-bachao.html#h-bukhari-10"}, "Q:16:43-44": {"l": "Surah An-Nahl, 16:43-44", "u": "https://quran.com/16/43-44", "ar": "وَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًۭا نُّوحِىٓ إِلَيْهِمْ ۚ فَسْـَٔلُوٓا۟ أَهْلَ ٱلذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ ﴿٤٣﴾ بِٱلْبَيِّنَٰتِ وَٱلزُّبُرِ ۗ وَأَنزَلْنَآ إِلَيْكَ ٱلذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ وَلَعَلَّهُمْ يَتَفَكَّرُونَ ﴿٤٤﴾", "tr": "And We sent not before you except men to whom We revealed [Our message]. So ask the people of the message if you do not know. (43) [We sent them] with clear proofs and written ordinances. And We revealed to you the message that you may make clear to the people what was sent down to them and that they might give thought. (44)", "a": "imamon-ki-haisiyat.html#q-16-43-44"}, "Q:62:2": {"l": "Surah Al-Jumu'a, 62:2", "u": "https://quran.com/62/2", "ar": "هُوَ ٱلَّذِى بَعَثَ فِى ٱلْأُمِّيِّۦنَ رَسُولًۭا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَٰلٍۢ مُّبِينٍۢ ﴿٢﴾", "tr": "It is He who has sent among the unlettered a Messenger from themselves reciting to them His verses and purifying them and teaching them the Book and wisdom - although they were before in clear error - (2)", "a": "tazkiya-e-nafs.html#q-62-2"}, "H:bukhari:4119": {"l": "Sahih al-Bukhari, Hadith 4119", "u": "https://sunnah.com/bukhari:4119", "t": "'Asr at Banu Qurayzah: he ﷺ blamed no one", "k": "لاَ يُصَلِّيَنَّ أَحَدٌ الْعَصْرَ إِلاَّ فِي بَنِي قُرَيْظَةَ … فَلَمْ يُعَنِّفْ وَاحِدًا مِنْهُمْ", "a": "firqa-parasti-se-bachao.html#h-bukhari-4119"}, "Q:42:14": {"l": "Surah Ash-Shura, 42:14", "u": "https://quran.com/42/14", "ar": "وَمَا تَفَرَّقُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۚ وَلَوْلَا كَلِمَةٌۭ سَبَقَتْ مِن رَّبِّكَ إِلَىٰٓ أَجَلٍۢ مُّسَمًّۭى لَّقُضِىَ بَيْنَهُمْ ۚ وَإِنَّ ٱلَّذِينَ أُورِثُوا۟ ٱلْكِتَٰبَ مِنۢ بَعْدِهِمْ لَفِى شَكٍّۢ مِّنْهُ مُرِيبٍۢ ﴿١٤﴾", "tr": "And they did not become divided until after knowledge had come to them - out of jealous animosity between themselves. And if not for a word that preceded from your Lord [postponing the penalty] until a specified time, it would have been concluded between them. And indeed, those who were granted inheritance of the Scripture after them are, concerning it, in disquieting doubt. (14)", "a": "ikhtilaf-ki-wajah.html#q-42-14"}, "H:bukhari:6011": {"l": "Sahih al-Bukhari, Hadith 6011", "u": "https://sunnah.com/bukhari:6011", "t": "Believers are like one body", "k": "تَرَى الْمُؤْمِنِينَ فِي تَرَاحُمِهِمْ وَتَوَادِّهِمْ وَتَعَاطُفِهِمْ كَمَثَلِ الْجَسَدِ", "a": "deen-aur-firqe.html#h-bukhari-6011"}, "Q:16:112": {"l": "Surah An-Nahl, 16:112", "u": "https://quran.com/16/112", "ar": "وَضَرَبَ ٱللَّهُ مَثَلًۭا قَرْيَةًۭ كَانَتْ ءَامِنَةًۭ مُّطْمَئِنَّةًۭ يَأْتِيهَا رِزْقُهَا رَغَدًۭا مِّن كُلِّ مَكَانٍۢ فَكَفَرَتْ بِأَنْعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلْجُوعِ وَٱلْخَوْفِ بِمَا كَانُوا۟ يَصْنَعُونَ ﴿١١٢﴾", "tr": "And Allah presents an example: a city which was safe and secure, its provision coming to it in abundance from every location, but it denied the favors of Allah. So Allah made it taste the envelopment of hunger and fear for what they had been doing. (112)", "a": "qaumon-ki-barbadi.html#q-16-112"}};
window.DIAGRAMS={"t1": {"type": "split", "title": "One rope, or scattered factions?", "hint": "Click both panels, then look at the further points below.", "left": {"label": "The rope of Allah: one ummah", "sub": "one religion, one path", "tone": "ok", "desc": "Holding together to the rope of Allah, one straight path, and believers being like one body.", "items": ["Hold the rope together", "One religion: Islam", "One straight path", "One body, one building"], "refs": [["Q:3:103", "وَٱعْتَصِمُوا۟ بِحَبْلِ ٱللَّهِ جَمِيعًۭا وَلَا تَفَرَّقُوا۟"], ["Q:21:92", ""], ["Q:6:153", "وَأَنَّ هَٰذَا صِرَٰطِى مُسْتَقِيمًۭا فَٱتَّبِعُوهُ"], ["H:bukhari:6011", "كَمَثَلِ الْجَسَدِ"]]}, "right": {"label": "The religion in pieces: factions", "sub": "each faction pleased with itself", "tone": "bad", "desc": "Splitting after clear proofs, cutting the religion into factions and following other paths.", "items": ["Differing after clear proofs", "Each faction rejoicing in itself", "Other paths: separation", "Dispute: weakness"], "refs": [["Q:3:105", ""], ["Q:30:32", "كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ"], ["Q:6:159", "لَّسْتَ مِنْهُمْ فِى شَىْءٍ"], ["Q:8:46", "وَلَا تَنَٰزَعُوا۟ فَتَفْشَلُوا۟"]]}, "chipsTitle": "Further points", "chips": [{"label": "The prophets' shared instruction", "desc": "Establish the religion and do not split in it.", "refs": [["Q:42:13", "أَنْ أَقِيمُوا۟ ٱلدِّينَ وَلَا تَتَفَرَّقُوا۟ فِيهِ"]]}, {"label": "What Allah is pleased with", "desc": "Tawhid, and holding to the rope together.", "refs": [["H:muslim:1715a", "وَأَنْ تَعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلاَ تَفَرَّقُوا"]]}, {"label": "What to do in trial?", "desc": "Stay with the community and its imam; otherwise keep away from all the sects.", "refs": [["H:bukhari:7084", "فَاعْتَزِلْ تِلْكَ الْفِرَقَ كُلَّهَا"]]}, {"label": "Innovation is rejected", "desc": "Every new matter introduced into the religion is rejected.", "refs": [["H:bukhari:2697", "فَهُوَ رَدٌّ"], ["H:muslim:867a", "وَكُلُّ بِدْعَةٍ ضَلاَلَةٌ"]]}]}, "t2": {"type": "flow", "title": "The chain of revelation: who commands, who conveys", "hint": "Click each link to see its evidence.", "nodes": [{"label": "Allah", "sub": "the command is His", "desc": "Allah sent down the religion; obedience to Him is the root, and disputes are judged by Him.", "refs": [["Q:4:59", "أَطِيعُوا۟ ٱللَّهَ"], ["Q:7:3", "ٱتَّبِعُوا۟ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ"]]}, {"label": "The Messenger ﷺ", "sub": "explains, is obeyed", "desc": "Obeying the Messenger is obeying Allah; he explains the revelation sent down.", "refs": [["Q:4:80", "مَّن يُطِعِ ٱلرَّسُولَ فَقَدْ أَطَاعَ ٱللَّهَ"], ["Q:16:44", "لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ"], ["Q:59:7", ""]]}, {"label": "Scholars and those in authority", "sub": "those who convey", "desc": "They learn and teach; obeyed only in what is right, never in sin; and they can err.", "refs": [["H:bukhari:79", "فَعَلِمَ وَعَلَّمَ"], ["H:bukhari:7257", "لاَ طَاعَةَ فِي مَعْصِيَةٍ"], ["H:bukhari:7352", "ثُمَّ أَخْطَأَ فَلَهُ أَجْرٌ"]]}, {"label": "The ummah", "sub": "returns disputes", "desc": "In disagreement the matter is returned to Allah and the Messenger, saying «we hear and we obey».", "refs": [["Q:4:59", "فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ"], ["Q:24:51", "سَمِعْنَا وَأَطَعْنَا"]]}, {"label": "The danger", "sub": "scholars as lords", "desc": "Earlier nations took their scholars and monks as lords besides Allah.", "refs": [["Q:9:31", "ٱتَّخَذُوٓا۟ أَحْبَارَهُمْ وَرُهْبَٰنَهُمْ أَرْبَابًۭا مِّن دُونِ ٱللَّهِ"], ["Q:33:67", ""]]}]}, "t3": {"type": "wheel", "title": "The causes of division at a glance", "hint": "Click any part of the circle or the centre to see the evidence for that cause.", "center": {"label": "Division", "sub": "after knowledge", "desc": "Mankind was one community; the Book came to end division, yet they differed after knowledge came.", "refs": [["Q:2:213", "كَانَ ٱلنَّاسُ أُمَّةًۭ وَٰحِدَةًۭ"], ["Q:10:19", ""]]}, "nodes": [{"label": "Rivalry", "sub": "baghy", "desc": "Obstinacy and the wish for superiority after knowledge came.", "refs": [["Q:3:19", "بَغْيًۢا بَيْنَهُمْ"], ["Q:42:14", ""], ["Q:45:17", ""]]}, {"label": "Desire", "sub": "following hawa", "desc": "Following one's desire without guidance from Allah.", "refs": [["Q:28:50", "وَمَنْ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ"], ["Q:45:23", ""]]}, {"label": "No knowledge", "sub": "speaking blindly", "desc": "Pursuing what one does not know and saying about Allah what one does not know.", "refs": [["Q:17:36", ""], ["Q:7:33", "وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ"]]}, {"label": "Ambiguous", "sub": "seeking discord", "desc": "Leaving the clear to chase the ambiguous; beware of such people.", "refs": [["Q:3:7", "فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنْهُ ٱبْتِغَآءَ ٱلْفِتْنَةِ"], ["H:bukhari:4547", "فَاحْذَرُوهُمْ"]]}, {"label": "Disputing", "sub": "over Book and prophets", "desc": "Quarrelling over the Book, needless questions and differing with prophets ruined those before.", "refs": [["H:muslim:2666", "بِاخْتِلاَفِهِمْ فِي الْكِتَابِ"], ["H:bukhari:7288", "بِسُؤَالِهِمْ وَاخْتِلاَفِهِمْ عَلَى أَنْبِيَائِهِمْ"]]}, {"label": "Rancour", "sub": "envy, suspicion", "desc": "Suspicion, envy, hatred and turning away; instead, be brothers.", "refs": [["H:bukhari:6066", "وَلاَ تَحَاسَدُوا، وَلاَ تَبَاغَضُوا"], ["H:bukhari:5060", "فَإِذَا اخْتَلَفْتُمْ فَقُومُوا عَنْهُ"]]}]}, "t4": {"type": "flow", "title": "The 'forefathers' loop, and the way out", "hint": "Click each stage: from the call to the truth to the return, each step shows its evidence.", "nodes": [{"label": "The call", "sub": "come to revelation", "desc": "One is called to what Allah sent down and to the Messenger.", "refs": [["Q:2:170", "ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ"], ["Q:5:104", "تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ"]]}, {"label": "The fathers", "sub": "we found them so", "desc": "The reply: we will do what we found our fathers upon, even if they were not guided.", "refs": [["Q:2:170", "بَلْ نَتَّبِعُ مَآ أَلْفَيْنَا عَلَيْهِ ءَابَآءَنَآ"], ["Q:43:22", ""], ["Q:7:28", ""]]}, {"label": "Pride", "sub": "rejecting truth", "desc": "Pride is rejecting the truth; arrogance makes one persist in sin.", "refs": [["H:muslim:91a", "الْكِبْرُ بَطَرُ الْحَقِّ وَغَمْطُ النَّاسِ"], ["Q:2:206", ""]]}, {"label": "Turning away", "sub": "accepting only what suits", "desc": "Turning away when called to judgement, accepting only what suits oneself.", "refs": [["Q:24:48", ""], ["Q:24:49", ""], ["Q:4:61", ""]]}, {"label": "The return", "sub": "we hear and obey", "desc": "The believer's answer is «we hear and we obey»; he listens and follows the best.", "refs": [["Q:24:51", "سَمِعْنَا وَأَطَعْنَا"], ["Q:39:18", "ٱلَّذِينَ يَسْتَمِعُونَ ٱلْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُۥٓ"]]}]}, "t5": {"type": "tree", "title": "The trust of knowledge: fulfilling it or betraying it", "hint": "Click the root and each branch. The first branch is fulfilling the trust; the others are forms of betraying it. (This division is an organising frame.)", "root": {"label": "Knowledge", "desc": "Knowledge is a trust from Allah; the People of the Book were bound by covenant to make it clear and not hide it.", "refs": [["Q:3:187", "لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكْتُمُونَهُۥ"], ["H:bukhari:71", "يُفَقِّهْهُ فِي الدِّينِ"]]}, "nodes": [{"label": "Convey ✓", "sub": "the trust fulfilled", "desc": "Convey from me even one verse; and act on it yourself.", "refs": [["H:bukhari:3461", "بَلِّغُوا عَنِّي وَلَوْ آيَةً"], ["Q:2:160", "وَبَيَّنُوا۟"]]}, {"label": "Concealing", "sub": "hiding the truth", "desc": "Hiding the guidance sent down and mixing truth with falsehood.", "refs": [["Q:2:159", ""], ["Q:2:42", ""]]}, {"label": "Selling", "sub": "a small price", "desc": "Taking the world in exchange for the verses and consuming people's wealth unjustly.", "refs": [["Q:9:9", ""], ["Q:9:34", ""], ["Q:2:174", ""]]}, {"label": "Inventing", "sub": "in the name of Allah and the Messenger", "desc": "Attributing one's own words to Allah or the Messenger ﷺ.", "refs": [["Q:2:79", ""], ["Q:16:116", ""], ["H:bukhari:1291", "مَنْ كَذَبَ عَلَىَّ مُتَعَمِّدًا"]]}, {"label": "Ignorant leaders", "sub": "verdicts without knowledge", "desc": "When scholars pass, ignorant leaders give verdicts without knowledge and mislead.", "refs": [["H:bukhari:100", "فَضَلُّوا وَأَضَلُّوا"]]}, {"label": "Not acting", "sub": "saying, not doing", "desc": "Commanding others and forgetting oneself; or knowledge for show.", "refs": [["Q:2:44", ""], ["H:bukhari:3267", ""], ["H:muslim:1905a", "لِيُقَالَ عَالِمٌ"]]}]}, "t6": {"type": "flow", "title": "The path of decline, and the door of return", "hint": "Click each stage: from blessing to corruption and back to return, see the evidence from the Quran and hadith.", "nodes": [{"label": "Blessing", "sub": "security and provision", "desc": "Allah gives a people security, peace and provision, and does not change it until they change.", "refs": [["Q:16:112", "كَانَتْ ءَامِنَةًۭ مُّطْمَئِنَّةًۭ"], ["Q:8:53", ""]]}, {"label": "Change within", "sub": "ingratitude, injustice, greed", "desc": "Ingratitude, double standards, the race for the world and greed change a people from within.", "refs": [["Q:13:11", "حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ"], ["H:bukhari:3475", "إِنَّمَا أَهْلَكَ الَّذِينَ قَبْلَكُمْ"], ["H:muslim:2578", "فَإِنَّ الشُّحَّ أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ"]]}, {"label": "Corruption", "sub": "hands' earnings", "desc": "When evil is not forbidden and people fight each other, corruption spreads.", "refs": [["Q:30:41", "بِمَا كَسَبَتْ أَيْدِى ٱلنَّاسِ"], ["H:bukhari:2493", "هَلَكُوا جَمِيعًا"], ["H:muslim:2890a", "بَأْسَهُمْ بَيْنَهُمْ"]]}, {"label": "Seizure", "sub": "for their own sin", "desc": "Each nation was seized for its sin; Allah did not wrong them, they wronged themselves.", "refs": [["Q:29:40", "فَكُلًّا أَخَذْنَا بِذَنۢبِهِۦ"], ["Q:6:44", "أَخَذْنَٰهُم بَغْتَةًۭ"]]}, {"label": "Return", "sub": "faith and mindfulness", "desc": "The purpose is return; faith and mindfulness open the blessings of heaven and earth.", "refs": [["Q:30:41", "لَعَلَّهُمْ يَرْجِعُونَ"], ["Q:7:96", "لَفَتَحْنَا عَلَيْهِم بَرَكَٰتٍۢ مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ"]]}]}, "t7": {"type": "tree", "title": "The mirror: errors of the People of the Book we were warned against", "hint": "Click the root (the prophecy), then each branch: each one is a warning. (This division is an organising frame.)", "root": {"label": "Ways of those before", "desc": "You will surely follow the ways of those before span by span; the Companions asked: the Jews and Christians? He said: who else?", "refs": [["H:bukhari:3456", "لَتَتَّبِعُنَّ سَنَنَ مَنْ قَبْلَكُمْ"], ["H:bukhari:7319", ""]]}, "nodes": [{"label": "Splitting", "sub": "after clear proofs", "desc": "Splitting after the clear proof came, then enmity until the Last Day.", "refs": [["Q:3:105", ""], ["Q:98:4", ""], ["Q:5:14", "فَأَغْرَيْنَا بَيْنَهُمُ ٱلْعَدَاوَةَ وَٱلْبَغْضَآءَ"]]}, {"label": "Hard hearts", "sub": "a long time", "desc": "Time grew long and hearts hardened.", "refs": [["Q:57:16", "فَقَسَتْ قُلُوبُهُمْ"], ["Q:5:13", ""]]}, {"label": "Excess", "sub": "beyond bounds", "desc": "Exaggerating about prophets and taking scholars as lords.", "refs": [["Q:4:171", ""], ["H:bukhari:3445", "لاَ تُطْرُونِي"], ["Q:9:31", ""]]}, {"label": "Graves", "sub": "as places of prostration", "desc": "Taking the graves of prophets and the righteous as places of prostration.", "refs": [["H:muslim:531", ""], ["H:muslim:532", "فَلاَ تَتَّخِذُوا الْقُبُورَ مَسَاجِدَ"]]}, {"label": "Distortion", "sub": "changing the words", "desc": "Changing Allah's words after understanding them, and attributing one's own writing to Allah.", "refs": [["Q:2:75", ""], ["Q:2:79", ""], ["H:bukhari:7363", ""]]}, {"label": "Picking parts", "sub": "leaving the rest", "desc": "Believing in part of the Book and denying part; turning away from its judgement.", "refs": [["Q:2:85", "أَفَتُؤْمِنُونَ بِبَعْضِ ٱلْكِتَٰبِ وَتَكْفُرُونَ بِبَعْضٍۢ"], ["Q:3:23", ""]]}]}, "t8": {"type": "checklist", "title": "A checklist of protection from sectarianism", "hint": "Click each point: its evidence appears and the point is ticked. Ticks are saved only in your browser.", "items": [{"label": "Hold the rope together", "desc": "Hold Allah's rope together and walk the one straight path.", "refs": [["Q:3:103", "وَٱعْتَصِمُوا۟ بِحَبْلِ ٱللَّهِ جَمِيعًۭا"], ["Q:6:153", ""]]}, {"label": "Return disputes to revelation", "desc": "Refer every dispute to Allah and the Messenger.", "refs": [["Q:4:59", "فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ"], ["Q:42:10", ""]]}, {"label": "Ask people of knowledge", "desc": "Instead of spreading a matter, take it to those who understand.", "refs": [["Q:4:83", ""]]}, {"label": "Breadth in differences", "desc": "Do not blame permitted differences, as the Prophet ﷺ did not.", "refs": [["H:bukhari:4119", "فَلَمْ يُعَنِّفْ وَاحِدًا مِنْهُمْ"], ["H:bukhari:2410", "كِلاَكُمَا مُحْسِنٌ"]]}, {"label": "Avoid takfir", "desc": "Do not call one who says the shahadah a disbeliever; Allah knows hearts.", "refs": [["H:bukhari:6103", ""], ["H:bukhari:391", ""], ["H:muslim:96a", "أَفَلاَ شَقَقْتَ عَنْ قَلْبِهِ"]]}, {"label": "Verify news", "desc": "Do not harm any group on the basis of hearsay.", "refs": [["Q:49:6", "فَتَبَيَّنُوٓا۟"]]}, {"label": "Guard the tongue", "desc": "Avoid mockery, fault-finding, insulting labels and abuse.", "refs": [["Q:49:11", ""], ["H:bukhari:10", ""], ["H:bukhari:48", "سِبَابُ الْمُسْلِمِ فُسُوقٌ"]]}, {"label": "Reconcile", "desc": "Believers are brothers; make peace between them with justice.", "refs": [["Q:49:10", ""], ["Q:49:9", ""], ["H:bukhari:2442", "الْمُسْلِمُ أَخُو الْمُسْلِمِ"]]}, {"label": "Keep the heart clean", "desc": "Love, the greeting of peace, and a prayer for a heart free of rancour.", "refs": [["H:muslim:54a", "أَفْشُوا السَّلاَمَ بَيْنَكُمْ"], ["Q:59:10", ""]]}, {"label": "Call with wisdom", "desc": "Wisdom, good admonition and the best argument; the model is the Messenger ﷺ.", "refs": [["Q:16:125", ""], ["Q:33:21", ""]]}]}, "t9": {"type": "split", "title": "Two paths: purifying or corrupting", "hint": "Click both panels, then see the means of purification below.", "left": {"label": "Successful: who purifies it", "sub": "the path of purity", "tone": "ok", "desc": "A sound intention, a sound heart, humility, forgiveness and control of desire.", "items": ["Sound intention", "A sound heart", "Humility and forgiveness", "Restraining desire"], "refs": [["Q:91:9", "قَدْ أَفْلَحَ مَن زَكَّىٰهَا"], ["H:bukhari:1", "إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ"], ["Q:26:89", "بِقَلْبٍۢ سَلِيمٍۢ"], ["Q:79:40", "وَنَهَى ٱلنَّفْسَ عَنِ ٱلْهَوَىٰ"]]}, "right": {"label": "Failed: who corrupts it", "sub": "the path of corruption", "tone": "bad", "desc": "Claiming purity, suspicion and backbiting, greed, anger and following desires.", "items": ["Claiming one's purity", "Suspicion and backbiting", "Greed", "Desires"], "refs": [["Q:91:10", "وَقَدْ خَابَ مَن دَسَّىٰهَا"], ["Q:53:32", "فَلَا تُزَكُّوٓا۟ أَنفُسَكُمْ"], ["Q:49:12", ""], ["H:bukhari:6487", "حُجِبَتِ النَّارُ بِالشَّهَوَاتِ"]]}, "chipsTitle": "Means of purification", "chips": [{"label": "Supplication", "desc": "Purification is Allah's grace, so ask Him for it.", "refs": [["H:muslim:2722", "وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا"], ["Q:24:21", ""]]}, {"label": "Remembrance", "desc": "Hearts find rest in the remembrance of Allah.", "refs": [["Q:13:28", "أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ"], ["H:bukhari:6407", ""]]}, {"label": "Seeking forgiveness", "desc": "The Prophet ﷺ sought forgiveness more than seventy times a day.", "refs": [["H:bukhari:6307", ""]]}, {"label": "Obligatory and voluntary deeds", "desc": "Obligations are most beloved, then nearness through voluntary deeds.", "refs": [["H:bukhari:6502", "يَتَقَرَّبُ إِلَىَّ بِالنَّوَافِلِ حَتَّى أُحِبَّهُ"]]}, {"label": "Ihsan", "desc": "Worship Allah as though you see Him.", "refs": [["H:bukhari:50", "كَأَنَّكَ تَرَاهُ"]]}]}};
window.QUIZ={"t1": [{"id": "t1-1", "q": "According to Al 'Imran 3:19, what is the religion in the sight of Allah?", "o": ["Islam", "Whatever came from one's forefathers", "Whatever the majority follows", "Each group's own religion"], "e": "«إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلْإِسْلَٰمُ»", "r": "Q:3:19"}, {"id": "t1-2", "q": "According to al-Hajj 22:78, what name did Allah give this ummah?", "o": ["Muslims", "A name after some imam", "A name after a region", "He gave no name"], "e": "«هُوَ سَمَّىٰكُمُ ٱلْمُسْلِمِينَ مِن قَبْلُ وَفِى هَٰذَا»", "r": "Q:22:78"}, {"id": "t1-3", "q": "What was declared about the religion in al-Ma'idah 5:3?", "o": ["This day I have perfected your religion for you", "The religion is still incomplete", "A new religion will come in every age", "The religion was left to the scholars"], "e": "«ٱلْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ»", "r": "Q:5:3"}, {"id": "t1-4", "q": "What command is given in Al 'Imran 3:103?", "o": ["Hold together to the rope of Allah and do not split", "Hold to your own group", "Follow only your elders", "Increase the differences"], "e": "«وَٱعْتَصِمُوا۟ بِحَبْلِ ٱللَّهِ جَمِيعًۭا وَلَا تَفَرَّقُوا۟»", "r": "Q:3:103"}, {"id": "t1-5", "q": "According to Al 'Imran 3:103, who joined the hearts together after enmity?", "o": ["Allah, by His favour", "Tribal treaties", "Wealth", "Kings"], "e": "«فَأَلَّفَ بَيْنَ قُلُوبِكُمْ فَأَصْبَحْتُم بِنِعْمَتِهِۦٓ إِخْوَٰنًۭا»", "r": "Q:3:103"}, {"id": "t1-6", "q": "According to Sahih Muslim 1715, which is among the three things Allah is pleased with?", "o": ["Holding together to the rope of Allah and not splitting", "Asking many questions", "Wasting wealth", "Idle talk"], "e": "«وَأَنْ تَعْتَصِمُوا بِحَبْلِ اللَّهِ جَمِيعًا وَلاَ تَفَرَّقُوا»", "r": "H:muslim:1715a"}, {"id": "t1-7", "q": "According to ash-Shura 42:13, what were Nuh, Ibrahim, Musa and 'Isa instructed?", "o": ["Establish the religion and do not be divided in it", "Make a separate sect for each prophet", "Call only your own people", "Keep adding to the religion"], "e": "«أَنْ أَقِيمُوا۟ ٱلدِّينَ وَلَا تَتَفَرَّقُوا۟ فِيهِ»", "r": "Q:42:13"}, {"id": "t1-8", "q": "What is said about the ummah in al-Anbiya' 21:92?", "o": ["This ummah of yours is one ummah", "There are countless ummahs", "Each region has its own ummah", "There is no concept of ummah"], "e": "«إِنَّ هَٰذِهِۦٓ أُمَّتُكُمْ أُمَّةًۭ وَٰحِدَةًۭ»", "r": "Q:21:92-93"}, {"id": "t1-9", "q": "According to al-Mu'minun 23:53, what is the state of each faction that split the religion?", "o": ["It rejoices in what it has", "It listens carefully to others", "It admits its mistake", "It loves everyone"], "e": "«كُلُّ حِزْبٍۭ بِمَا لَدَيْهِمْ فَرِحُونَ»", "r": "Q:23:52-53"}, {"id": "t1-10", "q": "According to al-An'am 6:159, what is the Prophet's ﷺ connection with those who split their religion into sects?", "o": ["None at all", "He is their leader", "He supports them", "He is with one of their groups"], "e": "«لَّسْتَ مِنْهُمْ فِى شَىْءٍ»", "r": "Q:6:159"}, {"id": "t1-11", "q": "In ar-Rum 30:31-32, with whom are those who split their religion mentioned?", "o": ["With the polytheists", "With the prophets", "With the martyrs", "With the angels"], "e": "«وَلَا تَكُونُوا۟ مِنَ ٱلْمُشْرِكِينَ» «مِنَ ٱلَّذِينَ فَرَّقُوا۟ دِينَهُمْ وَكَانُوا۟ شِيَعًۭا»", "r": "Q:30:31-32"}, {"id": "t1-12", "q": "According to Al 'Imran 3:105, when did the people we must not resemble split?", "o": ["After the clear proofs had come to them", "Because they had no knowledge", "Before a prophet came", "They never split"], "e": "«مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْبَيِّنَٰتُ»", "r": "Q:3:105"}, {"id": "t1-13", "q": "According to al-Anfal 8:46, what is the result of disputing among yourselves?", "o": ["Losing courage and strength", "More power", "Blessed provision", "Victory over the enemy"], "e": "«وَلَا تَنَٰزَعُوا۟ فَتَفْشَلُوا۟ وَتَذْهَبَ رِيحُكُمْ»", "r": "Q:8:46"}, {"id": "t1-14", "q": "According to al-An'am 6:153, what is the outcome of following other paths?", "o": ["They separate you from His way", "They also lead to Allah", "They complete the religion", "There is no harm in them"], "e": "«وَلَا تَتَّبِعُوا۟ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِۦ»", "r": "Q:6:153"}, {"id": "t1-15", "q": "In the sermon of Sahih Muslim 867, whose guidance is called the best?", "o": ["The guidance of Muhammad ﷺ", "Every elder's way", "The majority's way", "One's own sect's way"], "e": "«وَخَيْرُ الْهُدَى هُدَى مُحَمَّدٍ»", "r": "H:muslim:867a"}, {"id": "t1-16", "q": "According to Sahih al-Bukhari 2697, what is the ruling on something newly introduced into the religion?", "o": ["It is rejected", "It is a good deed", "It is obligatory", "It is recommended"], "e": "«مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ فِيهِ فَهُوَ رَدٌّ»", "r": "H:bukhari:2697"}, {"id": "t1-17", "q": "In the hadith of Hudhayfah, what is the instruction if there is neither a community nor an imam?", "o": ["Keep away from all the sects", "Join the strongest sect", "Start a new sect", "Take anyone you like as imam"], "e": "«فَاعْتَزِلْ تِلْكَ الْفِرَقَ كُلَّهَا»", "r": "H:bukhari:7084"}, {"id": "t1-18", "q": "In the same hadith, how are the «callers at the gates of Hell» described?", "o": ["From our own people, speaking our language", "Strangers from far away", "Only non-Muslim kings", "Jinn"], "e": "«هُمْ مِنْ جِلْدَتِنَا، وَيَتَكَلَّمُونَ بِأَلْسِنَتِنَا»", "r": "H:bukhari:7084"}, {"id": "t1-19", "q": "In Sahih al-Bukhari 6011, to what are the believers likened in their mutual love and mercy?", "o": ["One body", "Separate islands", "Different tribes", "A heap of stones"], "e": "«كَمَثَلِ الْجَسَدِ إِذَا اشْتَكَى عُضْوًا تَدَاعَى لَهُ سَائِرُ جَسَدِهِ بِالسَّهَرِ وَالْحُمَّى»", "r": "H:bukhari:6011"}], "t2": [{"id": "t2-1", "q": "According to an-Nisa' 4:59, to whom is a disagreement to be referred?", "o": ["To Allah and the Messenger", "To one's own imam", "To the majority opinion", "To the forefathers' way"], "e": "«فَإِن تَنَٰزَعْتُمْ فِى شَىْءٍۢ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ»", "r": "Q:4:59"}, {"id": "t2-2", "q": "In an-Nisa' 4:59, who is to be obeyed?", "o": ["Allah, the Messenger and those in authority among you", "Only scholars", "Only kings", "Every elder"], "e": "«أَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ وَأُو۟لِى ٱلْأَمْرِ مِنكُمْ»", "r": "Q:4:59"}, {"id": "t2-3", "q": "According to an-Nisa' 4:80, obeying the Messenger is in fact obeying whom?", "o": ["Allah", "The nation", "One's own self", "The commander"], "e": "«مَّن يُطِعِ ٱلرَّسُولَ فَقَدْ أَطَاعَ ٱللَّهَ»", "r": "Q:4:80"}, {"id": "t2-4", "q": "According to Al 'Imran 3:31, what is the way to Allah's love?", "o": ["Following the Messenger ﷺ", "Insisting on one's school", "Inventing new acts of worship", "Leaving the world"], "e": "«قُلْ إِن كُنتُمْ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِى يُحْبِبْكُمُ ٱللَّهُ»", "r": "Q:3:31-32"}, {"id": "t2-5", "q": "According to Sahih al-Bukhari 7137, obeying the commander is obeying whom?", "o": ["The Messenger ﷺ", "Only the commander personally", "The tribe", "No one"], "e": "«وَمَنْ أَطَاعَ أَمِيرِي فَقَدْ أَطَاعَنِي»", "r": "H:bukhari:7137"}, {"id": "t2-6", "q": "According to an-Nisa' 4:65, what is the condition of faith?", "o": ["Making the Messenger ﷺ judge in disputes and finding no discomfort in the heart", "Only a verbal declaration", "Accepting the elders' decision", "Arguing over every decision"], "e": "«حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا۟ فِىٓ أَنفُسِهِمْ حَرَجًۭا مِّمَّا قَضَيْتَ»", "r": "Q:4:65"}, {"id": "t2-7", "q": "According to al-Ahzab 33:36, what choice does a believer have after Allah and His Messenger decide?", "o": ["No choice remains", "He may choose what he likes", "He may change it after asking his imam", "The majority may change it"], "e": "«إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمْرًا أَن يَكُونَ لَهُمُ ٱلْخِيَرَةُ مِنْ أَمْرِهِمْ»", "r": "Q:33:36"}, {"id": "t2-8", "q": "According to an-Nur 24:51, what do the believers answer when called to Allah and His Messenger?", "o": ["We hear and we obey", "We will ask our elders", "We will think about it", "It is against our school"], "e": "«أَن يَقُولُوا۟ سَمِعْنَا وَأَطَعْنَا»", "r": "Q:24:51-52"}, {"id": "t2-9", "q": "What is the general principle of al-Hashr 59:7?", "o": ["Take what the Messenger gives and refrain from what he forbids", "Take what you like", "Only the Quran, not the Messenger's word", "Accept every word of your imam"], "e": "«وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمْ عَنْهُ فَٱنتَهُوا۟»", "r": "Q:59:7"}, {"id": "t2-10", "q": "According to Sahih al-Bukhari 7144, what is to be done if one in authority commands a sin?", "o": ["No listening and no obeying", "Obey at once", "Obey half of it", "Obey quietly"], "e": "«فَإِذَا أُمِرَ بِمَعْصِيَةٍ فَلاَ سَمْعَ وَلاَ طَاعَةَ»", "r": "H:bukhari:7144"}, {"id": "t2-11", "q": "In the incident of the commander who ordered his men into the fire, what principle did the Prophet ﷺ state?", "o": ["No obedience in sin; obedience is only in what is right", "Every order of the commander must be obeyed", "Questioning the commander is forbidden", "The commander never errs"], "e": "«لاَ طَاعَةَ فِي مَعْصِيَةٍ، إِنَّمَا الطَّاعَةُ فِي الْمَعْرُوفِ»", "r": "H:bukhari:7257"}, {"id": "t2-12", "q": "According to Sahih al-Bukhari 7352, what does one who strives and errs receive?", "o": ["One reward", "Two rewards", "A sin", "Nothing"], "e": "«وَإِذَا حَكَمَ فَاجْتَهَدَ ثُمَّ أَخْطَأَ فَلَهُ أَجْرٌ»", "r": "H:bukhari:7352"}, {"id": "t2-13", "q": "In Sahih al-Bukhari 79, whom does the best land represent?", "o": ["One who understood the religion, learned and taught", "One who concealed knowledge", "One who did not even raise his head", "One who only argued"], "e": "«فَذَلِكَ مَثَلُ مَنْ فَقِهَ فِي دِينِ اللَّهِ وَنَفَعَهُ مَا بَعَثَنِي اللَّهُ بِهِ، فَعَلِمَ وَعَلَّمَ»", "r": "H:bukhari:79"}, {"id": "t2-14", "q": "What did the Prophet ﷺ command in Sahih al-Bukhari 3461?", "o": ["Convey from me even if it is one verse", "Only scholars may speak", "Convey nothing", "Convey your own opinion"], "e": "«بَلِّغُوا عَنِّي وَلَوْ آيَةً»", "r": "H:bukhari:3461"}, {"id": "t2-15", "q": "According to an-Nahl 16:44, why was the Reminder sent down to the Prophet ﷺ?", "o": ["So that he makes clear to people what was sent down to them", "Only to be recited", "So that scholars may make rulings of their own", "To keep it closed"], "e": "«وَأَنزَلْنَآ إِلَيْكَ ٱلذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ»", "r": "Q:16:43-44"}, {"id": "t2-16", "q": "According to at-Tawbah 9:31, what did the People of the Book make of their scholars and monks?", "o": ["Lords besides Allah", "Merely teachers", "Servants", "Enemies"], "e": "«ٱتَّخَذُوٓا۟ أَحْبَارَهُمْ وَرُهْبَٰنَهُمْ أَرْبَابًۭا مِّن دُونِ ٱللَّهِ»", "r": "Q:9:31"}, {"id": "t2-17", "q": "What does al-A'raf 7:3 command us to follow?", "o": ["What was sent down from your Lord", "Whatever patrons say", "Whatever the majority does", "Whatever the forefathers did"], "e": "«ٱتَّبِعُوا۟ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ وَلَا تَتَّبِعُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ»", "r": "Q:7:3"}, {"id": "t2-18", "q": "In al-Ahzab 33:67, whose obedience will the people of Hell blame for their straying?", "o": ["Their masters and great ones", "Allah", "The Messenger", "Their children"], "e": "«رَبَّنَآ إِنَّآ أَطَعْنَا سَادَتَنَا وَكُبَرَآءَنَا فَأَضَلُّونَا ٱلسَّبِيلَا۠»", "r": "Q:33:66-68"}, {"id": "t2-19", "q": "According to al-Baqarah 2:166, what will the leaders do with their followers on the Day of Resurrection?", "o": ["Disown them", "Intercede for them", "Carry their burden", "Take them to Paradise"], "e": "«إِذْ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُوا۟ مِنَ ٱلَّذِينَ ٱتَّبَعُوا۟»", "r": "Q:2:166-167"}], "t3": [{"id": "t3-1", "q": "According to al-Baqarah 2:213, why did Allah send down the Book with the prophets?", "o": ["To judge between people in what they differed", "So that new sects arise", "Only for recitation", "So that each group interprets it its own way"], "e": "«وَأَنزَلَ مَعَهُمُ ٱلْكِتَٰبَ بِٱلْحَقِّ لِيَحْكُمَ بَيْنَ ٱلنَّاسِ فِيمَا ٱخْتَلَفُوا۟ فِيهِ»", "r": "Q:2:213"}, {"id": "t3-2", "q": "According to Yunus 10:19, what was the state of mankind at first?", "o": ["One community, then they differed", "Always divided", "Without religion", "Each had his own religion"], "e": "«وَمَا كَانَ ٱلنَّاسُ إِلَّآ أُمَّةًۭ وَٰحِدَةًۭ فَٱخْتَلَفُوا۟»", "r": "Q:10:19"}, {"id": "t3-3", "q": "According to Hud 11:119, who is saved from division?", "o": ["Those on whom Allah has mercy", "Those who argue the most", "Those in the majority", "The wealthiest"], "e": "«إِلَّا مَن رَّحِمَ رَبُّكَ»", "r": "Q:11:118-119"}, {"id": "t3-4", "q": "According to Al 'Imran 3:19, when and why did the People of the Book differ?", "o": ["After knowledge came, out of rivalry among themselves", "Because they lacked knowledge", "Because the Book was incomplete", "Because there was no prophet"], "e": "«إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ»", "r": "Q:3:19"}, {"id": "t3-5", "q": "What cause of division is given in ash-Shura 42:14?", "o": ["Rivalry among themselves after knowledge came", "Poverty", "Wars", "Different languages"], "e": "«وَمَا تَفَرَّقُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ»", "r": "Q:42:14"}, {"id": "t3-6", "q": "According to al-Jathiyah 45:17, when will their differences be judged?", "o": ["On the Day of Resurrection, by their Lord", "Never", "By majority vote", "By a committee of scholars"], "e": "«إِنَّ رَبَّكَ يَقْضِى بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ»", "r": "Q:45:17"}, {"id": "t3-7", "q": "According to al-Bayyinah 98:4, when did the People of the Book divide?", "o": ["After the clear evidence came to them", "Before any evidence came", "They never divided", "Only in wartime"], "e": "«إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَةُ»", "r": "Q:98:4"}, {"id": "t3-8", "q": "According to al-Qasas 28:50, who is the most astray?", "o": ["One who follows his desire without guidance from Allah", "One with little schooling", "One who is poor", "One who asks questions"], "e": "«وَمَنْ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيْرِ هُدًۭى مِّنَ ٱللَّهِ»", "r": "Q:28:50"}, {"id": "t3-9", "q": "According to al-Mu'minun 23:71, what would happen if the truth followed people's desires?", "o": ["The heavens, the earth and all within them would be ruined", "Everyone would unite", "Nothing would change", "Religion would become easy"], "e": "«وَلَوِ ٱتَّبَعَ ٱلْحَقُّ أَهْوَآءَهُمْ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ وَمَن فِيهِنَّ»", "r": "Q:23:71"}, {"id": "t3-10", "q": "Who is described in al-Jathiyah 45:23?", "o": ["One who took his desire as his god", "One who gained knowledge", "One who emigrated", "One who gave charity"], "e": "«أَفَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ»", "r": "Q:45:23"}, {"id": "t3-11", "q": "What does al-Isra' 17:36 forbid?", "o": ["Pursuing what you have no knowledge of", "Seeking knowledge", "Asking questions", "Travelling"], "e": "«وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ»", "r": "Q:17:36"}, {"id": "t3-12", "q": "Which of these is among the things forbidden in al-A'raf 7:33?", "o": ["Saying about Allah what you do not know", "Remembering Allah", "Teaching knowledge", "Reciting the Quran"], "e": "«وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ»", "r": "Q:7:33"}, {"id": "t3-13", "q": "According to Al 'Imran 3:7, who chase the ambiguous verses?", "o": ["Those in whose hearts is deviation", "Those firm in knowledge", "All believers", "The angels"], "e": "«فَأَمَّا ٱلَّذِينَ فِى قُلُوبِهِمْ زَيْغٌۭ فَيَتَّبِعُونَ مَا تَشَٰبَهَ مِنْهُ»", "r": "Q:3:7"}, {"id": "t3-14", "q": "In Sahih al-Bukhari 4547, what is the instruction about those who chase the ambiguous?", "o": ["Beware of them", "Follow them", "Debate them", "Make them your imams"], "e": "«فَأُولَئِكَ الَّذِينَ سَمَّى اللَّهُ، فَاحْذَرُوهُمْ»", "r": "H:bukhari:4547"}, {"id": "t3-15", "q": "According to Sahih Muslim 2666, why did earlier nations perish?", "o": ["Because of their differing over the Book", "Because of famine", "Because of earthquakes", "Because of too much worship"], "e": "«إِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِاخْتِلاَفِهِمْ فِي الْكِتَابِ»", "r": "H:muslim:2666"}, {"id": "t3-16", "q": "According to Sahih al-Bukhari 7288, what is the principle regarding the Prophet's ﷺ commands?", "o": ["Do what he commands as much as you can, and avoid what he forbids", "Question every command first", "Do only what seems easy", "Do it after asking your imam"], "e": "«فَإِذَا نَهَيْتُكُمْ عَنْ شَىْءٍ فَاجْتَنِبُوهُ، وَإِذَا أَمَرْتُكُمْ بِأَمْرٍ فَأْتُوا مِنْهُ مَا اسْتَطَعْتُمْ»", "r": "H:bukhari:7288"}, {"id": "t3-17", "q": "In Sahih al-Bukhari 3476, what did the Prophet ﷺ say about the difference in recitation?", "o": ["Both of you are doing well; do not differ", "Declare one of them astray", "Both of you are wrong", "Keep arguing"], "e": "«كِلاَكُمَا مُحْسِنٌ، وَلاَ تَخْتَلِفُوا»", "r": "H:bukhari:3476"}, {"id": "t3-18", "q": "According to Sahih al-Bukhari 6066, what is suspicion?", "o": ["The most false of speech", "Caution", "Intelligence", "Righteousness"], "e": "«فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ»", "r": "H:bukhari:6066"}, {"id": "t3-19", "q": "According to Sahih al-Bukhari 5060, what should be done when people begin to differ over the Quran?", "o": ["Get up and leave it", "Raise one's voice", "Call the opponent a disbeliever", "Win the argument"], "e": "«فَإِذَا اخْتَلَفْتُمْ فَقُومُوا عَنْهُ»", "r": "H:bukhari:5060"}], "t4": [{"id": "t4-1", "q": "According to al-Baqarah 2:170, what do they answer when told to follow what Allah sent down?", "o": ["We will follow what we found our fathers upon", "We accept at once", "We will look at the evidence", "We will ask the scholars"], "e": "«قَالُوا۟ بَلْ نَتَّبِعُ مَآ أَلْفَيْنَا عَلَيْهِ ءَابَآءَنَآ»", "r": "Q:2:170"}, {"id": "t4-2", "q": "What question does al-Baqarah 2:170 raise about their argument?", "o": ["Even if their fathers understood nothing and were not guided?", "Were the fathers rich?", "Were the fathers many?", "Were the fathers famous?"], "e": "«أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْقِلُونَ شَيْـًۭٔا وَلَا يَهْتَدُونَ»", "r": "Q:2:170"}, {"id": "t4-3", "q": "In al-Ma'idah 5:104, to what is the call made?", "o": ["To what Allah sent down and to the Messenger", "To one's elders", "To one's party", "To the world"], "e": "«تَعَالَوْا۟ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ»", "r": "Q:5:104"}, {"id": "t4-4", "q": "According to Luqman 31:21, where can blind following of the fathers lead?", "o": ["Shaytan may be calling them to the punishment of the Blaze", "They gain wealth", "They become famous", "Their family grows strong"], "e": "«أَوَلَوْ كَانَ ٱلشَّيْطَٰنُ يَدْعُوهُمْ إِلَىٰ عَذَابِ ٱلسَّعِيرِ»", "r": "Q:31:21"}, {"id": "t4-5", "q": "According to az-Zukhruf 43:23, who gave this argument in every town?", "o": ["Its affluent ones", "Its poor", "Its prophets", "Its children"], "e": "«إِلَّا قَالَ مُتْرَفُوهَآ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍۢ»", "r": "Q:43:22-24"}, {"id": "t4-6", "q": "What did the messenger ask in az-Zukhruf 43:24?", "o": ["Even if I bring you better guidance than what you found your fathers upon?", "Will you give me wealth?", "Will you fight with me?", "Will you emigrate?"], "e": "«أَوَلَوْ جِئْتُكُم بِأَهْدَىٰ مِمَّا وَجَدتُّمْ عَلَيْهِ ءَابَآءَكُمْ»", "r": "Q:43:22-24"}, {"id": "t4-7", "q": "In Yunus 10:78, what did Pharaoh's people accuse Musa of?", "o": ["Coming to turn them away from their fathers' way", "Wanting wealth", "Not knowing magic", "Being their friend"], "e": "«أَجِئْتَنَا لِتَلْفِتَنَا عَمَّا وَجَدْنَا عَلَيْهِ ءَابَآءَنَا»", "r": "Q:10:78"}, {"id": "t4-8", "q": "According to al-A'raf 7:28, what two claims did they make about their indecent deed?", "o": ["Our fathers did it, and Allah commanded it", "It is something new", "It has benefits", "Everyone does it"], "e": "«قَالُوا۟ وَجَدْنَا عَلَيْهَآ ءَابَآءَنَا وَٱللَّهُ أَمَرَنَا بِهَا»", "r": "Q:7:28"}, {"id": "t4-9", "q": "What answer to their claim is given in al-A'raf 7:28?", "o": ["Allah does not command indecency", "Allah really did command it", "The fathers were excused", "No answer was given"], "e": "«قُلْ إِنَّ ٱللَّهَ لَا يَأْمُرُ بِٱلْفَحْشَآءِ»", "r": "Q:7:28"}, {"id": "t4-10", "q": "According to an-Nur 24:49, when does the party that turns away come obediently?", "o": ["When the right is on their side", "Always", "Never", "When their imam says so"], "e": "«وَإِن يَكُن لَّهُمُ ٱلْحَقُّ يَأْتُوٓا۟ إِلَيْهِ مُذْعِنِينَ»", "r": "Q:24:48-51"}, {"id": "t4-11", "q": "In an-Nisa' 4:61, what are those called who turn away when called to Allah and the Messenger?", "o": ["Hypocrites", "Believers", "The righteous", "Martyrs"], "e": "«رَأَيْتَ ٱلْمُنَٰفِقِينَ يَصُدُّونَ عَنكَ صُدُودًۭا»", "r": "Q:4:61"}, {"id": "t4-12", "q": "In Sahih Muslim 91, how is pride defined?", "o": ["Rejecting the truth and looking down on people", "Wearing good clothes", "Wearing good shoes", "Liking beauty"], "e": "«الْكِبْرُ بَطَرُ الْحَقِّ وَغَمْطُ النَّاسِ»", "r": "H:muslim:91a"}, {"id": "t4-13", "q": "In Sahih Muslim 2021, what stopped the man from eating with his right hand?", "o": ["Pride", "Illness", "Forgetfulness", "Shyness"], "e": "«مَا مَنَعَهُ إِلاَّ الْكِبْرُ»", "r": "H:muslim:2021"}, {"id": "t4-14", "q": "According to al-Baqarah 2:206, how does the arrogant react when told to fear Allah?", "o": ["Pride in his sin takes hold of him", "He repents at once", "He weeps", "He gives thanks"], "e": "«وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتْهُ ٱلْعِزَّةُ بِٱلْإِثْمِ»", "r": "Q:2:206"}, {"id": "t4-15", "q": "According to al-A'raf 7:146, what do the arrogant do when they see the way of right guidance?", "o": ["They do not take it", "They take it at once", "They tell others", "They reflect on it"], "e": "«وَإِن يَرَوْا۟ سَبِيلَ ٱلرُّشْدِ لَا يَتَّخِذُوهُ سَبِيلًۭا»", "r": "Q:7:146"}, {"id": "t4-16", "q": "According to al-An'am 6:116, what is the result of obeying most of those on earth?", "o": ["They will lead you astray from Allah's way", "You will find the truth", "Unity will result", "No harm"], "e": "«وَإِن تُطِعْ أَكْثَرَ مَن فِى ٱلْأَرْضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِ»", "r": "Q:6:116"}, {"id": "t4-17", "q": "In Sad 38:26, what was Dawud told not to follow?", "o": ["Desire", "Truth", "Justice", "The law"], "e": "«وَلَا تَتَّبِعِ ٱلْهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِ»", "r": "Q:38:26"}, {"id": "t4-18", "q": "According to Sahih al-Bukhari 7188, who is the most hateful of men to Allah?", "o": ["The fiercely quarrelsome", "The quiet one", "The one with little knowledge", "The poor"], "e": "«أَبْغَضُ الرِّجَالِ إِلَى اللَّهِ الأَلَدُّ الْخَصِمُ»", "r": "H:bukhari:7188"}, {"id": "t4-19", "q": "According to az-Zumar 39:18, who are the people of understanding?", "o": ["Those who listen and follow the best of what is said", "Those who never listen to anyone", "Those who only speak their own word", "Those who win arguments"], "e": "«ٱلَّذِينَ يَسْتَمِعُونَ ٱلْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُۥٓ»", "r": "Q:39:17-18"}], "t5": [{"id": "t5-1", "q": "What covenant was taken from the People of the Book in Al 'Imran 3:187?", "o": ["To make the Book clear to people and not hide it", "To keep it among scholars only", "Not to read it", "To sell it"], "e": "«لَتُبَيِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكْتُمُونَهُۥ»", "r": "Q:3:187"}, {"id": "t5-2", "q": "According to Al 'Imran 3:187, what did they do with the covenant?", "o": ["Threw it behind their backs and took a small price", "Fulfilled it completely", "Handed it to others", "Wrote it down"], "e": "«فَنَبَذُوهُ وَرَآءَ ظُهُورِهِمْ وَٱشْتَرَوْا۟ بِهِۦ ثَمَنًۭا قَلِيلًۭا»", "r": "Q:3:187"}, {"id": "t5-3", "q": "What did the Prophet ﷺ command in Sahih al-Bukhari 3461?", "o": ["Convey from me, even one verse", "Only a scholar should speak", "Stay silent", "Only write"], "e": "«بَلِّغُوا عَنِّي وَلَوْ آيَةً»", "r": "H:bukhari:3461"}, {"id": "t5-4", "q": "According to Sahih al-Bukhari 71, what does Allah give one for whom He wants good?", "o": ["Understanding of the religion", "More wealth", "High office", "Long life"], "e": "«مَنْ يُرِدِ اللَّهُ بِهِ خَيْرًا يُفَقِّهْهُ فِي الدِّينِ»", "r": "H:bukhari:71"}, {"id": "t5-5", "q": "In Sahih al-Bukhari 118 (a Companion's words), what reason did Abu Hurayrah give for narrating hadith?", "o": ["Two verses in the Book of Allah (the warning on concealment)", "People's insistence", "Desire for fame", "The caliph's order"], "e": "«وَلَوْلاَ آيَتَانِ فِي كِتَابِ اللَّهِ مَا حَدَّثْتُ حَدِيثًا»", "r": "H:bukhari:118"}, {"id": "t5-6", "q": "According to al-Baqarah 2:159, what is the end of those who hide the guidance Allah sent down?", "o": ["Allah and those who curse curse them", "They are rewarded", "They are not questioned", "They are excused"], "e": "«أُو۟لَٰٓئِكَ يَلْعَنُهُمُ ٱللَّهُ وَيَلْعَنُهُمُ ٱللَّٰعِنُونَ»", "r": "Q:2:159-160"}, {"id": "t5-7", "q": "In al-Baqarah 2:160, who among those who hid the truth are excepted?", "o": ["Those who repent, put things right and make it clear", "The rich", "The famous", "No one"], "e": "«إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَبَيَّنُوا۟»", "r": "Q:2:159-160"}, {"id": "t5-8", "q": "What is forbidden in al-Baqarah 2:42?", "o": ["Mixing truth with falsehood and knowingly hiding it", "Reading the Book", "Asking questions", "Travelling"], "e": "«وَلَا تَلْبِسُوا۟ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُوا۟ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ»", "r": "Q:2:41-42"}, {"id": "t5-9", "q": "According to al-Baqarah 2:175, what bargain did those who hid the truth make?", "o": ["They bought error for guidance", "They bought guidance for error", "They made no bargain", "Knowledge for knowledge"], "e": "«أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَٰلَةَ بِٱلْهُدَىٰ»", "r": "Q:2:174-175"}, {"id": "t5-10", "q": "What does at-Tawbah 9:34 say about «many» of the rabbis and monks?", "o": ["They consume people's wealth unjustly and turn people from Allah's way", "All of them are righteous", "All of them are evil", "They fight in Allah's way"], "e": "«إِنَّ كَثِيرًۭا مِّنَ ٱلْأَحْبَارِ وَٱلرُّهْبَانِ لَيَأْكُلُونَ أَمْوَٰلَ ٱلنَّاسِ بِٱلْبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِ»", "r": "Q:9:34"}, {"id": "t5-11", "q": "In al-Ma'idah 5:63, what are the rabbis and scholars blamed for?", "o": ["Not forbidding people's sinful speech and unlawful gain", "Too much worship", "Travelling", "Trading"], "e": "«لَوْلَا يَنْهَىٰهُمُ ٱلرَّبَّٰنِيُّونَ وَٱلْأَحْبَارُ عَن قَوْلِهِمُ ٱلْإِثْمَ وَأَكْلِهِمُ ٱلسُّحْتَ»", "r": "Q:5:63"}, {"id": "t5-12", "q": "In al-Baqarah 2:79, for whom is there woe?", "o": ["Those who write with their hands and say, this is from Allah", "Those who write the Quran", "Those who learn", "Those who ask questions"], "e": "«فَوَيْلٌۭ لِّلَّذِينَ يَكْتُبُونَ ٱلْكِتَٰبَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَٰذَا مِنْ عِندِ ٱللَّهِ»", "r": "Q:2:79"}, {"id": "t5-13", "q": "What is forbidden in an-Nahl 16:116?", "o": ["Declaring things lawful and unlawful by one's own invention", "Eating lawful food", "Avoiding the unlawful", "Reading the Book"], "e": "«وَلَا تَقُولُوا۟ لِمَا تَصِفُ أَلْسِنَتُكُمُ ٱلْكَذِبَ هَٰذَا حَلَٰلٌۭ وَهَٰذَا حَرَامٌۭ»", "r": "Q:16:116"}, {"id": "t5-14", "q": "According to Sahih al-Bukhari 1291, what awaits one who deliberately lies about the Prophet ﷺ?", "o": ["Let him take his seat in the Fire", "He is forgiven", "Only a warning", "Nothing"], "e": "«مَنْ كَذَبَ عَلَىَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ»", "r": "H:bukhari:1291"}, {"id": "t5-15", "q": "According to Sahih al-Bukhari 100, how will Allah take away knowledge?", "o": ["By taking the scholars", "By burning books", "By snatching it from hearts", "By silencing tongues"], "e": "«وَلَكِنْ يَقْبِضُ الْعِلْمَ بِقَبْضِ الْعُلَمَاءِ»", "r": "H:bukhari:100"}, {"id": "t5-16", "q": "According to Sahih al-Bukhari 100, what happens when ignorant leaders give verdicts without knowledge?", "o": ["They go astray and lead others astray", "All are guided", "Disagreement ends", "Nothing happens"], "e": "«فَأَفْتَوْا بِغَيْرِ عِلْمٍ، فَضَلُّوا وَأَضَلُّوا»", "r": "H:bukhari:100"}, {"id": "t5-17", "q": "What attitude is questioned in al-Baqarah 2:44?", "o": ["Commanding people to good and forgetting oneself", "Praying", "Teaching the Book", "Giving charity"], "e": "«أَتَأْمُرُونَ ٱلنَّاسَ بِٱلْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ»", "r": "Q:2:44"}, {"id": "t5-18", "q": "In al-Jumu'ah 62:5, to what are those who carried the Book but did not act on it likened?", "o": ["A donkey carrying books", "A bright lamp", "A flowing river", "A strong tree"], "e": "«كَمَثَلِ ٱلْحِمَارِ يَحْمِلُ أَسْفَارًۢا»", "r": "Q:62:5"}, {"id": "t5-19", "q": "In Sahih al-Bukhari 3267, what will the man thrown into the Fire say about himself?", "o": ["I commanded you to good but did not do it", "I was ignorant", "No one told me", "I committed no sin"], "e": "«كُنْتُ آمُرُكُمْ بِالْمَعْرُوفِ وَلاَ آتِيهِ»", "r": "H:bukhari:3267"}, {"id": "t5-20", "q": "In Sahih Muslim 1905, why was the man of knowledge thrown into the Fire?", "o": ["He learned so that he would be called a scholar", "He did not teach", "He read too little", "He did not travel"], "e": "«وَلَكِنَّكَ تَعَلَّمْتَ الْعِلْمَ لِيُقَالَ عَالِمٌ»", "r": "H:muslim:1905a"}], "t6": [{"id": "t6-1", "q": "According to ar-Ra'd 13:11, when does Allah change a people's condition?", "o": ["When they change what is within themselves", "When the enemy weakens", "When time passes", "Never"], "e": "«إِنَّ ٱللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ حَتَّىٰ يُغَيِّرُوا۟ مَا بِأَنفُسِهِمْ»", "r": "Q:13:11"}, {"id": "t6-2", "q": "In al-Anfal 8:53, what does Allah not change until a people change themselves?", "o": ["A favour He bestowed on them", "The seasons", "The sun's course", "The mountains"], "e": "«لَمْ يَكُ مُغَيِّرًۭا نِّعْمَةً أَنْعَمَهَا عَلَىٰ قَوْمٍ»", "r": "Q:8:53"}, {"id": "t6-3", "q": "According to Hud 11:117, which towns does Allah not destroy unjustly?", "o": ["Those whose people are doing right", "Large ones", "Rich ones", "Old ones"], "e": "«وَمَا كَانَ رَبُّكَ لِيُهْلِكَ ٱلْقُرَىٰ بِظُلْمٍۢ وَأَهْلُهَا مُصْلِحُونَ»", "r": "Q:11:117"}, {"id": "t6-4", "q": "According to al-'Ankabut 29:40, who wronged the destroyed nations?", "o": ["They wronged themselves", "Allah", "The angels", "Other nations"], "e": "«وَمَا كَانَ ٱللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ»", "r": "Q:29:40"}, {"id": "t6-5", "q": "According to ar-Rum 30:41, why has corruption appeared on land and sea?", "o": ["Because of what people's hands have earned", "Because of fate", "By chance", "Because of the jinn"], "e": "«ظَهَرَ ٱلْفَسَادُ فِى ٱلْبَرِّ وَٱلْبَحْرِ بِمَا كَسَبَتْ أَيْدِى ٱلنَّاسِ»", "r": "Q:30:41"}, {"id": "t6-6", "q": "According to ar-Rum 30:41, what is the purpose of letting them taste it?", "o": ["That perhaps they will return", "To wipe them out", "To punish them forever", "No purpose"], "e": "«لَعَلَّهُمْ يَرْجِعُونَ»", "r": "Q:30:41"}, {"id": "t6-7", "q": "In an-Nahl 16:112, what was the ungrateful town made to taste?", "o": ["The garment of hunger and fear", "More wealth", "Peace", "Honour"], "e": "«فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلْجُوعِ وَٱلْخَوْفِ»", "r": "Q:16:112"}, {"id": "t6-8", "q": "According to al-A'raf 7:96, what opens the blessings of heaven and earth?", "o": ["Faith and mindfulness of Allah", "Only hard work", "Only trade", "Chance"], "e": "«وَلَوْ أَنَّ أَهْلَ ٱلْقُرَىٰٓ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَفَتَحْنَا عَلَيْهِم بَرَكَٰتٍۢ مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ»", "r": "Q:7:94-96"}, {"id": "t6-9", "q": "According to al-Isra' 17:16, which group transgressed in the destroyed town?", "o": ["Its affluent ones", "Orphans", "Travellers", "Prophets"], "e": "«أَمَرْنَا مُتْرَفِيهَا فَفَسَقُوا۟ فِيهَا»", "r": "Q:17:16"}, {"id": "t6-10", "q": "According to al-An'am 6:44, what was first opened to those who forgot the reminder?", "o": ["The gates of everything", "The gates of punishment", "The gates of Paradise", "Nothing"], "e": "«فَتَحْنَا عَلَيْهِمْ أَبْوَٰبَ كُلِّ شَىْءٍ»", "r": "Q:6:44"}, {"id": "t6-11", "q": "In Sahih al-Bukhari 6425, what did the Prophet ﷺ fear for his ummah?", "o": ["The world spread out and competition for it", "Poverty", "The enemy", "Famine"], "e": "«مَا الْفَقْرَ أَخْشَى عَلَيْكُمْ، وَلَكِنْ أَخْشَى عَلَيْكُمْ أَنْ تُبْسَطَ عَلَيْكُمُ الدُّنْيَا»", "r": "H:bukhari:6425"}, {"id": "t6-12", "q": "According to Sahih al-Bukhari 3475, what destroyed earlier nations?", "o": ["Letting the noble go and punishing the weak", "Too much worship", "Too little wealth", "Defeat in war"], "e": "«إِذَا سَرَقَ فِيهِمُ الشَّرِيفُ تَرَكُوهُ، وَإِذَا سَرَقَ فِيهِمُ الضَّعِيفُ أَقَامُوا عَلَيْهِ الْحَدَّ»", "r": "H:bukhari:3475"}, {"id": "t6-13", "q": "In Sahih al-Bukhari 3475, whose example did the Prophet ﷺ give for equal justice?", "o": ["His daughter Fatimah", "His uncle", "A slave", "A merchant"], "e": "«لَوْ أَنَّ فَاطِمَةَ ابْنَةَ مُحَمَّدٍ سَرَقَتْ لَقَطَعْتُ يَدَهَا»", "r": "H:bukhari:3475"}, {"id": "t6-14", "q": "According to Sahih Muslim 2578, what drove those before to shed blood and treat the forbidden as lawful?", "o": ["Greedy stinginess (ash-shuhh)", "Knowledge", "Generosity", "Worship"], "e": "«فَإِنَّ الشُّحَّ أَهْلَكَ مَنْ كَانَ قَبْلَكُمْ»", "r": "H:muslim:2578"}, {"id": "t6-15", "q": "According to al-Ma'idah 5:79, what failing of the Children of Israel is mentioned?", "o": ["They did not forbid one another from wrong", "They traded", "They travelled", "They read the Book"], "e": "«كَانُوا۟ لَا يَتَنَاهَوْنَ عَن مُّنكَرٍۢ فَعَلُوهُ»", "r": "Q:5:78-79"}, {"id": "t6-16", "q": "In the ship parable of Sahih al-Bukhari 2493, what happens if those making the hole are left alone?", "o": ["All will perish", "Only those below will perish", "Nothing", "Only those above survive"], "e": "«فَإِنْ يَتْرُكُوهُمْ وَمَا أَرَادُوا هَلَكُوا جَمِيعًا»", "r": "H:bukhari:2493"}, {"id": "t6-17", "q": "According to Sahih al-Bukhari 3346, when does ruin come even with the righteous present?", "o": ["When wickedness becomes widespread", "Never", "When rain stops", "When wealth decreases"], "e": "«نَعَمْ، إِذَا كَثُرَ الْخُبْثُ»", "r": "H:bukhari:3346"}, {"id": "t6-18", "q": "In Sahih Muslim 2890, which request of the Prophet ﷺ was withheld?", "o": ["That the ummah's violence not be among themselves", "That it not perish by famine", "That it not drown", "None was withheld"], "e": "«وَسَأَلْتُهُ أَنْ لاَ يَجْعَلَ بَأْسَهُمْ بَيْنَهُمْ فَمَنَعَنِيهَا»", "r": "H:muslim:2890a"}, {"id": "t6-19", "q": "According to al-Hajj 22:46, what is the real blindness?", "o": ["Of the hearts within the breasts", "Of the eyes", "Of the ears", "Of the hands"], "e": "«فَإِنَّهَا لَا تَعْمَى ٱلْأَبْصَٰرُ وَلَٰكِن تَعْمَى ٱلْقُلُوبُ ٱلَّتِى فِى ٱلصُّدُورِ»", "r": "Q:22:45-46"}, {"id": "t6-20", "q": "According to Ta Ha 20:124, what is the result of turning from Allah's remembrance?", "o": ["A constricted life", "Abundant provision", "Long life", "No difference"], "e": "«وَمَنْ أَعْرَضَ عَن ذِكْرِى فَإِنَّ لَهُۥ مَعِيشَةًۭ ضَنكًۭا»", "r": "Q:20:124"}], "t7": [{"id": "t7-1", "q": "According to Sahih al-Bukhari 3456, how will this ummah follow the ways of those before?", "o": ["Span by span and cubit by cubit", "It never will", "Only in good things", "Only in trade"], "e": "«شِبْرًا بِشِبْرٍ، وَذِرَاعًا بِذِرَاعٍ»", "r": "H:bukhari:3456"}, {"id": "t7-2", "q": "In Sahih al-Bukhari 3456, what did he ﷺ answer when the Companions asked «the Jews and the Christians?»", "o": ["Who else?", "No", "Only the Jews", "Only the polytheists"], "e": "«الْيَهُودَ وَالنَّصَارَى قَالَ ‏\"‏ فَمَنْ»", "r": "H:bukhari:3456"}, {"id": "t7-3", "q": "In Sahih al-Bukhari 7319, which nations are mentioned in the ummah copying earlier nations?", "o": ["Persia and Rome", "'Ad and Thamud", "Egypt and Yemen", "India and China"], "e": "«حَتَّى تَأْخُذَ أُمَّتِي بِأَخْذِ الْقُرُونِ قَبْلَهَا»", "r": "H:bukhari:7319"}, {"id": "t7-4", "q": "In Al 'Imran 3:105, this ummah is forbidden to be like whom?", "o": ["Those who split after clear proofs", "Those who emigrated", "Those who were patient", "Those who travelled"], "e": "«وَلَا تَكُونُوا۟ كَٱلَّذِينَ تَفَرَّقُوا۟ وَٱخْتَلَفُوا۟ مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْبَيِّنَٰتُ»", "r": "Q:3:105"}, {"id": "t7-5", "q": "According to al-Bayyinah 98:4, when did the People of the Book split?", "o": ["After the clear proof came to them", "Before knowledge", "Before the prophet came", "They never split"], "e": "«إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَةُ»", "r": "Q:98:4"}, {"id": "t7-6", "q": "According to al-Ma'idah 5:14, what resulted from forgetting part of the reminder?", "o": ["Enmity and hatred among them until the Day of Resurrection", "More wealth", "Unity", "Nothing"], "e": "«فَأَغْرَيْنَا بَيْنَهُمُ ٱلْعَدَاوَةَ وَٱلْبَغْضَآءَ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ»", "r": "Q:5:14"}, {"id": "t7-7", "q": "According to al-Hadid 57:16, why did the hearts of the People of the Book harden?", "o": ["A long time passed over them", "They received no knowledge", "They were poor", "They had no prophet"], "e": "«فَطَالَ عَلَيْهِمُ ٱلْأَمَدُ فَقَسَتْ قُلُوبُهُمْ»", "r": "Q:57:16"}, {"id": "t7-8", "q": "According to al-Ma'idah 5:13, what did those with hardened hearts do?", "o": ["Distorted words from their places", "Preserved the Book", "Established prayer", "Gave charity"], "e": "«يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ»", "r": "Q:5:13"}, {"id": "t7-9", "q": "What were the People of the Book forbidden in an-Nisa' 4:171?", "o": ["Excess in their religion", "Knowledge", "Trade", "Prayer"], "e": "«يَٰٓأَهْلَ ٱلْكِتَٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ»", "r": "Q:4:171"}, {"id": "t7-10", "q": "In Sahih al-Bukhari 3445, what did the Prophet ﷺ tell us to call him?", "o": ["The servant of Allah and His Messenger", "Son of God", "Owner of the unseen", "Present everywhere"], "e": "«فَقُولُوا عَبْدُ اللَّهِ وَرَسُولُهُ»", "r": "H:bukhari:3445"}, {"id": "t7-11", "q": "In Sahih Muslim 531, at his death, what act of the Jews and Christians did the Prophet ﷺ curse?", "o": ["Taking the prophets' graves as places of prostration", "Trading", "Travelling", "Writing books"], "e": "«اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ»", "r": "H:muslim:531"}, {"id": "t7-12", "q": "In Sahih Muslim 532, what did the Prophet ﷺ forbid five days before his death?", "o": ["Taking graves as places of prostration", "Visiting graves", "Supplication", "Charity"], "e": "«أَلاَ فَلاَ تَتَّخِذُوا الْقُبُورَ مَسَاجِدَ»", "r": "H:muslim:532"}, {"id": "t7-13", "q": "According to at-Tawbah 9:31, whom did the People of the Book take as lords besides Allah?", "o": ["Their rabbis and monks", "Their kings", "The stars", "Their children"], "e": "«ٱتَّخَذُوٓا۟ أَحْبَارَهُمْ وَرُهْبَٰنَهُمْ أَرْبَابًۭا مِّن دُونِ ٱللَّهِ»", "r": "Q:9:31"}, {"id": "t7-14", "q": "According to al-Baqarah 2:75, what did a party do with Allah's words?", "o": ["Knowingly distorted them after understanding them", "Memorised them", "Never heard them", "Conveyed them to others"], "e": "«ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَمُونَ»", "r": "Q:2:75"}, {"id": "t7-15", "q": "In Sahih al-Bukhari 7363 (a Companion's words), what quality of our Book did Ibn 'Abbas mention?", "o": ["You read it pure and unmixed", "It is the oldest", "It is only for scholars", "It is in Hebrew"], "e": "«تَقْرَءُونَهُ مَحْضًا لَمْ يُشَبْ»", "r": "H:bukhari:7363"}, {"id": "t7-16", "q": "According to Sahih al-Bukhari 4485, what is the ruling on what the People of the Book relate?", "o": ["Neither believe nor deny them", "Believe all of it", "Deny all of it", "Write it down"], "e": "«لاَ تُصَدِّقُوا أَهْلَ الْكِتَابِ وَلاَ تُكَذِّبُوهُمْ»", "r": "H:bukhari:4485"}, {"id": "t7-17", "q": "What question was put to the Children of Israel in al-Baqarah 2:85?", "o": ["Do you believe in part of the Book and disbelieve in part?", "Have you read the Book?", "Will you emigrate?", "Do you pray?"], "e": "«أَفَتُؤْمِنُونَ بِبَعْضِ ٱلْكِتَٰبِ وَتَكْفُرُونَ بِبَعْضٍۢ»", "r": "Q:2:85"}, {"id": "t7-18", "q": "According to Al 'Imran 3:23, what happened when they were called to the Book of Allah for judgement?", "o": ["A party of them turned away", "All accepted", "All emigrated", "They wept"], "e": "«ثُمَّ يَتَوَلَّىٰ فَرِيقٌۭ مِّنْهُمْ وَهُم مُّعْرِضُونَ»", "r": "Q:3:23"}, {"id": "t7-19", "q": "According to al-Ma'idah 5:66, what would have happened had the People of the Book upheld their Books?", "o": ["They would have eaten from above and beneath their feet", "They would have weakened", "Nothing", "They would have split"], "e": "«لَأَكَلُوا۟ مِن فَوْقِهِمْ وَمِن تَحْتِ أَرْجُلِهِم»", "r": "Q:5:66"}], "t8": [{"id": "t8-1", "q": "In Al 'Imran 3:103, what is the first command for avoiding division?", "o": ["Hold the rope of Allah all together", "Let everyone choose his own way", "Hold to your own group", "Keep arguing"], "e": "«وَٱعْتَصِمُوا۟ بِحَبْلِ ٱللَّهِ جَمِيعًۭا وَلَا تَفَرَّقُوا۟»", "r": "Q:3:103"}, {"id": "t8-2", "q": "According to al-An'am 6:153, what is the result of following other paths?", "o": ["They separate you from Allah's path", "They reach the goal sooner", "They are all the same", "No difference"], "e": "«وَلَا تَتَّبِعُوا۟ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِۦ»", "r": "Q:6:153"}, {"id": "t8-3", "q": "According to an-Nisa' 4:59, what should be done when there is disagreement?", "o": ["Refer it to Allah and the Messenger", "Decide by majority", "Draw lots", "Leave it"], "e": "«فَإِن تَنَٰزَعْتُمْ فِى شَىْءٍۢ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ»", "r": "Q:4:59"}, {"id": "t8-4", "q": "According to ash-Shura 42:10, with whom is the judgement of what you differ over?", "o": ["With Allah", "With the majority", "With the king", "With no one"], "e": "«وَمَا ٱخْتَلَفْتُمْ فِيهِ مِن شَىْءٍۢ فَحُكْمُهُۥٓ إِلَى ٱللَّهِ»", "r": "Q:42:10"}, {"id": "t8-5", "q": "According to an-Nisa' 4:83, what should have been done instead of spreading the news?", "o": ["Refer it to the Messenger and those in authority", "Spread it at once", "Hide it", "Change it"], "e": "«وَلَوْ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُو۟لِى ٱلْأَمْرِ مِنْهُمْ»", "r": "Q:4:83"}, {"id": "t8-6", "q": "In Sahih al-Bukhari 4119, how did the Prophet ﷺ react to the Companions' difference over 'Asr?", "o": ["He blamed none of them", "He blamed one group", "He blamed both", "He ordered the prayer repeated"], "e": "«فَلَمْ يُعَنِّفْ وَاحِدًا مِنْهُمْ»", "r": "H:bukhari:4119"}, {"id": "t8-7", "q": "In Sahih al-Bukhari 2410, what did the Prophet ﷺ say about the two different recitations?", "o": ["Both of you are right", "One is wrong", "Both are wrong", "Stop reciting"], "e": "«كِلاَكُمَا مُحْسِنٌ»", "r": "H:bukhari:2410"}, {"id": "t8-8", "q": "According to Sahih al-Bukhari 6103, what happens if a man calls his brother «O disbeliever»?", "o": ["It returns to one of the two", "No harm", "It is a good deed", "Only the listener sins"], "e": "«فَقَدْ بَاءَ بِهِ أَحَدُهُمَا»", "r": "H:bukhari:6103"}, {"id": "t8-9", "q": "In Sahih al-Bukhari 391, which outward marks of a Muslim are named?", "o": ["Our prayer, our qiblah and our slaughtered meat", "Our group's name", "Our dress", "Our region"], "e": "«مَنْ صَلَّى صَلاَتَنَا، وَاسْتَقْبَلَ قِبْلَتَنَا، وَأَكَلَ ذَبِيحَتَنَا»", "r": "H:bukhari:391"}, {"id": "t8-10", "q": "In Sahih Muslim 96, what did the Prophet ﷺ ask Usama?", "o": ["Did you split open his heart?", "Did you recognise him?", "Did you greet him?", "Did you take his wealth?"], "e": "«أَفَلاَ شَقَقْتَ عَنْ قَلْبِهِ»", "r": "H:muslim:96a"}, {"id": "t8-11", "q": "What is the ruling in an-Nisa' 4:94 about one who offers peace?", "o": ["Do not say to him, you are not a believer", "Demand proof from him", "Ignore him", "Ask him his group"], "e": "«وَلَا تَقُولُوا۟ لِمَنْ أَلْقَىٰٓ إِلَيْكُمُ ٱلسَّلَٰمَ لَسْتَ مُؤْمِنًۭا»", "r": "Q:4:94"}, {"id": "t8-12", "q": "According to al-Hujurat 49:6, what should you do if a wrongdoer brings news?", "o": ["Verify it", "Accept it at once", "Spread it at once", "Punish him"], "e": "«إِن جَآءَكُمْ فَاسِقٌۢ بِنَبَإٍۢ فَتَبَيَّنُوٓا۟»", "r": "Q:49:6"}, {"id": "t8-13", "q": "What is forbidden in al-Hujurat 49:11?", "o": ["Mocking, fault-finding and insulting labels", "Greeting", "Meeting", "Reconciling"], "e": "«وَلَا تَلْمِزُوٓا۟ أَنفُسَكُمْ وَلَا تَنَابَزُوا۟ بِٱلْأَلْقَٰبِ»", "r": "Q:49:11"}, {"id": "t8-14", "q": "According to Sahih al-Bukhari 10, who is the Muslim?", "o": ["One from whose tongue and hand Muslims are safe", "One who wins debates", "One whose group is large", "One who talks much"], "e": "«الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ»", "r": "H:bukhari:10"}, {"id": "t8-15", "q": "According to Sahih al-Bukhari 48, what is abusing a Muslim?", "o": ["Wickedness (fusuq)", "Permissible", "Recommended", "A trivial matter"], "e": "«سِبَابُ الْمُسْلِمِ فُسُوقٌ، وَقِتَالُهُ كُفْرٌ»", "r": "H:bukhari:48"}, {"id": "t8-16", "q": "In Sahih al-Bukhari 121, what warning was given at the Farewell Pilgrimage?", "o": ["Do not become disbelievers after me, striking one another's necks", "Give up trade", "Do not travel", "Do not leave Makkah"], "e": "«لاَ تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ»", "r": "H:bukhari:121"}, {"id": "t8-17", "q": "According to al-Hujurat 49:10, what are the believers to each other, and what is the command?", "o": ["Brothers; make peace between them", "Rivals; compete", "Strangers; keep away", "No relation"], "e": "«إِنَّمَا ٱلْمُؤْمِنُونَ إِخْوَةٌۭ فَأَصْلِحُوا۟ بَيْنَ أَخَوَيْكُمْ»", "r": "Q:49:10"}, {"id": "t8-18", "q": "In Sahih Muslim 54, what way is given to increase mutual love?", "o": ["Spread the greeting of peace among you", "Argue", "Stay apart", "Give no gifts"], "e": "«أَفْشُوا السَّلاَمَ بَيْنَكُمْ»", "r": "H:muslim:54a"}, {"id": "t8-19", "q": "In the prayer of al-Hashr 59:10, what is asked for the heart?", "o": ["No rancour in it towards the believers", "Victory over enemies", "More wealth", "Long life"], "e": "«وَلَا تَجْعَلْ فِى قُلُوبِنَا غِلًّۭا لِّلَّذِينَ ءَامَنُوا۟»", "r": "Q:59:10"}, {"id": "t8-20", "q": "According to an-Nahl 16:125, how should one call to Allah's way?", "o": ["With wisdom, good admonition and the best argument", "With harshness and taunts", "By force", "By silence"], "e": "«ٱدْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلْحِكْمَةِ وَٱلْمَوْعِظَةِ ٱلْحَسَنَةِ»", "r": "Q:16:125"}], "t9": [{"id": "t9-1", "q": "According to ash-Shams 91:9, who is successful?", "o": ["The one who purifies the soul", "The one who amasses wealth", "The one whose group is large", "The one who wins debates"], "e": "«قَدْ أَفْلَحَ مَن زَكَّىٰهَا»", "r": "Q:91:7-10"}, {"id": "t9-2", "q": "According to ash-Shams 91:10, who has failed?", "o": ["The one who corrupts the soul", "The one who stayed poor", "The one who travelled", "The one who stayed silent"], "e": "«وَقَدْ خَابَ مَن دَسَّىٰهَا»", "r": "Q:91:7-10"}, {"id": "t9-3", "q": "In al-A'la 87:14-15, what deeds of the successful one are mentioned?", "o": ["He purified himself, remembered his Lord's name and prayed", "He earned money and built a house", "He travelled and traded", "He argued and won"], "e": "«قَدْ أَفْلَحَ مَن تَزَكَّىٰ» «وَذَكَرَ ٱسْمَ رَبِّهِۦ فَصَلَّىٰ»", "r": "Q:87:14-15"}, {"id": "t9-4", "q": "According to Fatir 35:18, for whom does one who purifies himself do so?", "o": ["For his own soul", "For his group", "For his teacher", "For show"], "e": "«وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفْسِهِۦ»", "r": "Q:35:18"}, {"id": "t9-5", "q": "In al-Jumu'ah 62:2, what is included in the Messenger's ﷺ work?", "o": ["Reciting verses, purifying, and teaching the Book and wisdom", "Only governing", "Only trade", "Only war"], "e": "«يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ»", "r": "Q:62:2"}, {"id": "t9-6", "q": "According to at-Tawbah 9:103, what is one purpose of taking charity?", "o": ["To cleanse and purify them", "To fill the treasury", "Fame", "Competition"], "e": "«صَدَقَةًۭ تُطَهِّرُهُمْ وَتُزَكِّيهِم بِهَا»", "r": "Q:9:103"}, {"id": "t9-7", "q": "According to Sahih al-Bukhari 52, which piece makes the whole body sound when it is sound?", "o": ["The heart", "The brain", "The tongue", "The eye"], "e": "«أَلاَ وَهِيَ الْقَلْبُ»", "r": "H:bukhari:52"}, {"id": "t9-8", "q": "According to Sahih Muslim 2564, what does Allah look at?", "o": ["Hearts and deeds", "Forms", "Wealth", "Lineage"], "e": "«وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ»", "r": "H:muslim:2564c"}, {"id": "t9-9", "q": "According to ash-Shu'ara' 26:89, what will benefit on the Day of Resurrection?", "o": ["A sound heart", "Wealth", "Children", "One's group"], "e": "«إِلَّا مَنْ أَتَى ٱللَّهَ بِقَلْبٍۢ سَلِيمٍۢ»", "r": "Q:26:88-89"}, {"id": "t9-10", "q": "According to Sahih al-Bukhari 1, what do deeds depend on?", "o": ["Intentions", "Fame", "Numbers", "Lineage"], "e": "«إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ»", "r": "H:bukhari:1"}, {"id": "t9-11", "q": "What is forbidden in an-Najm 53:32?", "o": ["Claiming oneself pure", "Repentance", "Prayer", "Charity"], "e": "«فَلَا تُزَكُّوٓا۟ أَنفُسَكُمْ ۖ هُوَ أَعْلَمُ بِمَنِ ٱتَّقَىٰٓ»", "r": "Q:53:32"}, {"id": "t9-12", "q": "According to an-Nur 24:21, what if not for Allah's grace?", "o": ["No one would ever have been pure", "All would purify themselves", "No difference", "Only scholars would be pure"], "e": "«وَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنْ أَحَدٍ أَبَدًۭا»", "r": "Q:24:21"}, {"id": "t9-13", "q": "In the prayer of Sahih Muslim 2722, what did the Prophet ﷺ ask for his soul?", "o": ["Mindfulness and purity", "Wealth and fame", "Rule", "Long life"], "e": "«اللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا وَزَكِّهَا»", "r": "H:muslim:2722"}, {"id": "t9-14", "q": "What does al-Hujurat 49:12 command us to avoid?", "o": ["Suspicion, spying and backbiting", "Greeting and meeting", "Prayer and fasting", "Knowledge and teaching"], "e": "«ٱجْتَنِبُوا۟ كَثِيرًۭا مِّنَ ٱلظَّنِّ إِنَّ» «وَلَا تَجَسَّسُوا۟ وَلَا يَغْتَب بَّعْضُكُم بَعْضًا»", "r": "Q:49:12"}, {"id": "t9-15", "q": "According to Sahih al-Bukhari 6114, who is truly strong?", "o": ["One who controls himself in anger", "One who wins at wrestling", "One who has an army", "One who speaks loudly"], "e": "«إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ»", "r": "H:bukhari:6114"}, {"id": "t9-16", "q": "According to Sahih Muslim 2588, what happens to one who humbles himself for Allah?", "o": ["Allah raises him", "He is disgraced", "He suffers loss", "Nothing"], "e": "«وَمَا تَوَاضَعَ أَحَدٌ لِلَّهِ إِلاَّ رَفَعَهُ اللَّهُ»", "r": "H:muslim:2588"}, {"id": "t9-17", "q": "According to an-Nazi'at 79:40-41, whose refuge is Paradise?", "o": ["One who feared his Lord and restrained the soul from desire", "One who followed desire", "One who was merely rich", "One whose group was large"], "e": "«وَنَهَى ٱلنَّفْسَ عَنِ ٱلْهَوَىٰ»", "r": "Q:79:40-41"}, {"id": "t9-18", "q": "According to Sahih al-Bukhari 6487, with what is Paradise veiled?", "o": ["Things disliked", "Desires", "Wealth", "Play"], "e": "«وَحُجِبَتِ الْجَنَّةُ بِالْمَكَارِهِ»", "r": "H:bukhari:6487"}, {"id": "t9-19", "q": "In Sahih al-Bukhari 6407, what is the example of one who remembers and one who does not?", "o": ["The living and the dead", "Rich and poor", "Scholar and ignorant", "King and slave"], "e": "«مَثَلُ الْحَىِّ وَالْمَيِّتِ»", "r": "H:bukhari:6407"}, {"id": "t9-20", "q": "According to Sahih al-Bukhari 50, what is ihsan?", "o": ["To worship Allah as though you see Him", "Only giving charity", "Only learning", "Reminding people of favours"], "e": "«أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ»", "r": "H:bukhari:50"}]};
